                else
                {
                    //Armor   PLATE AND CHAIN completely tested 46-100in dungeons///////
                    if (playerLevel == 46) hp += 2;
                    if (playerLevel == 47) hp += 1;
                    if (playerLevel == 48) hp += 1;
