                    if (playerLevel >= 55) hp -= 1;
                    if (playerLevel >= 56) hp -= 1;
                    if (playerLevel >= 58) hp -= 1;
                    if (playerLevel >= 59) hp += 1;
                    if (playerLevel >= 60) hp -= 1;
                    if (playerLevel >= 63) hp -= 1;
