                    if (playerLevel >= 74) hp -= 1;
                    if (playerLevel >= 75) hp += 1;
                    if (playerLevel >= 76) hp -= 1;
                    if (playerLevel >= 78) hp -= 1;
                    if (playerLevel >= 81) hp -= 1;
                    if (playerLevel >= 83) hp -= 1;
                    if (playerLevel >= 87) hp -= 1;
                    if (playerLevel >= 90) hp -= 1;
