                    if (playerLevel >= 92) hp -= 1;
                    if (playerLevel >= 94) hp -= 1;
                    if (playerLevel >= 96) hp -= 1;
                    if (playerLevel >= 99) hp -= 1;
                }
                int endOffset = Math.Min(2 + (playerLevel - 50) / 7, 3);
                int primPool = 20 + (itemLevel + endOffset) * 1090 / 109;
                int end;
                // Crystal and Splint armor both use 0.8 End - same formula
                if (isCrystal || isSplint)
                {
                    int crystalEndOffset = Math.Min(endOffset + 2, 3);
                    int crystalPrimPool = 20 + (itemLevel + crystalEndOffset) * 1090 / 109;
                    end = crystalPrimPool * 4 / 25;
                    if (playerLevel == 39 || playerLevel == 42 || playerLevel == 44 || playerLevel == 47 || playerLevel == 52) end -= 1;
                    if (playerLevel == 65 || playerLevel == 70 || playerLevel == 73 || playerLevel == 75 || playerLevel == 76 ||
                        playerLevel == 78 || (playerLevel >= 80 && playerLevel != 82 && playerLevel != 87)) end += 1;
