        }

        private bool WritePlayerEntitySynchNoFlush(RRConnection conn, LEWriter writer)
        {
            return TryWritePlayerEntitySynch(conn, writer, SyncContext.PlayerActionResponse, "WritePlayerEntitySynchNoFlush", true, false);
        }

        private bool WritePlayerEntitySynchNoCombatFlush(RRConnection conn, LEWriter writer)
        {
            return TryWritePlayerEntitySynch(conn, writer, SyncContext.PlayerActionResponse, "WritePlayerEntitySynchNoCombatFlush", true, false);
        }

        private bool TryWritePlayerEntitySynch(RRConnection conn, LEWriter writer, SyncContext context, string packetName, bool advanceClientSync, bool flushCombat)
        {
            if (writer == null) return false;
            if (flushCombat)
            {
                GetNativeValidationCutoff(out _, out float validationCutoffTime);
                FlushCombatBeforeSynch(conn, validationCutoffTime);
            }

            if (TryResolveWriterComponentUpdate(conn, writer, out ushort componentId, out byte subtype))
                return TryWriteEntitySynchForComponent(conn, writer, componentId, subtype, context, packetName, advanceClientSync);

            if (!TryResolvePlayerSynchronizedHP(conn, context, packetName, advanceClientSync, out uint hpWire))
            {
                Debug.LogError($"[SYNC-SUFFIX-UNRESOLVED] packet={packetName} context={context} owner=Avatar reason=player-hp-unresolved");
                return false;
            }

            GetNativeValidationCutoff(out uint fallbackCutoffTick, out float fallbackCutoffTime);
            // CORRECTED 2026-05-25: [+0x2F0] is CurrentHPWire, NOT MaxHP cache. Send the resolved runtime HP, not MaxHP.
            uint avatarSuffixHPWire = hpWire;
            return TryWriteResolvedEntitySynchInfo(writer, 0, 0, context, packetName, EntitySynchInfoDecision.HP(EntitySynchInfoOwner.Avatar, avatarSuffixHPWire, packetName, conn?.Avatar != null ? (uint)conn.Avatar.Id : 0u, 0, 0, GetNativeCombatNow(), $"player-fallback; validationCutoffTick={fallbackCutoffTick} validationCutoffTime={fallbackCutoffTime:F3}", fallbackCutoffTick, fallbackCutoffTime));
        }

        private bool TryWriteEntitySynchForComponent(RRConnection conn, LEWriter writer, ushort componentId, byte subtype, string tag, bool advanceClientSync)
        {
            return TryWriteEntitySynchForComponent(conn, writer, componentId, subtype, SyncContextFromTag(tag), tag, advanceClientSync);
        }

        private static uint ResolveAuthoredUnitMaxHealthWire(string gcType, uint fallbackHPWire = NativeNonCombatInteractiveHPWire)
        {
            if (string.IsNullOrEmpty(gcType) || GCDatabase.Instance == null || !GCDatabase.Instance.IsLoaded)
                return fallbackHPWire;

            var node = GCDatabase.Instance.ResolveWithInheritance(gcType);
            var desc = node?.GetChild("Description") ?? node;
            if (desc == null || !desc.HasProperty("MaxHealth"))
                return fallbackHPWire;

            float maxHealth = desc.GetFloat("MaxHealth", fallbackHPWire / 256f);
            if (maxHealth <= 0f || float.IsNaN(maxHealth) || float.IsInfinity(maxHealth))
                return fallbackHPWire;

            return (uint)Mathf.Max(1, Mathf.RoundToInt(maxHealth * 256f));
        }

        private static void WriteNonCombatInteractiveEntitySynchInfo(LEWriter writer, string gcType = null)
        {
            uint hpWire = ResolveAuthoredUnitMaxHealthWire(gcType);
            writer.WriteByte(0x02);
            writer.WriteUInt32(hpWire);
            Debug.LogError($"[SYNC-SUFFIX] packet=NCI owner=NonCombatInteractive gc={gcType ?? "<default>"} flags=0x02 hp={hpWire}");
        }

        private bool TryWriteEntitySynchForComponent(RRConnection conn, LEWriter writer, ushort componentId, byte subtype, SyncContext context, string packetName, bool advanceClientSync)
        {
            if (advanceClientSync && IsAvatarHPSyncComponentId(conn, componentId))
            {
                GetNativeValidationCutoff(out _, out float validationCutoffTime);
                FlushCombatBeforeSynch(conn, validationCutoffTime);
            }
            if (!ResolveEntitySynchInfoForComponent(conn, componentId, subtype, context, 0, packetName, advanceClientSync, out EntitySynchInfoDecision decision))
            {
                Debug.LogError($"[SYNC-SUFFIX-UNRESOLVED] packet={packetName} context={context} component={componentId} sub=0x{subtype:X2} owner={decision.Owner} reason={decision.Reason}");
                return false;
            }

            return TryWriteResolvedEntitySynchInfo(writer, componentId, subtype, context, packetName, decision);
        }

        // S11.3 / Path γ kill-switch — DEFAULT FALSE after live test 2026-05-27 showed
        // stripping the HP bit makes things worse, not better. The client's Validate
        // UNCONDITIONALLY compares streamed [+0x18] to local entity [+0x2F0] regardless
        // of our flag — stripping the bit makes us send HP=0, which mismatches a healthy
        // entity at max HP and fires popup on every spawn. Pre-γ behavior was at least
        // correct when no damage had been taken. Keep false unless you have a specific
        // reason to test.
        public static bool SuppressAvatarHPSuffix = false;

        private bool TryWriteResolvedEntitySynchInfo(LEWriter writer, ushort componentId, byte subtype, SyncContext context, string packetName, EntitySynchInfoDecision decision)
        {
            if (!decision.Allow)
            {
                Debug.LogError($"[SYNC-SUFFIX-BLOCK] packet={packetName} context={context} component={componentId} sub=0x{subtype:X2} owner={decision.Owner} reason={decision.Reason}");
                return false;
            }

            // Path γ: strip HP bit from Avatar suffix so client's Validate skips HP check.
            if (SuppressAvatarHPSuffix && decision.Owner == EntitySynchInfoOwner.Avatar && (decision.Flags & 0x02) != 0)
            {
                decision.Flags = (byte)(decision.Flags & ~0x02);  // clear HP bit
                decision.HPWire = 0u;                              // zero HP value (not sent anyway)
                decision.Reason = (decision.Reason ?? "") + "; pathγ-strip-hp";
            }

            if (decision.Owner == EntitySynchInfoOwner.Avatar && (decision.Flags & 0x02) == 0 && !ShouldKeepPlayerComponentSyncEmpty(context) && !SuppressAvatarHPSuffix)
            {
                Debug.LogError($"[SYNC-SUFFIX-BLOCK] Avatar suffix without HP packet={packetName} context={context} component={componentId} sub=0x{subtype:X2} flags=0x{decision.Flags:X2} reason={decision.Reason}");
                return false;
            }

            if (decision.Owner == EntitySynchInfoOwner.Monster && (decision.Flags & 0x02) == 0)
            {
                if (!ShouldKeepMonsterComponentSyncEmpty(context, packetName))
                {
                    Debug.LogError($"[SYNC-SUFFIX-BLOCK] Monster suffix without HP packet={packetName} context={context} component={componentId} sub=0x{subtype:X2} flags=0x{decision.Flags:X2} reason={decision.Reason}");
                    return false;
                }
            }

            new EntitySynchInfoPayload(decision.Flags, decision.HPWire).Write(writer);

            if (VerboseSynchLogging || decision.Owner == EntitySynchInfoOwner.Avatar || decision.Owner == EntitySynchInfoOwner.Monster || decision.Owner == EntitySynchInfoOwner.NonUnit)
            {
                string hpText = (decision.Flags & 0x02) != 0 ? decision.HPWire.ToString() : "none";
                Debug.LogError($"[SYNC-SUFFIX] packet={packetName} context={context} component={componentId} sub=0x{subtype:X2} owner={decision.Owner} ownerEntity={decision.OwnerEntityId} flags=0x{decision.Flags:X2} hp={hpText} nativeNow={decision.NativeNow:F3} cutoffTick={decision.ValidationCutoffTick} cutoffTime={decision.ValidationCutoffTime:F3} reason={decision.Reason} provenance={decision.Provenance}");
            }
            return true;
        }

        private bool TryWriteResolvedEntitySynchInfo(LEWriter writer, ushort componentId, byte subtype, SyncContext context, string packetName, uint ownerEntityId, EntitySynchInfoDecision decision)
        {
            return TryWriteResolvedEntitySynchInfo(writer, componentId, subtype, context, packetName, decision);
        }

        private bool TryWriteRemoteAvatarEntitySynchInfo(RRConnection sourceConn, LEWriter writer, ushort componentId, byte subtype, string packetName)
        {
            if (!TryResolvePlayerSynchronizedHP(sourceConn, SyncContext.PlayerActionResponse, packetName, false, out uint hpWire))
            {
                Debug.LogError($"[SYNC-SUFFIX-UNRESOLVED] packet={packetName} owner=RemoteAvatar reason=player-hp-unresolved");
                return false;
            }

            string source = sourceConn?.LoginName ?? "unknown";
            GetNativeValidationCutoff(out uint validationCutoffTick, out float validationCutoffTime);
            return TryWriteResolvedEntitySynchInfo(writer, componentId, subtype, SyncContext.PlayerActionResponse, packetName, EntitySynchInfoDecision.HP(EntitySynchInfoOwner.Avatar, hpWire, $"{packetName} source={source}", sourceConn?.Avatar != null ? (uint)sourceConn.Avatar.Id : 0u, componentId, subtype, GetNativeCombatNow(), $"remote-avatar; validationCutoffTick={validationCutoffTick} validationCutoffTime={validationCutoffTime:F3}", validationCutoffTick, validationCutoffTime));
        }

        private bool ResolveEntitySynchInfoForComponent(RRConnection conn, ushort componentId, byte subtype, SyncContext context, uint ownerEntityId, string packetName, bool advanceClientSync, out EntitySynchInfoDecision decision)
        {
            decision = EntitySynchInfoDecision.Empty(EntitySynchInfoOwner.Unknown, packetName);

            if (conn == null || (componentId == 0 && ownerEntityId == 0))
                return true;

            if (IsNonUnitPlayerComponentId(conn, componentId))
            {
                decision = EntitySynchInfoDecision.Empty(EntitySynchInfoOwner.NonUnit, $"{packetName} non-unit-player-component");
                return true;
            }

            RegisterHpSyncPlayer(conn);
            Monster monster = ResolveMonsterForComponent(componentId, ownerEntityId);
            if (monster != null)
            {
                HpSyncService.Instance.RegisterMonster(monster);
                string monsterPacketName = $"{packetName} context={context} cid={componentId} sub=0x{subtype:X2} owner={monster.EntityId}";
                float suffixNativeNow = GetNativeCombatNow();
                GetNativeValidationCutoff(out uint validationCutoffTick, out float validationCutoffTime);
                FlushMonsterRuntimeBeforeSynch(conn, monster, context, monsterPacketName, validationCutoffTime, suffixNativeNow, validationCutoffTick);
                PrimeMonsterHPBeforeSync(monster, validationCutoffTime);
                if (!CombatManager.Instance.TryResolveMonsterSynchronizedHP(monster, context, monsterPacketName, validationCutoffTime, out uint monsterHPWire, out string monsterHPReason))
                {
                    if (ShouldKeepMonsterComponentSyncEmpty(context, packetName))
                    {
                        decision = EntitySynchInfoDecision.Empty(EntitySynchInfoOwner.Monster, monsterPacketName);
                        return true;
                    }
                    monsterHPWire = CombatManager.Instance.PeekMonsterCurrentHPWire(monster);
                    monsterHPReason = $"{monsterHPReason}; direct-runtime-hp";
                    Debug.LogError($"[SYNC-SUFFIX-RECOVER] packet={packetName} owner=Monster entity={monster.EntityId} hp={monsterHPWire} reason={monsterHPReason}");
                }

                // Monster Path C auto-refresh removed Stage 0 cleanup 2026-05-27. HP sync flows
                // via EntitySynchInfo suffix on natural 0x35 packets (set below). Server's monster
                // HP becomes wire-truthful once the combat simulator (proposal Stage 3) makes
                // PlayerState._currentHPWire authoritative. Death-refresh HP=0 path still lives
                // at UGS:~10508 and uses the trimmed BuildMonsterEntityInitHPRefreshPacket.
                HpSyncService.Instance.RecordMonsterOutboundHP(monster, monsterHPWire, monsterPacketName);
                string provenance = $"{monsterHPReason}; validationCutoffTick={validationCutoffTick} validationCutoffTime={validationCutoffTime:F3}";
                uint suffixHPWire = monsterHPWire;
                decision = EntitySynchInfoDecision.HP(EntitySynchInfoOwner.Monster, suffixHPWire, $"{monsterPacketName} {monsterHPReason}", monster.EntityId, componentId != 0 ? componentId : monster.BehaviorId, subtype, suffixNativeNow, provenance, validationCutoffTick, validationCutoffTime);
                return true;
            }

            if (conn.Avatar != null && !IsZoneSpawnInvulnerabilityBlockingCombat(conn))
                FlushWeaponCycleBeforeSynch(conn, $"ResolveEntitySynchInfo:{packetName}", false);

            if (!IsAvatarHPSyncComponentId(conn, componentId))
            {
                decision = EntitySynchInfoDecision.Empty(EntitySynchInfoOwner.Unknown, packetName);
                return true;
            }

            if (!TryResolvePlayerSynchronizedHP(conn, context, packetName, advanceClientSync, out uint avatarHPWire))
            {
                var state = GetPlayerState(conn.ConnId.ToString());
                avatarHPWire = state != null ? state.SynchHP : 0;
                Debug.LogError($"[SYNC-SUFFIX-RECOVER] packet={packetName} owner=Avatar component={componentId} hp={avatarHPWire} reason=avatar-hp-unresolved");
            }

            GetNativeValidationCutoff(out uint avatarCutoffTick, out float avatarCutoffTime);

            // Avatar Path C auto-refresh removed Stage 0 cleanup 2026-05-27. The Option A
            // investigation proved it was firing with state.SynchHP=MaxHP between client HP
            // reports (server had no way to track monster→player damage) — every refresh wrote
            // MaxHP into client's [Avatar+0x2F0], guaranteeing the next 0x35 suffix Validate
            // failure when client's local damage had reduced its real HP. Suffix carries the
            // resolved avatar HP; once the simulator (proposal Stage 3) makes server-side
            // PlayerState._currentHPWire authoritative, the suffix will match client truth.
            uint avatarSuffixHPWire = avatarHPWire;
            decision = EntitySynchInfoDecision.HP(EntitySynchInfoOwner.Avatar, avatarSuffixHPWire, packetName, conn.Avatar != null ? (uint)conn.Avatar.Id : 0u, componentId, subtype, GetNativeCombatNow(), $"avatar-hp; validationCutoffTick={avatarCutoffTick} validationCutoffTime={avatarCutoffTime:F3}", avatarCutoffTick, avatarCutoffTime);
            return true;
        }

        private bool TryResolveWriterComponentUpdate(RRConnection conn, LEWriter writer, out ushort componentId, out byte subtype)
        {
            componentId = 0;
            subtype = 0;
            byte[] data = writer?.GetBuffer();
            if (data == null || data.Length < 3) return false;

            bool found = false;
            for (int i = 0; i + 2 < data.Length; i++)
            {
                byte opcode = data[i];
                if (opcode != 0x35 && opcode != 0x36) continue;
                if (opcode == 0x35 && i + 3 >= data.Length) continue;
                ushort cid = (ushort)(data[i + 1] | (data[i + 2] << 8));
                bool knownPlayerComponent = IsAvatarHPSyncComponentId(conn, cid)
                    || IsNonUnitPlayerComponentId(conn, cid);
                if (!knownPlayerComponent && ResolveMonsterForComponent(cid, 0) == null)
                    continue;
                componentId = cid;
                subtype = opcode == 0x35 ? data[i + 3] : (byte)0;
                found = true;
            }

            return found;
        }

        private Monster ResolveMonsterForComponent(uint componentId, uint ownerEntityId)
        {
            if (CombatManager.Instance == null) return null;
            Monster monster = null;
            if (componentId != 0)
            {
                monster = CombatManager.Instance.GetMonsterByComponent(componentId)
                    ?? CombatManager.Instance.GetMonsterByBehaviorId(componentId)
                    ?? CombatManager.Instance.GetMonsterBySkillsId(componentId)
                    ?? CombatManager.Instance.GetMonsterByManipulatorsId(componentId);
            }
            if (monster == null && ownerEntityId != 0)
                monster = CombatManager.Instance.GetMonster(ownerEntityId);
            return monster;
        }

        private static SyncContext SyncContextFromTag(string tag)
        {
            if (string.IsNullOrEmpty(tag)) return SyncContext.Unknown;
            switch (tag)
            {
                case "WorldInterval": return SyncContext.WorldInterval;
                case "WorldRuntimeBootstrap": return SyncContext.BootstrapReplay;
                case "WorldRuntimeRecoveryReplay": return SyncContext.RecoveryReplay;
                case "WorldRuntimeRepeatResync": return SyncContext.RepeatResync;
                case "WorldRuntimeInventorySync": return SyncContext.InventoryReplay;
                case "WorldRuntimeEquipResync": return SyncContext.EquipmentReplay;
                case "WorldLateArmorSync": return SyncContext.LateArmorSync;
                case "WorldUnitBehaviorControlGrant": return SyncContext.ControlGrant;
                case "WorldUnitBehaviorControlAck": return SyncContext.ControlAck;
                case "WorldMoverAck": return SyncContext.MoverAck;
                case "PlayerBasicAttackResponse": return SyncContext.PlayerBasicAttackResponse;
            }
            if (tag.StartsWith("MON-ATTACK", StringComparison.Ordinal)) return SyncContext.MonsterAction;
            if (tag.StartsWith("MON-MOVE", StringComparison.Ordinal)) return SyncContext.MonsterMove;
            if (tag.StartsWith("DAMAGE-HP", StringComparison.Ordinal)) return SyncContext.MonsterDamage;
            if (tag.Contains("Inventory")) return SyncContext.InventoryReplay;
            if (tag.Contains("Equip")) return SyncContext.EquipmentReplay;
            return SyncContext.PlayerActionResponse;
        }

        private static bool ShouldKeepPlayerComponentSyncEmpty(SyncContext context)
        {
            return false;
        }

        private static bool ShouldKeepMonsterComponentSyncEmpty(SyncContext context, string packetName = null)
        {
            return false;
        }

        private static bool ShouldKeepPlayerActionLaneAlive(SyncContext context)
        {
            return context == SyncContext.PlayerBasicAttackResponse || context == SyncContext.PlayerActionResponse;
        }

        private static bool CanApplyPlayerHPBeforeSuffix(SyncContext context, string packetName = null)
        {
            return true;
        }

        private static bool CanAdvancePlayerClientSyncHP(uint playerEntityId)
        {
            if (playerEntityId == 0) return true;
            return !CombatManager.Instance.HasPendingClientVisibleMonsterAttack(playerEntityId);
        }

        private void RegisterHpSyncPlayer(RRConnection conn)
        {
            if (conn?.Avatar == null) return;
            PlayerState state = GetPlayerState(conn.ConnId.ToString());
            if (state == null) return;
            HpSyncService.Instance.RegisterPlayer(conn, state, (uint)conn.Avatar.Id);
        }

        private void FlushCombatBeforeSynch(RRConnection conn, float nativeNowOverride = -1f)
        {
            if (conn?.Avatar == null) return;
            conn.LastCombatSyncFlushFrame = Time.frameCount;
            CombatManager.Instance.UpdatePlayerPosition((uint)conn.Avatar.Id, conn.PlayerPosX, conn.PlayerPosY);
            float flushNow = nativeNowOverride >= 0f ? nativeNowOverride : GetNativeCombatNow();
            if (IsZoneSpawnInvulnerabilityBlockingCombat(conn))
            {
                FlushPendingKills();
                return;
            }
            FlushPendingKills();
            FlushWeaponCycleBeforeSynch(conn, "FlushCombatBeforeSynch", true, flushNow);
            CombatManager.Instance.FlushPlayerCombatBeforeSync((uint)conn.Avatar.Id, 0f, "FlushCombatBeforeSynch", flushNow);
        }

        private void FlushWeaponCycleBeforeSynch(RRConnection conn, string source, bool flushKillsAfter, float nativeNowOverride = -1f)
        {
            if (conn?.Avatar == null) return;
            uint playerEntityId = (uint)conn.Avatar.Id;
            CombatManager.Instance.UpdatePlayerPosition(playerEntityId, conn.PlayerPosX, conn.PlayerPosY);
            float flushNow = nativeNowOverride >= 0f ? nativeNowOverride : GetNativeCombatNow();
            if (ShouldAdvancePlayerActionSliceBeforeAvatarSuffix(conn, playerEntityId))
            {
                conn.LastAvatarPreSuffixActionSliceFrame = Time.frameCount;
                var player = CombatManager.Instance.GetPlayer(playerEntityId);
                Debug.LogError($"[PLAYER-ACTION-PRE-SUFFIX] source={source ?? "unknown"} player={conn.LoginName ?? conn.ConnId.ToString()} activeUseTarget={conn.HasActiveUseTarget} activeAttack={player?.HasActiveClientAttack ?? false} target={conn.ActiveUseTargetId} flushNow={flushNow:F3} slice=due-drain");
            }
            Combat.WeaponCycleTracker.Instance.FlushPlayerEntityBeforeSynch(playerEntityId, CombatManager.Instance.RoomRng, flushNow, source);
            if (flushKillsAfter)
            {
                DrainWeaponCycleKills(source ?? "FlushWeaponCycleBeforeSynch");
                FlushPendingKills();
            }
        }

        private bool ShouldAdvancePlayerActionSliceBeforeAvatarSuffix(RRConnection conn, uint playerEntityId)
        {
            if (conn == null || playerEntityId == 0) return false;
            if (conn.LastAvatarPreSuffixActionSliceFrame == Time.frameCount) return false;
            var player = CombatManager.Instance.GetPlayer(playerEntityId);
            return conn.HasActiveUseTarget || (player != null && player.HasActiveClientAttack);
        }

        private bool TryResolvePlayerSynchronizedHP(RRConnection conn, string packetName, bool advanceClientSync, out uint hpWire)
        {
            return TryResolvePlayerSynchronizedHP(conn, SyncContextFromTag(packetName), packetName, advanceClientSync, out hpWire);
        }

        private bool TryResolvePlayerSynchronizedHP(RRConnection conn, SyncContext context, string packetName, bool advanceClientSync, out uint hpWire)
        {
            hpWire = 0;
            if (conn == null) return false;
            RefreshZoneSpawnInvulnerability(conn);
            PlayerState state = GetPlayerState(conn.ConnId.ToString());
            if (state == null) return false;
            uint playerEntityId = conn.Avatar != null ? (uint)conn.Avatar.Id : 0;
            if (playerEntityId != 0)
            {
                HpSyncService.Instance.RegisterPlayer(conn, state, playerEntityId);
                // Stat-parity fix 2026-05-30: keep the combat sim's player on THIS live PlayerState.
                // A relog mints a fresh per-connId PlayerState but leaves _players[id] bound to the
                // prior connection's stale copy (avatar id unchanged -> no lifecycle re-register), so
                // replayed mob damage lands on the stale copy while this suffix ships the fresh full one.
                CombatManager.Instance.RebindPlayerStateIfChanged(playerEntityId, state);
            }
            GetNativeValidationCutoff(out uint validationCutoffTick, out float validationCutoffTime);
            bool canApplyPlayerHP = CanApplyPlayerHPBeforeSuffix(context, packetName);
            bool pendingClientVisibleAttack = false;
            uint runtimeHPWire = state.SynchHP;
            if (canApplyPlayerHP && playerEntityId != 0 && !IsZoneSpawnInvulnerabilityBlockingCombat(conn))
            {
                CombatManager.Instance.UpdatePlayerPosition(playerEntityId, conn.PlayerPosX, conn.PlayerPosY);
                FlushPendingKills();
                FlushWeaponCycleBeforeSynch(conn, $"TryResolvePlayerSynchronizedHP:{packetName}", true, validationCutoffTime);
                CombatManager.Instance.FlushPlayerCombatBeforeSync(playerEntityId, 0f, $"TryResolvePlayerSynchronizedHP:{packetName}", validationCutoffTime);
                if (!CombatManager.Instance.FlushPlayerHPRuntimeBeforeSync(playerEntityId, packetName, out runtimeHPWire, out bool unsafeAttack, validationCutoffTime))
                {
                    Debug.LogError($"[{packetName}] player HP runtime flush incomplete for {conn.LoginName ?? conn.ConnId.ToString()}: serverHP={state.CurrentHPWire / 256f:F2}/{state.MaxHPWire / 256f:F2} syncHP={state.SynchHP / 256f:F2} runtimeHP={runtimeHPWire / 256f:F2} unsafeAttack={unsafeAttack}");
                }
            }
            pendingClientVisibleAttack = playerEntityId != 0 && CombatManager.Instance.HasPendingClientVisibleMonsterAttack(playerEntityId);
            bool canAdvanceClientSync = advanceClientSync && !pendingClientVisibleAttack;
            if (playerEntityId != 0)
            {
                float nativeNow = validationCutoffTime;
                var resolve = HpSyncService.Instance.ResolveOutboundPlayer(conn, state, playerEntityId, context, packetName, canAdvanceClientSync, nativeNow, out hpWire);
                if (!resolve.AllowPacket)
                {
                    Debug.LogError($"[{packetName}] player HP sync unresolved by HpSyncService for {conn.LoginName ?? conn.ConnId.ToString()}: serverHP={state.CurrentHPWire / 256f:F2}/{state.MaxHPWire / 256f:F2} syncHP={state.SynchHP / 256f:F2} lastOutbound={conn.LastOutboundHPWire / 256f:F2} reason={resolve.Reason}");
                    return false;
                }
                if (resolve.HasHP && (context == SyncContext.PlayerActionResponse || context == SyncContext.PlayerBasicAttackResponse || hpWire != state.CurrentHPWire))
                    Debug.LogError($"[PLAYER-HP-SUFFIX] packet={packetName} context={context} player={conn.LoginName ?? conn.ConnId.ToString()} currentHP={state.CurrentHPWire} syncHP={state.SynchHP} outboundHP={hpWire} advanceRequested={advanceClientSync} canAdvance={canAdvanceClientSync} pendingClientVisibleAttack={pendingClientVisibleAttack} runtimeProbeHP={runtimeHPWire} cutoffTick={validationCutoffTick} cutoffTime={validationCutoffTime:F3}");
                return resolve.HasHP;
            }
            if (canAdvanceClientSync)
                state.AdvanceClientSyncHP(validationCutoffTime, packetName);
            hpWire = state.SynchHP;
            return true;
        }

        private uint GetSynchValue(RRConnection conn, bool advanceClientSync)
        {
            string caller = null;
            string connIdStr = conn.ConnId.ToString();
            bool existed = _playerStates.ContainsKey(connIdStr);
            PlayerState state = GetPlayerState(connIdStr);

            if (VerboseSynchLogging)
            {
                var trace = new System.Diagnostics.StackTrace(1, false);
                caller = trace.GetFrame(0)?.GetMethod()?.Name ?? "unknown";
                Debug.LogWarning($"[GETSYNCH] Called by {caller}, returning {state.SynchHP}");
            }

            if (VerboseSynchLogging)
            {
                Debug.LogError($"[SYNCH-DEBUG] ConnId={conn.ConnId}, Key='{connIdStr}', ExistedBefore={existed}, SynchHP={state.SynchHP}, Level={state.Level}");
                Debug.LogError($"[GETSYNCH] Returning SynchHP: {state.SynchHP} CurrentHPWire: {state.CurrentHPWire}");
                if (state.SynchHP == 0)
                {
                    Debug.LogError($"[SYNCH-DEBUG] ⚠️ WARNING: SynchHP is 0! Dumping all known PlayerStates:");
                    foreach (var kvp in _playerStates)
                    {
                        Debug.LogError($"[SYNCH-DEBUG]   Key='{kvp.Key}', SynchHP={kvp.Value.SynchHP}, Level={kvp.Value.Level}");
                    }
                }
            }
            // return state.MaxHPWire;
            return state.SynchHP;
            // return state.SynchHP;
        }


        // ═══════════════════════════════════════════════════════════════════════════════
        // INVENTORY ITEM TRACKING
        // ═══════════════════════════════════════════════════════════════════════════════

        // Container keys: 0x0B (main inv) maps to the raw connId to preserve all existing
        // dict accesses across the codebase. Bank containers (0x0C, 0x0E-0x13) get suffixed keys.
        // Bank pages are 10x14 (per Bank.gc); main inv is 10x8.
        private static string InvKey(string connId, byte containerId)
            => containerId == 0x0B ? connId : $"{connId}:0x{containerId:X2}";

        private static bool IsBankContainer(byte containerId)
            => containerId == 0x0C || (containerId >= 0x0E && containerId <= 0x13);

        private static int ContainerHeight(byte containerId) => IsBankContainer(containerId) ? 14 : 8;
        private const int CONTAINER_WIDTH = 10;

        public void TrackInventoryItem(string connId, uint index, GCObject item, byte x, byte y, byte containerId = 0x0B)
        {
            string key = InvKey(connId, containerId);
            if (!_playerInventoryItems.ContainsKey(key))
                _playerInventoryItems[key] = new Dictionary<uint, (GCObject, byte, byte)>();
            _playerInventoryItems[key][index] = (item, x, y);
            Debug.LogError($"[INV-TRACK] Player {connId} container=0x{containerId:X2}: Index {index} = {item.GCClass} at ({x}, {y})");
        }

        public (int x, int y) FindNextFreeInventorySlot(string connId, int width, int height, byte containerId = 0x0B)
        {
            int invHeight = ContainerHeight(containerId);

            for (byte y = 0; y <= invHeight - height; y++)
            {
                for (byte x = 0; x <= CONTAINER_WIDTH - width; x++)
                {
                    if (!IsInventorySlotOccupied(connId, x, y, width, height, containerId))
                    {
                        return (x, y);
                    }
                }
            }
            return (-1, -1);  // Inventory full
        }


        private Dictionary<string, Dictionary<uint, int>> _inventoryStackCounts = new Dictionary<string, Dictionary<uint, int>>();

        public int GetStackCount(string connId, uint slot, byte containerId = 0x0B)
        {
            string key = InvKey(connId, containerId);
            if (_inventoryStackCounts.ContainsKey(key) && _inventoryStackCounts[key].ContainsKey(slot))
                return _inventoryStackCounts[key][slot];
            return 1;
        }

        public void SetStackCount(string connId, uint slot, int count, byte containerId = 0x0B)
        {
            string key = InvKey(connId, containerId);
            if (!_inventoryStackCounts.ContainsKey(key))
                _inventoryStackCounts[key] = new Dictionary<uint, int>();
            _inventoryStackCounts[key][slot] = count;
        }

        public void RemoveEquippedItem(string connId, uint slot)
        {
            if (_playerEquippedItems.ContainsKey(connId) && _playerEquippedItems[connId].ContainsKey(slot))
            {
                _playerEquippedItems[connId].Remove(slot);
                Debug.LogError($"[EQUIP-TRACK] Removed item from slot {slot}");
            }
        }

        public uint GetNextInventorySlot(string playerId)
        {
            if (!_inventorySlotCounters.ContainsKey(playerId))
            {
                _inventorySlotCounters[playerId] = 100; // Start at 100 to avoid equipment slot conflicts
            }

            uint slot = _inventorySlotCounters[playerId];
            _inventorySlotCounters[playerId]++;

            Debug.LogError($"[INV-SLOT] Generated new inventory slot {slot} for player {playerId}");
            return slot;
        }







        public (GCObject item, byte x, byte y)? GetAndRemoveInventoryItem(string connId, uint index, byte containerId = 0x0B)
        {
            string key = InvKey(connId, containerId);
            if (_playerInventoryItems.ContainsKey(key) && _playerInventoryItems[key].ContainsKey(index))
            {
                var data = _playerInventoryItems[key][index];
                _playerInventoryItems[key].Remove(index);

                // Get item dimensions from database
                ItemData itemData = DatabaseLoader.FindItem(data.item.GCClass);
                int width = itemData?.inventoryWidth ?? 1;
                int height = itemData?.inventoryHeight ?? 1;

                // Free ALL slots this item occupied
                FreeInventorySlots(connId, data.x, data.y, width, height, containerId);
                return data;
            }
            Debug.LogError($"[INV-TRACK] ❌ No item at index {index} in container 0x{containerId:X2}!");
            return null;
        }





        public bool IsInventorySlotOccupied(string connId, byte x, byte y, int width, int height, byte containerId = 0x0B)
        {
            int invHeight = ContainerHeight(containerId);
            // Bounds check
            if (x + width > CONTAINER_WIDTH || y + height > invHeight)
                return true;  // treat out-of-bounds as occupied

            string key = InvKey(connId, containerId);
            if (!_occupiedInventorySlots.ContainsKey(key))
                return false;

            // Check ALL cells the item would occupy
            for (int dx = 0; dx < width; dx++)
            {
                for (int dy = 0; dy < height; dy++)
                {
                    int slotIndex = (y + dy) * CONTAINER_WIDTH + (x + dx);
                    if (_occupiedInventorySlots[key].Contains(slotIndex))
                    {
                        Debug.LogError($"[INV-TRACK] ❌ Cell ({x + dx}, {y + dy}) in container 0x{containerId:X2} is already occupied!");
                        return true;
                    }
                }
            }
            return false;
        }

        public void OccupyInventorySlots(string connId, byte x, byte y, int width, int height, byte containerId = 0x0B)
        {
            string key = InvKey(connId, containerId);
            if (!_occupiedInventorySlots.ContainsKey(key))
                _occupiedInventorySlots[key] = new HashSet<int>();

            for (int dx = 0; dx < width; dx++)
            {
                for (int dy = 0; dy < height; dy++)
                {
                    int slotIndex = (y + dy) * CONTAINER_WIDTH + (x + dx);
                    _occupiedInventorySlots[key].Add(slotIndex);
                }
            }
            Debug.LogError($"[INV-TRACK] ✅ Occupied {width}x{height} slots starting at ({x}, {y}) in container 0x{containerId:X2}");
        }

        public void FreeInventorySlots(string connId, byte x, byte y, int width, int height, byte containerId = 0x0B)
        {
            string key = InvKey(connId, containerId);
            if (!_occupiedInventorySlots.ContainsKey(key))
                return;

            for (int dx = 0; dx < width; dx++)
            {
                for (int dy = 0; dy < height; dy++)
                {
                    int slotIndex = (y + dy) * CONTAINER_WIDTH + (x + dx);
                    _occupiedInventorySlots[key].Remove(slotIndex);
                }
            }
            Debug.LogError($"[INV-TRACK] ✅ Freed {width}x{height} slots starting at ({x}, {y}) in container 0x{containerId:X2}");
        }

        public (uint slot, GCObject item, byte x, byte y)? FindInventoryItemByGCClass(string connId, string gcClass, byte containerId = 0x0B)
        {
            string key = InvKey(connId, containerId);
            if (!_playerInventoryItems.ContainsKey(key)) return null;
            string gcLower = gcClass.ToLower();
            foreach (var kvp in _playerInventoryItems[key])
            {
                if (kvp.Value.Item1.GCClass.ToLower() == gcLower)
                    return (kvp.Key, kvp.Value.Item1, kvp.Value.Item2, kvp.Value.Item3);
            }
            return null;
        }
        private void SavePlayerInventory(RRConnection conn)
        {
            if (conn == null || string.IsNullOrEmpty(conn.LoginName)) return;
            string connId = conn.ConnId.ToString();
            if (!_selectedCharacter.ContainsKey(conn.LoginName)) return;
            var savedChar = CharacterRepository.GetCharacter(_selectedCharacter[conn.LoginName].Id);
            if (savedChar == null) return;
            savedChar.inventory.Clear();

            // Iterate every container: main inv (0x0B) and the 7 bank pages.
            // Items are tagged with containerId so LoadInventory restores them to the right container.
            byte[] saveContainers = { 0x0B, 0x0C, 0x0E, 0x0F, 0x10, 0x11, 0x12, 0x13 };
            foreach (byte cid in saveContainers)
            {
                string dictKey = InvKey(connId, cid);
                if (!_playerInventoryItems.ContainsKey(dictKey)) continue;
                foreach (var kvp in _playerInventoryItems[dictKey])
                {
                    int count = GetStackCount(connId, kvp.Key, cid);
                    // Position conflicts only apply within the same container.
                    var posConflict = savedChar.inventory.Find(i =>
                        i.containerId == cid &&
                        i.x == kvp.Value.Item2 &&
                        i.y == kvp.Value.Item3);
                    if (posConflict != null)
                    {
                        if (count > posConflict.count)
                        {
                            posConflict.gcClass = kvp.Value.Item1.GCClass;
                            posConflict.count = count;
                        }
                        uint bpConflict = DungeonRunners.Managers.MerchantManager.GetBuyPrice(connId, kvp.Value.Item1.GCClass);
                        if (bpConflict > 0) posConflict.buyPrice = bpConflict;
                    }
                    else
                    {
                        string bpGcClass = kvp.Value.Item1.GCClass;
                        uint bp = DungeonRunners.Managers.MerchantManager.GetBuyPrice(connId, bpGcClass);
                        savedChar.inventory.Add(new SavedInventoryItem
                        {
                            gcClass = bpGcClass,
                            x = kvp.Value.Item2,
                            y = kvp.Value.Item3,
                            count = count,
                            buyPrice = bp,
                            rarity = kvp.Value.Item1.GetEffectiveRarity(),
                            storedLevel = kvp.Value.Item1.StoredLevel,
                            containerId = cid
                        });
                    }
                }
            }

            // Save active item (on cursor) back to inventory so it's not lost
            PlayerState ps = GetPlayerState(connId);
            if (ps?.ActiveItem != null)
            {
                byte ax = 0, ay = 0;
                bool foundActive = false;
                int aw = 1, ah = 1;
                for (byte ry = 0; ry < 8 && !foundActive; ry++)
                    for (byte cx = 0; cx < 10 && !foundActive; cx++)
                        if (!IsInventorySlotOccupied(connId, cx, ry, aw, ah))
                        { ax = cx; ay = ry; foundActive = true; }
                if (foundActive)
                {
                    savedChar.inventory.Add(new SavedInventoryItem
                    {
                        gcClass = ps.ActiveItem.GCClass,
                        x = ax,
                        y = ay,
                        count = 1,
                        rarity = ps.ActiveItem.GetEffectiveRarity(),
                        storedLevel = ps.ActiveItem.StoredLevel
                    });
                    Debug.LogError($"[SAVE] Saved cursor item {ps.ActiveItem.GCClass} to inventory at ({ax},{ay})");
                }
                ps.ActiveItem = null;
            }

            // Sync equipment from tracking to savedChar
            if (_playerEquippedItems.ContainsKey(connId))
            {
                var eq = _playerEquippedItems[connId];
                savedChar.equipment.weapon = eq.ContainsKey(10) ? eq[10].GCClass : "";
                savedChar.equipment.armor = eq.ContainsKey(6) ? eq[6].GCClass : "";
                savedChar.equipment.helmet = eq.ContainsKey(5) ? eq[5].GCClass : "";
                savedChar.equipment.gloves = eq.ContainsKey(2) ? eq[2].GCClass : "";
                savedChar.equipment.boots = eq.ContainsKey(7) ? eq[7].GCClass : "";
                savedChar.equipment.shoulders = eq.ContainsKey(8) ? eq[8].GCClass : "";
                savedChar.equipment.shield = eq.ContainsKey(11) ? eq[11].GCClass : "";
                savedChar.equipment.ring1 = eq.ContainsKey(3) ? eq[3].GCClass : "";
                savedChar.equipment.ring2 = eq.ContainsKey(4) ? eq[4].GCClass : "";
                savedChar.equipment.amulet = eq.ContainsKey(1) ? eq[1].GCClass : "";
                // Sync rarity from tracked GCObjects
                if (eq.ContainsKey(10)) savedChar.equipment.slotRarity["weapon"] = eq[10].GetEffectiveRarity();
                if (eq.ContainsKey(6)) savedChar.equipment.slotRarity["armor"] = eq[6].GetEffectiveRarity();
                if (eq.ContainsKey(5)) savedChar.equipment.slotRarity["helmet"] = eq[5].GetEffectiveRarity();
                if (eq.ContainsKey(2)) savedChar.equipment.slotRarity["gloves"] = eq[2].GetEffectiveRarity();
                if (eq.ContainsKey(7)) savedChar.equipment.slotRarity["boots"] = eq[7].GetEffectiveRarity();
                if (eq.ContainsKey(8)) savedChar.equipment.slotRarity["shoulders"] = eq[8].GetEffectiveRarity();
                if (eq.ContainsKey(11)) savedChar.equipment.slotRarity["shield"] = eq[11].GetEffectiveRarity();
                if (eq.ContainsKey(3)) savedChar.equipment.slotRarity["ring1"] = eq[3].GetEffectiveRarity();
                if (eq.ContainsKey(4)) savedChar.equipment.slotRarity["ring2"] = eq[4].GetEffectiveRarity();
                if (eq.ContainsKey(1)) savedChar.equipment.slotRarity["amulet"] = eq[1].GetEffectiveRarity();
                // Sync stored level from tracked GCObjects
                if (eq.ContainsKey(10)) savedChar.equipment.slotLevel["weapon"] = eq[10].StoredLevel;
                if (eq.ContainsKey(6)) savedChar.equipment.slotLevel["armor"] = eq[6].StoredLevel;
                if (eq.ContainsKey(5)) savedChar.equipment.slotLevel["helmet"] = eq[5].StoredLevel;
                if (eq.ContainsKey(2)) savedChar.equipment.slotLevel["gloves"] = eq[2].StoredLevel;
                if (eq.ContainsKey(7)) savedChar.equipment.slotLevel["boots"] = eq[7].StoredLevel;
                if (eq.ContainsKey(8)) savedChar.equipment.slotLevel["shoulders"] = eq[8].StoredLevel;
                if (eq.ContainsKey(11)) savedChar.equipment.slotLevel["shield"] = eq[11].StoredLevel;
                if (eq.ContainsKey(3)) savedChar.equipment.slotLevel["ring1"] = eq[3].StoredLevel;
                if (eq.ContainsKey(4)) savedChar.equipment.slotLevel["ring2"] = eq[4].StoredLevel;
                if (eq.ContainsKey(1)) savedChar.equipment.slotLevel["amulet"] = eq[1].StoredLevel;
                Debug.LogError($"[SAVE] Equipment synced: weapon={savedChar.equipment.weapon}, armor={savedChar.equipment.armor}");
            }

            savedChar.currentZoneName = conn.CurrentZoneName ?? "tutorial";
            savedChar.zoneId = (int)conn.CurrentZoneId;
            CharacterRepository.SaveCharacter(savedChar);
            Debug.LogError($"[SAVE] Saved {savedChar.inventory.Count} inventory items for {conn.LoginName}");
        }



        public void SavePlayerInventoryPublic(RRConnection conn)
        {
            SavePlayerInventory(conn);
        }

        public void SavePlayerLevelPublic(RRConnection conn)
        {
            SavePlayerLevel(conn);
        }

        /// <summary>
        /// Removes quest item objectives from inventory on turn-in.
        /// Stackable handling: decrements stack by obj.Required via 0x22 UpdateQuantity
        /// when the remaining count is > 0, falls back to 0x1F full-row remove when the
        /// stack hits zero (or for non-stackables). Crosses multiple stacks if the
        /// requirement exceeds any one stack's count. Call BEFORE HandleTurnInConfirmed
        /// (which drops the quest from the active list).
        ///
        /// Previously this used `GetAndRemoveInventoryItem` against the first matching
        /// slot, which nuked a 50-stack of QuestItemPAL.Token when the wishing-well
        /// objective only asked for 1 — see CHANGELOG_WISHING_WELL_2026-05-19.md.
        /// </summary>
        private void RemoveQuestItemsFromInventory(RRConnection conn, ActiveQuest completingQuest)
        {
            if (completingQuest == null) return;
            string connId = conn.ConnId.ToString();

            foreach (var obj in completingQuest.Objectives)
            {
                if (obj.Type == null || !obj.Type.Equals("item", StringComparison.OrdinalIgnoreCase))
                    continue;
                if (string.IsNullOrEmpty(obj.Target))
                    continue;

                int remainingToRemove = Math.Max(1, obj.Required);
                Debug.LogError($"[QUEST-ITEM-REMOVE] Looking for: {obj.Target} ({obj.Label}) ×{remainingToRemove}");

                if (!_playerInventoryItems.ContainsKey(connId))
                {
                    Debug.LogError($"[QUEST-ITEM-REMOVE] No inventory tracked for {connId}");
                    continue;
                }

                // Snapshot slot ids first so we can mutate _playerInventoryItems during iteration.
                var matchingSlots = new List<uint>();
                foreach (var kvp in _playerInventoryItems[connId])
                {
                    if (kvp.Value.item != null &&
                        kvp.Value.item.GCClass != null &&
                        kvp.Value.item.GCClass.Equals(obj.Target, StringComparison.OrdinalIgnoreCase))
                    {
                        matchingSlots.Add(kvp.Key);
                    }
                }

                if (matchingSlots.Count == 0)
                {
                    Debug.LogError($"[QUEST-ITEM-REMOVE] NOT FOUND in inventory! Dumping all slots:");
                    foreach (var kvp in _playerInventoryItems[connId])
                        Debug.LogError($"  slot {kvp.Key}: {kvp.Value.item?.GCClass ?? "NULL"}");
                    continue;
                }

                foreach (uint slotId in matchingSlots)
                {
                    if (remainingToRemove <= 0) break;

                    int stack = GetStackCount(connId, slotId);
                    if (stack <= 0) stack = 1;

                    if (stack > remainingToRemove)
                    {
                        // Stack survives — decrement count, send 0x22 UpdateQuantity.
                        int newCount = stack - remainingToRemove;
                        SetStackCount(connId, slotId, newCount);
                        remainingToRemove = 0;

                        if (conn.UnitContainerId != 0)
                        {
                            var qWriter = new LEWriter();
                            qWriter.WriteByte(0x07);
                            qWriter.WriteByte(0x35);
                            qWriter.WriteUInt16(conn.UnitContainerId);
                            qWriter.WriteByte(0x22);
                            qWriter.WriteUInt32(slotId);
                            qWriter.WriteByte((byte)(newCount > 255 ? 255 : newCount));
                            WritePlayerEntitySynch(conn, qWriter);
                            qWriter.WriteByte(0x06);
                            SendCompressedA(conn, 0x01, 0x0F, qWriter.ToArray());
                        }
                        Debug.LogError($"[QUEST-ITEM-REMOVE] decremented slot {slotId}: {stack} → {newCount}");
                    }
                    else
                    {
                        // Stack consumed entirely — full-row remove via 0x1F.
                        remainingToRemove -= stack;
                        GetAndRemoveInventoryItem(connId, slotId);

                        if (conn.UnitContainerId != 0)
                        {
                            var writer = new LEWriter();
                            writer.WriteByte(0x07);
                            writer.WriteByte(0x35);
                            writer.WriteUInt16(conn.UnitContainerId);
                            writer.WriteByte(0x1F);
                            writer.WriteUInt32(slotId);
                            writer.WriteByte(0x02);
                            writer.WriteUInt32(0x00000000);
                            writer.WriteByte(0x06);
                            SendCompressedA(conn, 0x01, 0x0F, writer.ToArray());
                        }
                        Debug.LogError($"[QUEST-ITEM-REMOVE] consumed full stack at slot {slotId} (was {stack})");
                    }
                }

                if (remainingToRemove > 0)
                {
                    Debug.LogError($"[QUEST-ITEM-REMOVE] ⚠️ underflowed: {remainingToRemove}× {obj.Target} still needed but inventory exhausted");
                }
                SavePlayerInventory(conn);
                Debug.LogError($"[QUEST-ITEM-REMOVE] ✅ done for {obj.Target}");
            }
        }


