        // ═══════════════════════════════════════════════════════════════════
        // STATIC KEYS FROM cryNullKeyExchanger (HARDCODED IN CLIENT BINARY)
        // ═══════════════════════════════════════════════════════════════════
        private static readonly byte[] NULL_PUBKEY = System.Text.Encoding.ASCII.GetBytes("PUBKEY12");
        private static readonly byte[] NULL_PRIVKEY = System.Text.Encoding.ASCII.GetBytes("PRIVKEY!");
        private byte[] _udpBlowfishKey;

        private void SendUDPSynAck(IPEndPoint clientEndpoint, byte[] clientSyn)
        {
            try
            {
                byte[] generator = new byte[64];
                generator[0] = 0x02;

                byte[] prime = new byte[128];
                for (int i = 0; i < prime.Length; i++) prime[i] = 0xFF;

                var ms = new System.IO.MemoryStream();
                var bw = new System.IO.BinaryWriter(ms);

                bw.Write((byte)0x03);
                bw.Write(clientSyn.Length > 1 ? clientSyn[1] : (byte)0x01);
                bw.Write((ushort)0);
                bw.Write((uint)1);

                bw.Write((ushort)generator.Length);
                bw.Write(generator);

                bw.Write((ushort)prime.Length);
                bw.Write(prime);

                bw.Write((ushort)NULL_PUBKEY.Length);
                bw.Write(NULL_PUBKEY);

                byte[] packet = ms.ToArray();
                _udpListener.Send(packet, packet.Length, clientEndpoint);

                // Create UDP session with Blowfish
                string epKey = GetEndpointKey(clientEndpoint);
                var session = new UDPSession { Endpoint = clientEndpoint, IsEstablished = false };

                using (var md5 = System.Security.Cryptography.MD5.Create())
                {
                    byte[] blowfishKey = md5.ComputeHash(NULL_PRIVKEY);
                    session.InitializeCipher(blowfishKey);
                    _udpBlowfishKey = blowfishKey;
                    Debug.LogError($"[UDP] Blowfish Key: {BitConverter.ToString(blowfishKey)}");
                }

                _udpSessions[epKey] = session;
                Debug.LogError($"[UDP] Sent SYN-ACK with PUBKEY12, session created for {epKey}");
            }
            catch (Exception ex)
            {
                Debug.LogError($"[UDP] SendUDPSynAck error: {ex.Message}");
            }
        }

        private string GetLocalIPAddress()
        {
            var host = Dns.GetHostEntry(Dns.GetHostName());
            foreach (var ip in host.AddressList)
            {
                if (ip.AddressFamily == AddressFamily.InterNetwork)
                {
                    string ipStr = ip.ToString();
                    if (ipStr.StartsWith("10."))
                    {
                        return ipStr;
                    }
                }
            }
            foreach (var ip in host.AddressList)
            {
                if (ip.AddressFamily == AddressFamily.InterNetwork)
                {
                    return ip.ToString();
                }
            }
            return "127.0.0.1";
        }

        private void StopServer()
        {
            _isRunning = false;
            _listener?.Stop();
            _udpListener?.Close();  // 🔥 ADD THIS LINE
            foreach (var conn in _connections.Values)

            {
                conn.Disconnect();
            }
            _connections.Clear();
            Debug.Log("Game Server stopped");
        }

        // ═══════════════════════════════════════════════════════════
        // ADMIN PANEL: PENDING ITEM GRANTS
        // ═══════════════════════════════════════════════════════════
        private IEnumerator PollPendingItemGrants()
        {
            yield return new WaitForSeconds(5f);
            while (_isRunning)
            {
                try { ProcessPendingGrants(); }
                catch (Exception ex) { Debug.LogError($"[GRANTS] Error: {ex.Message}"); }
                try { ProcessPendingAdminActions(); }
                catch (Exception ex) { Debug.LogError($"[ADMIN-ACT] Error: {ex.Message}"); }
                yield return new WaitForSeconds(5f);
            }
        }

        private void ProcessPendingAdminActions()
        {
            using (var conn = GameDatabase.GetConnection())
            {
                // Check if table exists
                object tbl = GameDatabase.ExecuteScalar(conn, "SELECT name FROM sqlite_master WHERE type='table' AND name='pending_admin_actions'");
                if (tbl == null) return;

                var actions = new List<(int id, int charId, string actionType, int value)>();
                using (var cmd = conn.CreateCommand())
                {
                    cmd.CommandText = "SELECT id, character_id, action_type, value FROM pending_admin_actions ORDER BY id";
                    using (var reader = cmd.ExecuteReader())
                        while (reader.Read())
                            actions.Add((reader.GetInt32(0), reader.GetInt32(1), reader.GetString(2), reader.GetInt32(3)));
                }
                if (actions.Count == 0) return;

                foreach (var act in actions)
                {
                    try
                    {
                        // Find online connection
                        RRConnection onlineConn = null;
                        string loginName = null;
                        foreach (var kvp in _selectedCharacter)
                            if (kvp.Value.Id == act.charId) { loginName = kvp.Key; break; }
                        if (loginName != null)
                            foreach (var c in _connections)
                                if (c.Value.LoginName == loginName) { onlineConn = c.Value; break; }

                        if (act.actionType == "gold" && onlineConn != null && onlineConn.UnitContainerId != 0)
                        {
                            // Direct SQL update — don't use SaveCharacter which overwrites XP/level
                            using (var gdb = GameDatabase.GetConnection())
                            {
                                if (act.value > 0)
                                {
                                    GameDatabase.ExecuteNonQuery(gdb,
                                        "UPDATE characters SET gold = gold + @amt WHERE id = @id",
                                        ("@amt", act.value), ("@id", act.charId));
                                    // Send AddCurrency packet (0x20)
                                    var wr = new LEWriter();
                                    wr.WriteByte(0x07);
                                    wr.WriteByte(0x35);
                                    wr.WriteUInt16(onlineConn.UnitContainerId);
                                    wr.WriteByte(0x20);
                                    wr.WriteUInt32((uint)act.value);
                                    wr.WriteByte(0x00);
                                    wr.WriteUInt32(0x00000000);
                                    wr.WriteByte(0x01);
                                    wr.WriteByte(0x02);
                                    wr.WriteUInt32(0x00000000);
                                    wr.WriteByte(0x06);
                                    SendToClient(onlineConn, wr.ToArray());
                                }
                                else if (act.value < 0)
                                {
                                    GameDatabase.ExecuteNonQuery(gdb,
                                        "UPDATE characters SET gold = MAX(0, gold + @amt) WHERE id = @id",
                                        ("@amt", act.value), ("@id", act.charId));
                                    // Send AddCurrency (0x20) with negative value — 0x21 is gated behind merchant context
                                    var wr = new LEWriter();
                                    wr.WriteByte(0x07);
                                    wr.WriteByte(0x35);
                                    wr.WriteUInt16(onlineConn.UnitContainerId);
                                    wr.WriteByte(0x20);                  // AddCurrency
                                    wr.WriteInt32(act.value);            // already negative
                                    wr.WriteByte(0x00);                  // source
                                    wr.WriteUInt32(0x00000000);          // entityHandle
                                    wr.WriteByte(0x01);                  // notifyFlag (jingle)
                                    WritePlayerEntitySynch(onlineConn, wr);
                                    wr.WriteByte(0x06);
                                    SendCompressedA(onlineConn, 0x01, 0x0F, wr.ToArray());
                                }
                                // Update in-memory savedChar gold too
                                var sc = GetSavedCharacterForConn(onlineConn);
                                if (sc != null) sc.gold = (uint)Math.Max(0, (int)sc.gold + act.value);
                            }
                            Debug.LogError($"[ADMIN-ACT] ✅ Gold {(act.value > 0 ? "+" : "")}{act.value} for char {act.charId}");
                        }
                        else if (act.actionType == "level" && onlineConn != null)
                        {
                            string connId = onlineConn.ConnId.ToString();
                            PlayerState lvlPs = GetPlayerState(connId);
                            var savedChar = GetSavedCharacterForConn(onlineConn);
                            if (savedChar != null && lvlPs != null)
                            {
                                int oldLevel = lvlPs.Level;
                                int targetLevel = act.value;
                                // Direct SQL — only update level and experience
                                using (var ldb = GameDatabase.GetConnection())
                                    GameDatabase.ExecuteNonQuery(ldb,
                                        "UPDATE characters SET level=@lv, experience=0 WHERE id=@id",
                                        ("@lv", targetLevel), ("@id", act.charId));
                                savedChar.level = (byte)targetLevel;
                                savedChar.experience = 0;
                                lvlPs.InitializeStats(savedChar.className ?? "Fighter", savedChar.level);
                                lvlPs.Experience = 0;
                                if (onlineConn.Avatar != null)
                                    CalculateEquipmentBonuses(connId, onlineConn.Avatar);
                                lvlPs.RestoreToFull();

                                if (targetLevel > oldLevel)
                                {
                                    for (int lv = oldLevel; lv < targetLevel; lv++)
                                    {
                                        uint threshold = PlayerState.GetClientThreshold(lv + 1);
                                        uint packetXP = threshold * 256 / 5 + 100;
                                        SendAdminXPUpdate(onlineConn, packetXP, (uint)lv);
                                    }
                                    // The DLL's XP hook on the client will echo each admin XP
                                    // packet back to the server and write _lastClientXP. Without
                                    // this reset, the next mob kill would consume that stale value
                                    // and add a giant chunk of XP on top of the level we just set.
                                    _lastClientXP = 0;
                                }
                                SendAdminHPSync(onlineConn, lvlPs);
                                Debug.LogError($"[ADMIN-ACT] ✅ Level {oldLevel} → {targetLevel} for char {act.charId}");
                            }
                        }
                        // XP: update in-memory state so zone save doesn't overwrite DB
                        if (act.actionType == "xp" && onlineConn != null)
                        {
                            var savedChar = GetSavedCharacterForConn(onlineConn);
                            if (savedChar != null)
                            {
                                savedChar.experience = (uint)act.value;
                                string connId = onlineConn.ConnId.ToString();
                                PlayerState xpPs = GetPlayerState(connId);
                                if (xpPs != null) xpPs.Experience = (uint)act.value;
                                Debug.LogError($"[ADMIN-ACT] ✅ XP memory updated to {act.value} for char {act.charId}");
                            }
                        }
                        else if (act.actionType == "xp" && onlineConn == null)
                        {
                            // Offline - DB already updated by admin panel, nothing to do
                        }

                        // Delete processed action
                        GameDatabase.ExecuteNonQuery(conn, "DELETE FROM pending_admin_actions WHERE id=@id", ("@id", act.id));
                    }
                    catch (Exception ex) { Debug.LogError($"[ADMIN-ACT] Failed action {act.id}: {ex.Message}"); }
                }
            }
        }

        private void ProcessPendingGrants()
        {
            using (var conn = GameDatabase.GetConnection())
            {
                var grants = new List<(int id, int charId, string gcClass, int count, int width, int height, int rarity)>();
                using (var cmd = conn.CreateCommand())
                {
                    cmd.CommandText = "SELECT id, character_id, gc_class, count, width, height, rarity FROM pending_item_grants ORDER BY id";
                    using (var reader = cmd.ExecuteReader())
                    {
                        while (reader.Read())
                            grants.Add((reader.GetInt32(0), reader.GetInt32(1), reader.GetString(2),
                                reader.GetInt32(3), reader.GetInt32(4), reader.GetInt32(5), reader.GetInt32(6)));
                    }
                }
                if (grants.Count == 0) return;

                foreach (var grant in grants)
                {
                    try
                    {
                        // Find if character is online
                        RRConnection onlineConn = null;
                        string loginName = null;
                        foreach (var kvp in _selectedCharacter)
                        {
                            if (kvp.Value.Id == grant.charId) { loginName = kvp.Key; break; }
                        }
                        if (loginName != null)
                        {
                            foreach (var c in _connections)
                            {
                                if (c.Value.LoginName == loginName) { onlineConn = c.Value; break; }
                            }
                        }

                        if (onlineConn != null && onlineConn.UnitContainerId != 0)
                        {
                            string connId = onlineConn.ConnId.ToString();
                            string gcTypeFull = grant.gcClass;
                            if (!gcTypeFull.StartsWith("items.", StringComparison.OrdinalIgnoreCase))
                                gcTypeFull = "items.pal." + gcTypeFull;
                            int itemWidth = grant.width, itemHeight = grant.height;
                            try
                            {
                                using (var db2 = GameDatabase.GetConnection())
                                using (var dimReader = GameDatabase.ExecuteReader(db2,
                                    "SELECT gc_type, width, height FROM item_dimensions WHERE LOWER(gc_type) = LOWER(@g)", ("@g", gcTypeFull)))
                                { if (dimReader.Read()) { gcTypeFull = dimReader.GetString(0); itemWidth = dimReader.GetInt32(1); itemHeight = dimReader.GetInt32(2); } }
                            }
                            catch { }

                            string packetGcType = gcTypeFull.ToLowerInvariant();
                            if (packetGcType.StartsWith("items.pal.")) packetGcType = packetGcType.Substring(10);

                            byte slotX = 0, slotY = 0; bool foundSlot = false;
                            for (byte row = 0; row < 8 && !foundSlot; row++)
                                for (byte col = 0; col < 10 && !foundSlot; col++)
                                    if (!IsInventorySlotOccupied(connId, col, row, itemWidth, itemHeight))
                                    { slotX = col; slotY = row; foundSlot = true; }
                            if (!foundSlot) { Debug.LogError($"[GRANTS] Inventory full char {grant.charId}"); continue; }

                            // CRITICAL: use _mythicModSlots for correct mod count (NOT weapons.mod_count!)
                            int modSlots = 1;
                            if (DungeonRunners.Managers.MerchantManager._mythicModSlots.TryGetValue(packetGcType, out int ms))
                                modSlots = ms;

                            uint slot = GetNextInventorySlot(connId);
                            PlayerState ps = GetPlayerState(connId);

                            byte itemLevel = ps != null ? (byte)Math.Max(1, Math.Min(ps.Level, 100)) : (byte)1;

                            var wr = new LEWriter();
                            wr.WriteByte(0x07);
                            wr.WriteByte(0x35);
                            wr.WriteUInt16(onlineConn.UnitContainerId);
                            wr.WriteByte(0x1E);
                            wr.WriteByte(0x0B);
                            wr.WriteByte(0xFF);
                            wr.WriteCString(packetGcType);
                            wr.WriteUInt32(slot);
                            wr.WriteByte(slotX);
                            wr.WriteByte(slotY);
                            wr.WriteByte((byte)grant.count);
                            wr.WriteByte(itemLevel);
                            for (int mi = 0; mi < modSlots; mi++)
                                wr.WriteByte(0x00);
                            wr.WriteByte(0x01);
                            wr.WriteByte(0xFF);
                            wr.WriteCString("ScaleModPAL.Rare.Mod1");
                            wr.WriteByte(0x03);
                            wr.WriteByte(0x15);
                            wr.WriteUInt32(0x11111111);
                            WritePlayerEntitySynch(onlineConn, wr);
                            wr.WriteByte(0x06);

                            Debug.LogError($"[GRANTS] Sending: gc={packetGcType} modSlots={modSlots} slot={slot} pos=({slotX},{slotY})");
                            SendToClient(onlineConn, wr.ToArray());

                            // Set NativeClass correctly (same as merchant buy)
                            string gcLower2 = packetGcType.ToLowerInvariant();
                            string nativeClass = "Armor";
                            if (gcLower2.Contains("consumable") || gcLower2.Contains("questitem") || gcLower2.Contains("ring") || gcLower2.Contains("amulet") || gcLower2.Contains("scroll") || gcLower2.Contains("potion") || gcLower2.Contains("skillbook") || gcLower2.Contains("voucher"))
                                nativeClass = "Item";
                            else if (gcLower2.Contains("sword") || gcLower2.Contains("axe") || gcLower2.Contains("mace") || gcLower2.Contains("dagger") || gcLower2.Contains("hammer") || gcLower2.Contains("staff") || gcLower2.Contains("spear") || gcLower2.Contains("pick") || gcLower2.Contains("club") || gcLower2.Contains("scepter") || gcLower2.Contains("wand"))
                                nativeClass = "MeleeWeapon";
                            else if (gcLower2.Contains("bow") || gcLower2.Contains("cannon") || gcLower2.Contains("crossbow") || gcLower2.Contains("xbow") || gcLower2.Contains("gun"))
                                nativeClass = "RangedWeapon";

                            var newItem = new DungeonRunners.Data.GCObject { GCClass = packetGcType, NativeClass = nativeClass };
                            newItem.StoredRarity = grant.rarity;
                            newItem.StoredLevel = itemLevel;
                            TrackInventoryItem(connId, slot, newItem, slotX, slotY);
                            OccupyInventorySlots(connId, slotX, slotY, itemWidth, itemHeight);
                            SetStackCount(connId, slot, grant.count);
                            SavePlayerInventoryPublic(onlineConn);

                            Debug.LogError($"[GRANTS] ✅ LIVE delivered {packetGcType} x{grant.count} modSlots={modSlots}");
                            GameDatabase.ExecuteNonQuery(conn, "DELETE FROM pending_item_grants WHERE id=@id", ("@id", grant.id));
                            continue;
                        }

                        {
                            // OFFLINE: insert into DB with proper grid placement
                            var occupied = new HashSet<string>();
                            using (var cmd2 = conn.CreateCommand())
                            {
                                cmd2.CommandText = "SELECT slot_x, slot_y FROM character_inventory WHERE character_id=@cid";
                                cmd2.Parameters.AddWithValue("@cid", grant.charId);
                                using (var r2 = cmd2.ExecuteReader())
                                    while (r2.Read()) occupied.Add($"{r2.GetInt32(0)},{r2.GetInt32(1)}");
                            }

                            int fx = -1, fy = -1;
                            for (int y = 0; y <= 8 - grant.height && fy < 0; y++)
                                for (int x = 0; x <= 10 - grant.width && fx < 0; x++)
                                {
                                    bool fits = true;
                                    for (int dx = 0; dx < grant.width && fits; dx++)
                                        for (int dy = 0; dy < grant.height && fits; dy++)
                                            if (occupied.Contains($"{x + dx},{y + dy}")) fits = false;
                                    if (fits) { fx = x; fy = y; }
                                }

                            if (fx < 0) { Debug.LogError($"[GRANTS] Inventory full (offline) char {grant.charId}"); continue; }

                            GameDatabase.ExecuteNonQuery(conn,
                                "INSERT INTO character_inventory (character_id,gc_class,slot_x,slot_y,count,rarity,stored_level) VALUES(@cid,@gc,@x,@y,@n,@r,-1)",
                                ("@cid", grant.charId), ("@gc", grant.gcClass), ("@x", fx), ("@y", fy), ("@n", grant.count), ("@r", grant.rarity));
                            Debug.LogError($"[GRANTS] 📦 OFFLINE inserted {grant.gcClass} x{grant.count} to char {grant.charId} at ({fx},{fy})");
                        }

                        // Delete processed grant
                        GameDatabase.ExecuteNonQuery(conn, "DELETE FROM pending_item_grants WHERE id=@id", ("@id", grant.id));
                    }
                    catch (Exception ex) { Debug.LogError($"[GRANTS] Failed grant {grant.id}: {ex.Message}"); }
                }
            }
        }

        private IEnumerator AcceptClientsCoroutine()
        {
            while (_isRunning)
            {
                if (_listener.Pending())
                {
                    TcpClient client = _listener.AcceptTcpClient();
                    var endpoint = (System.Net.IPEndPoint)client.Client.RemoteEndPoint;
                    string remoteIP = endpoint.Address.IsIPv4MappedToIPv6
                        ? endpoint.Address.MapToIPv4().ToString()
                        : endpoint.Address.ToString();
                    Debug.LogError($"[GAME-PORT] Connection from {remoteIP}:{endpoint.Port}");

                    // Check if this is a queue connection (flagged by AuthServer)
                    string queueUser = QueueConnectionBridge.CheckAndConsumeQueueIP(remoteIP);
                    if (queueUser != null)
                    {
                        Debug.LogError($"[QUEUE] ✅ Queue connection from {remoteIP} for {queueUser} on GAME port");
                        // Game port uses Go/Blowfish (same as PlayOk) — no crypto needed
                    }

                    int connId = _nextConnId++;
                    NetworkStream stream = client.GetStream();
                    var conn = new RRConnection(connId, client, stream);
                    if (queueUser != null)
                        conn.LoginName = queueUser;
                    _connections[connId] = conn;
                    Debug.Log($"Client {connId} connected from {client.Client.RemoteEndPoint}");
                    InitiateUDPToClient(conn);
                    StartCoroutine(HandleClientCoroutine(conn));
                }
                yield return null;
            }
        }

        private IEnumerator HandleClientCoroutine(RRConnection conn)
        {
            // Load account flags for queue users (LoginName already set)
            if (conn.LoginName != null)
            {
                LoadAccountFlags(conn.LoginName);
                conn.DllSessionToken = (uint)(new System.Random().Next(1, int.MaxValue));
                Debug.LogError($"[DLL-TOKEN] Generated token 0x{conn.DllSessionToken:X8} for {conn.LoginName}");
            }

            byte[] buffer = new byte[8192];
            while (_isRunning && conn.Client.Connected)
            {
                try
                {
                    // Detect dead connections (client closed without sending data)
                    if (conn.Client.Client.Poll(0, System.Net.Sockets.SelectMode.SelectRead) && !conn.Stream.DataAvailable)
                    {
                        Debug.LogError($"[CLIENT] Connection {conn.ConnId} dead (poll detected)");
                        break;
                    }

                    if (conn.Stream.DataAvailable)
                    {
                        int bytesRead = conn.Stream.Read(buffer, 0, buffer.Length);
                        if (bytesRead > 0)
                        {
                            byte[] data = new byte[bytesRead];
                            Array.Copy(buffer, data, bytesRead);
                            ProcessMessage(conn, data);
                        }
                    }
                }
                catch (Exception ex)
                {
                    Debug.LogError($"Error handling client {conn.ConnId}: {ex.Message}\n{ex.StackTrace}");
                    // DON'T break — one bad packet should not kill the connection
                }
                yield return null;
            }
            Debug.Log($"Client {conn.ConnId} disconnected");
            QueueConnectionBridge.PlayerDisconnected();
            SavePlayerInventory(conn);
            SavePlayerQuests(conn);
            SavePlayerLevel(conn);

            // Clean up Bling Gnome on disconnect
            BlingGnomeManager.Instance.OnPlayerDisconnect(conn.ConnId);

            // Clear modifier tracker on disconnect (admin buffs are session-only)
            if (conn.LoginName != null)
                _modifierTracker.ClearPlayer(conn.LoginName);

            if (conn.LoginName != null)
                _debuffCooldowns.Remove(conn.LoginName);

            // Clean modifier sent guard so reconnect works
            if (conn.LoginName != null)
            {
                _freePlayerModifierSent.Remove(conn.LoginName);
                _freePlayerModifierSent.Remove(conn.LoginName + "_sent");
            }

            // Clear active character in DB for admin panel
            if (conn.LoginName != null)
            {
                try
                {
                    using (var dbConn = GameDatabase.GetConnection())
                        GameDatabase.ExecuteNonQuery(dbConn,
                            "UPDATE accounts SET current_character_id=0 WHERE username=@u COLLATE NOCASE",
                            ("@u", conn.LoginName));
                }
                catch { }
            }

            // Clear town portal on normal logoff
            if (conn.LoginName != null && _selectedCharacter.ContainsKey(conn.LoginName))
            {
                var logoffChar = CharacterRepository.GetCharacter(_selectedCharacter[conn.LoginName].Id);
                if (logoffChar != null)
                {
                    logoffChar.tpZone = "";
                    logoffChar.tpZoneId = 0;
                    logoffChar.tpTargetZone = "";
                    logoffChar.tpPosX = 0;
                    logoffChar.tpPosY = 0;
                    logoffChar.tpPosZ = 0;
                    CharacterRepository.SaveCharacter(logoffChar);
                    Debug.LogError($"[DISCONNECT] Cleared town portal from DB");
                }
            }

            // ═══ DROPPED ITEMS: Remove all items dropped by this player ═══
            if (conn.LoginName != null)
            {
                string dropperName = conn.LoginName;
                List<ushort> toRemove = new List<ushort>();

                foreach (var kvp in _droppedItems)
                {
                    if (kvp.Value.DroppedBy == dropperName)
                        toRemove.Add(kvp.Key);
                }

                foreach (ushort entityId in toRemove)
                {
                    var info = _droppedItems[entityId];

                    // Despawn for all other players in same zone
                    foreach (var other in _connections.Values)
                    {
                        if (other == conn) continue;
                        if (!other.IsSpawned) continue;
                        if (other.CurrentZoneGcType != info.Zone) continue;
                        if (other.InstanceId != info.InstanceId) continue;
                        SendDespawnEntity(other, entityId);
                    }

                    // Remove from DB
                    if (info.DbId > 0)
                    {
                        try
                        {
                            using (var db2 = DungeonRunners.Database.GameDatabase.GetConnection())
                            {
                                DungeonRunners.Database.GameDatabase.ExecuteNonQuery(db2,
                                    "DELETE FROM dropped_items WHERE id = @id",
                                    ("@id", info.DbId));
                            }
                            _dbIdToEntityId.Remove(info.DbId);
                        }
                        catch (Exception ex)
                        {
                            Debug.LogError($"[DISCONNECT] ❌ Failed to delete dropped item dbId={info.DbId}: {ex.Message}");
                        }
                    }

                    _droppedItems.Remove(entityId);
                }

                if (toRemove.Count > 0)
                    Debug.LogError($"[DISCONNECT] Removed {toRemove.Count} dropped items for {dropperName}");
            }

            // ═══ GROUP: Mark member offline, send 0x49 then 0x35 ═══
            // TTD-VERIFIED sequence:
            //   0x49 → sets member+0x18=0, +0x30=1, shows "disconnected" chat message
            //   0x35 → rebuilds member vector from packet data (isOnline=false for
            //          disconnected member via readMember@0x5FA6D0), fires event 0x121111
            //          → GroupHealth::refresh reads fresh member+0x18=0 → shows grey overlay
            // DO NOT send 0x44 — TTD trace 20 proved it resets member state.
            // 0x35 AFTER 0x49 works because 0x35 creates NEW member entries from packet
            // data where isOnline byte is already 0, so no state to "undo".
            var group = GroupManager.Instance.GetGroupForConn(conn.ConnId);
            if (group != null)
            {
                // Cache data BEFORE disconnect
                var gm = group.Members.Find(m => m.ConnId == conn.ConnId);
                if (gm != null)
                {
                    gm.CharSqlId = GetCharSqlId(conn);
                    gm.AvatarEntityId = GetPlayerAvatarId(conn.LoginName);
                    if (_selectedCharacter.TryGetValue(conn.LoginName, out var ch))
                        gm.Name = ch.Name ?? gm.Name;
                }

                uint disconnCharId = GetCharSqlId(conn);

                if (GroupManager.Instance.DisconnectMember(conn.ConnId))
                {
                    if (group.Members.Any(m => m.IsOnline))
                    {
                        // Step 1: 0x49 — shows "Group member '%s' has disconnected." chat message
                        byte[] disconnectPacket = GroupPackets.BuildMemberDisconnected(group.GroupId, disconnCharId);
                        foreach (var rm in group.Members)
                        {
                            if (!rm.IsOnline) continue;
                            var rmc = FindConnectionById(rm.ConnId);
                            if (rmc != null)
                                SendToClient(rmc, disconnectPacket);
                        }

                        // Step 2: 0x35 — rebuilds member vector with isOnline=false for
                        // disconnected member. readMember@0x5FA6D0 reads isOnline byte from
                        // packet → stores at member+0x18. Event 0x121111 fires →
                        // GroupHealth::refresh → reads +0x18=0 → grey overlay.
                        SendGroupConnectedToAll(group);

                        Debug.LogError($"[GROUP] Sent 0x49+0x35 for disconnect: {conn.LoginName} charId=0x{disconnCharId:X8}");
                    }
                    else
                    {
                        foreach (var m in group.Members.ToList())
                            GroupManager.Instance.LeaveGroup(m.ConnId);
                    }
                }
                conn.GroupConnectedSent = false;
            }

            // ═══ MULTIPLAYER: Remove avatar from other clients ═══
            if (conn.IsSpawned)
            {
                BroadcastEntityRemove(conn, conn.CurrentZoneGcType);
                conn.IsSpawned = false;
            }

            string disconnKey = conn.ConnId.ToString();
            ClearUseTarget(conn);
            Combat.WeaponCycleTracker.Instance.ClearConnection(disconnKey);
            if (conn.Avatar != null)
                CombatManager.Instance.UnregisterPlayer((uint)conn.Avatar.Id);
            else if (_playerAvatarEntityId.TryGetValue(disconnKey, out uint oldAvatarId))
                CombatManager.Instance.UnregisterPlayer(oldAvatarId);
            Debug.LogError($"[COMBAT-LIFECYCLE] disconnect cleared combat state conn={conn.ConnId} avatar={(conn.Avatar != null ? conn.Avatar.Id : 0)}");
            _playerAvatarEntityId.Remove(disconnKey);
            _playerNextSkillEntityId.Remove(disconnKey);
            _playerSkillsComponentId.Remove(disconnKey);
            _playerSkillSlots.Remove(disconnKey);
            _connections.Remove(conn.ConnId);
            if (conn.LoginName != null) { lock (_dllEndpoints) { _dllEndpoints.Remove(conn.LoginName); } }

            // PVP: clean up queue + forfeit active match on disconnect
            try
            {
                var forfeited = Managers.PVPMatchManager.Instance.HandleDisconnect(conn.LoginName);
                if (forfeited != null) FinalizeMatchResults(forfeited);
            }
            catch (Exception ex) { Debug.LogError($"[PVP] disconnect cleanup: {ex.Message}"); }

            // Social: notify friends this player went offline
            if (conn.LoginName != null && _selectedCharacter.TryGetValue(conn.LoginName, out var disconnChar))
            {
                SocialManager.Instance.PlayerOffline(conn.LoginName, disconnChar.Name, SendSocialViaAuth);
                // Posse: rebroadcast CachedPosseFull to other posse members so they see the offline state.
                try { PosseManager.Instance.NotifyMemberStateChange(disconnChar.Id, this); }
                catch (Exception ex) { Debug.LogError($"[POSSE] disconnect notify failed: {ex.Message}"); }
            }
            else if (conn.LoginName != null)
            {
                // Fallback: remove from online users even without character lookup
                SocialManager.Instance.ForceRemoveOnline(conn.LoginName);
            }
            QueueConnectionBridge.RemoveQueueStream(conn.LoginName);

            conn.Disconnect();
        }

        private void ProcessMessage(RRConnection conn, byte[] data)
        {
            int offset = 0;

            // Loop through all concatenated messages in the buffer (like Rainbow does)
            while (offset < data.Length)
            {
                if (data.Length - offset < 1) break;

                byte messageType = data[offset];
                int messageLen = CalculateMessageLength(data, offset, messageType);

                if (messageLen <= 0 || offset + messageLen > data.Length)
                {
                    Debug.LogError($"[MSG-LOOP] Invalid message length {messageLen} at offset {offset}, remaining {data.Length - offset}");
                    break;
                }

                // Extract this single message
                byte[] singleMessage = new byte[messageLen];
                Array.Copy(data, offset, singleMessage, 0, messageLen);

                ProcessSingleMessage(conn, singleMessage);

                offset += messageLen;
            }
        }

        private int CalculateMessageLength(byte[] data, int offset, byte messageType)
        {
            switch (messageType)
            {
                case 0x02: // Ping - variable, read from buffer
                    return data.Length - offset; // Consume all for ping
                case 0x03: // Connect - 4 bytes total
                    return 4;
                case 0x0A: // CompressedA - 1 + 3 + 4 + bodyLen
                case 0x0E: // CompressedE - 1 + 3 + 4 + bodyLen
                    if (data.Length - offset < 8) return -1;
                    uint bodyLen = BitConverter.ToUInt32(data, offset + 4);
                    return 8 + (int)bodyLen;
                case 0x10: // Direct - need to figure out length
                    return data.Length - offset; // Consume all for now
                default:
                    return data.Length - offset; // Unknown, consume all
            }
        }

        private void ProcessSingleMessage(RRConnection conn, byte[] data)
        {
            MegaCatcher.OnRawTCP(data);
            if (data.Length < 1) return;

            byte messageType = data[0];

            switch (messageType)
            {
                case 0x02: // Ping - don't log these
                    HandlePing(conn, data);
                    break;
                case 0x03:
                    HandleConnect(conn, data);
                    break;
                case 0x0A:
                    HandleCompressedA(conn, data);
                    break;
                case 0x0E:
                    HandleCompressedE(conn, data);
                    break;
                case 0x10:
                    HandleDirectMessage(conn, data);
                    break;
                default:
                    Debug.LogError($"[RAW-IN] UNKNOWN message type: 0x{messageType:X2}");
                    break;
            }
        }

        private void HandlePing(RRConnection conn, byte[] data)
        {
            var writer = new LEWriter();
            writer.WriteByte(0x02);
            if (data.Length > 1)
            {
                byte[] pingData = new byte[data.Length - 1];
                Array.Copy(data, 1, pingData, 0, data.Length - 1);
                writer.WriteBytes(pingData);
            }
            byte[] response = writer.ToArray();
            lock (conn.SendLock)
            {
                conn.Stream.Write(response, 0, response.Length);
            }
        }

        private void HandleConnect(RRConnection conn, byte[] data)
        {
            Debug.Log($"Client {conn.ConnId} sent connect message");

            var reader = new LEReader(data);
            reader.ReadByte(); // Skip message type
            uint clientId = reader.ReadUInt24();
            _peerId24[conn.ConnId] = clientId;

            Debug.Log($"Client peer ID: 0x{clientId:X6}");

            var writer = new LEWriter();
            writer.WriteByte(0x04);
            writer.WriteUInt24((int)clientId);
            writer.WriteUInt32(0);

            byte[] response = writer.ToArray();
            lock (conn.SendLock)
            {
                conn.Stream.Write(response, 0, response.Length);
            }
            Debug.Log($"Sent connect response to client {conn.ConnId}");
        }

        private void HandleCompressedA(RRConnection conn, byte[] data)
        {
            try
            {
                var reader = new LEReader(data);
                reader.ReadByte(); // 0x0A
                uint peerId = reader.ReadUInt24();
                uint bodyLen = reader.ReadUInt32();
                byte channel = reader.ReadByte();
                byte messageType = reader.ReadByte();
                reader.ReadByte(); // 0x00
                uint uncompressedLen = reader.ReadUInt32();

                byte[] compressed = reader.ReadBytes((int)(bodyLen - 7));
                byte[] payload = ZlibUtil.Inflate(compressed);

                HandleChannelMessage(conn, channel, messageType, payload);
            }
            catch (Exception ex)
            {
                Debug.LogError($"HandleCompressedA error: {ex.Message}");
            }
        }

        private void HandleCompressedE(RRConnection conn, byte[] data)
        {
            try
            {
                var reader = new LEReader(data);
                reader.ReadByte(); // 0x0E
                uint dest = reader.ReadUInt24();
                uint bodyLen = reader.ReadUInt24();
                reader.ReadByte(); // 0x00
                uint source = reader.ReadUInt24();
                reader.ReadBytes(5); // Skip 5 bytes
                uint uncompressedLen = reader.ReadUInt32();

                byte[] compressed = reader.ReadBytes((int)(bodyLen - 12));

                byte[] payload = ZlibUtil.Inflate(compressed);

                if (payload.Length >= 2)
                {
                    byte channel = payload[0];
                    byte messageType = payload[1];
                    byte[] innerData = new byte[payload.Length - 2];
                    Array.Copy(payload, 2, innerData, 0, innerData.Length);

                    HandleChannelMessage(conn, channel, messageType, innerData);
                }
                else
                {
                    Debug.LogError($"[E-LANE] Payload too short: {payload.Length} bytes");
                }
            }
            catch (Exception ex)
            {
                Debug.LogError($"[E-LANE] ERROR: {ex.Message}");
            }
        }

        private void HandleDirectMessage(RRConnection conn, byte[] data)
        {
            try
            {
                var reader = new LEReader(data);
                reader.ReadByte(); // 0x10
                uint peerId = reader.ReadUInt24();
                uint bodyLen = reader.ReadUInt24();
                byte channel = reader.ReadByte();
                byte[] payload = reader.ReadBytes((int)bodyLen);

                Debug.Log($"Direct message: peer=0x{peerId:X6}, channel={channel}");
                HandleChannelMessage(conn, channel, 0, payload);
            }
            catch (Exception ex)
            {
                Debug.LogError($"HandleDirectMessage error: {ex.Message}");
            }
        }

        private void HandleChannelMessage(RRConnection conn, byte channel, byte messageType, byte[] data)
        {
            MegaCatcher.OnChannel(channel, messageType, data);

            switch (channel)
            {
                case 0: // Initial connection
                    HandleInitialConnection(conn, messageType, data);
                    break;
                case 3: // Social/UserManager channel (TChannelManager index 3)
                    // Binary-verified: UserManagerClient::start @ 0x601B10 registers at
                    // GatewayClient's TChannelManager slot 3 (push 3 @ 0x601B71).
                    // HandleCompressedE already extracted: channel=3, messageType=socialOp, data=body
                    // messageType IS the social operation (0x00=connect, 0x01=requestRosters,
                    // 0x03=addContact, 0x07=requestUserList, etc.)
                    SocialManager.Instance.HandleMessage(conn, messageType, data, SendSocialViaAuth);
                    break;
                case 4: // Character channel
                    HandleCharacterChannel(conn, messageType, data);
                    break;
                case 6:
                    // Check for admin commands first (Invulnerable, etc.)
                    if (_adminHandler == null)
                    {
                        _adminHandler = new AdminCommandHandler();
                        _adminHandler.SetServerCallbacks(
                            (c, zone) => ChatChangeZone(c, zone),
                            (c) => {
                                if (_selectedCharacter.TryGetValue(c.LoginName, out var ch))
                                    return CharacterRepository.GetCharacter(ch.Id);
                                return null;
                            },
                            HandleAdminLevelUp,
                            (login, gcType, modId) => _modifierTracker.TrackModifier(login, new ActiveModifier
                            {
                                GCType = gcType,
                                Id = modId,
                                Level = 0,
                                PowerLevel = 0,
                                Duration = 0,
                                SourceIsSelf = 0,
                                AddedAt = DateTime.UtcNow
                            }),
                            (login, modId) => _modifierTracker.RemoveModifierById(login, modId),
                            AdminCompleteQuest,
                            (c, w) => { WritePlayerEntitySynch(c, w); }
                        );
                    }
                    {
                        PlayerState adminPs = GetPlayerState(conn.ConnId.ToString());
                        // /adminui commands only for admins
                        if (IsPlayerAdmin(conn.LoginName) && _adminHandler.TryHandleAdminCommand(conn, messageType, data, adminPs, SendSystemMessage, SendToClient))
                            break;
                    }
                    // ═══ Bling Gnome chat commands — available to ALL players ═══
                    // Must come BEFORE ChatCommandHandler which blocks all @ for non-admin
                    {
                        bool handledByGnome = false;
                        try
                        {
                            var peekReader = new LEReader(data);
                            string peekMsg = peekReader.ReadCString();
                            if (peekMsg.StartsWith("@"))
                            {
                                string cmd = peekMsg.Substring(1).Trim().ToLower();
                                if (cmd == "gnome" || cmd == "bling" || cmd == "blinggnome" || cmd == "gs" || cmd == "gnomestatus")
                                {
                                    BlingGnomeManager.Instance.SetServer(this);
                                    BlingGnomeManager.Instance.HandleChatMessage(conn, data, SendCompressedA, SendSystemMessage);
                                    handledByGnome = true;
                                }
                            }
                        }
                        catch { }
                        if (handledByGnome) break;
                    }
                    if (_chatHandler == null) _chatHandler = new ChatCommandHandler(this);
                    if (!_chatHandler.HandleChatMessage(conn, data, SendSystemMessage))
                    {
                        // Fallback — other non-admin @ commands
                    }
                    // ═══ MULTIPLAYER: Chat relay ═══
                    {
                        try
                        {
                            var chatReader = new LEReader(data);
                            string chatText = chatReader.ReadCString();
                            if (!string.IsNullOrEmpty(chatText) && !chatText.StartsWith("/") && !chatText.StartsWith("@"))
                            {
                                BroadcastChatToZone(conn, chatText);
                            }
                        }
                        catch (Exception ex)
                        {
                            Debug.LogError($"[CHAT-RELAY] Error: {ex.Message}");
                        }
                    }
                    break;
                case 7: // ClientEntity channel
                    HandleClientEntityChannel(conn, messageType, data);
                    break;
                case 9: // Group channel
                    HandleGroupChannel(conn, messageType, data);
                    break;
                case 12: // Social/UserManager channel
                    SocialManager.Instance.HandleMessage(conn, messageType, data, SendSocialViaAuth);
                    break;
                case 13: // QuestManager channel
                    Debug.LogError($"[CH13] ████ type=0x{messageType:X2} dataLen={data?.Length ?? 0} hex={(data != null && data.Length > 0 ? BitConverter.ToString(data, 0, Math.Min(30, data.Length)) : "EMPTY")} ████");
                    if (messageType == 0x07)
                    {
                        Debug.LogError($"[CH13] → Routing to goToCheckpoint (0x07)");
                        HandleCheckpointTeleportRequest(conn, data);
                    }
                    else if (messageType == 0x0C)
                    {
                        Debug.LogError($"[CH13] → Routing to Obelisk (0x0C)");
                        HandleObeliskTeleport(conn);
                    }
                    else if (messageType == 0x0B)
                    {
                        Debug.LogError($"[CH13] → Routing to SavedPlace (0x0B)");
                        HandleSavedPlaceTeleport(conn);
                    }
                    else
                    {
                        Debug.LogError($"[CH13] → UNHANDLED type 0x{messageType:X2} — routing to HandleZoneChannel");
                        HandleZoneChannel(conn, data);
                    }
                    break;
                case 11: // GroupClient channel (0x0B) — per binary VA 0x458B9B
                    HandleGroupClientChannel(conn, messageType, data);
                    break;
                case 15: // PosseClient channel (0x0F) — binary-verified via Ghidra (2026-05-16)
                    // PosseClient::start @ 0x00610610 has PUSH 0xf @ 0x00610676 immediately
                    // before CALL TChannelManager<>::createChannel @ 0x0061067F. Dispatch
                    // jump table for incoming messages lives at 0x00611F60. See PosseManager.cs
                    // header for the full opcode map.
                    PosseManager.Instance.HandleMessage(conn, messageType, data, SendSocialViaAuth, this);
                    break;
                default:
                    {
                        // Unknown-channel canary. PosseClient (slot 15) is wired above; any other
                        // channel that surfaces here is a still-unmapped gateway client
                        // (TradeClient candidates etc.). Keep the [POSSE-PROBE] prefix so the
                        // existing RuntimeEvidenceManager.IsFocusedLog entry continues to surface
                        // it in server.log.
                        string hex = (data != null && data.Length > 0)
                            ? BitConverter.ToString(data, 0, Math.Min(48, data.Length))
                            : "EMPTY";
                        Debug.LogError($"[POSSE-PROBE] Unhandled channel={channel} type=0x{messageType:X2} dataLen={data?.Length ?? 0} hex={hex}");
                    }
                    break;
            }
        }

        private void HandleCheckpointTeleportRequest(RRConnection conn, byte[] data)
        {
            Debug.LogError($"[CP-TELEPORT] ═══════════════════════════════════════════════════");
            Debug.LogError($"[CP-TELEPORT] Data hex: {BitConverter.ToString(data ?? new byte[0])}");

            try
            {
                if (data == null || data.Length < 1)
                {
                    Debug.LogError($"[CP-TELEPORT] ❌ Empty data");
                    return;
                }

                // Parse GC type tag format (matches binary readType @ 0x5E3C40)
                // Tag 0xFF = [0xFF][cstring\0]  (full class name)
                // Tag 0x00 = null reference
                // Tag 0x01 = [0x01][byte index]
                byte tag = data[0];
                string checkpointName = null;

                if (tag == 0xFF && data.Length > 2)
                {
                    // Read null-terminated string
                    int end = System.Array.IndexOf(data, (byte)0x00, 1);
                    if (end > 1)
                        checkpointName = System.Text.Encoding.ASCII.GetString(data, 1, end - 1);
                    Debug.LogError($"[CP-TELEPORT] Tag 0xFF → checkpoint name: '{checkpointName}'");
                }
                else if (tag == 0x00)
                {
                    Debug.LogError($"[CP-TELEPORT] Tag 0x00 = null ref — using obelisk rotator");
                    HandleObeliskTeleport(conn);
                    return;
                }
                else
                {
                    Debug.LogError($"[CP-TELEPORT] ❌ Unknown tag: 0x{tag:X2}");
                    return;
                }

                if (string.IsNullOrEmpty(checkpointName))
                {
                    Debug.LogError($"[CP-TELEPORT] ❌ Empty checkpoint name");
                    return;
                }

                // Look up checkpoint directly by GC class name
                var checkpoint = DatabaseLoader.Checkpoints.FirstOrDefault(c =>
                    c.id.Equals(checkpointName, StringComparison.OrdinalIgnoreCase));

                if (checkpoint == null)
                {
                    Debug.LogError($"[CP-TELEPORT] ❌ Checkpoint not in database: '{checkpointName}'");
                    return;
                }

                string destinationZone = checkpoint.zone;
                Debug.LogError($"[CP-TELEPORT] 🚀 Teleporting to '{destinationZone}' via checkpoint '{checkpointName}'");

                // Get destination zone's spawn point
                var destZone = _zones.Values.FirstOrDefault(z =>
                    z.name.Equals(destinationZone, StringComparison.OrdinalIgnoreCase));

                if (destZone != null)
                {
                    conn.PendingSpawnX = destZone.spawnX;
                    conn.PendingSpawnY = destZone.spawnY;
                    conn.PendingSpawnZ = destZone.spawnZ;
                }

                ChangeZone(conn, destinationZone, "");
            }
            catch (Exception ex)
            {
                Debug.LogError($"[CP-TELEPORT] ❌ Error: {ex.Message}\n{ex.StackTrace}");
            }
        }

        // Track last obelisk click index per player for cycling through destinations
        private Dictionary<string, int> _obeliskClickIndex = new Dictionary<string, int>();
        private Dictionary<string, string> _checkpointZoneMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

        private void HandleObeliskTeleport(RRConnection conn)
        {
            try
            {
                string connId = conn.ConnId.ToString();
                var playerState = QuestManager.Instance.GetPlayerState(connId);
                if (playerState == null) { Debug.LogError("[OBELISK] No player state"); return; }

                string currentZone = "";
                if (_zones.TryGetValue(conn.CurrentZoneId, out Zone cz))
                    currentZone = cz.name;

                // Build sorted list of available obelisk checkpoints (matching client dialog order)
                var available = new List<(string id, int order, string zone)>();
                foreach (var cpId in playerState.UnlockedCheckpoints)
                {
                    var cp = DatabaseLoader.Checkpoints.FirstOrDefault(c =>
                        c.id.Equals(cpId, StringComparison.OrdinalIgnoreCase));
                    if (cp == null) continue;
                    if (cp.zone.Equals(currentZone, StringComparison.OrdinalIgnoreCase)) continue;
                    available.Add((cpId, cp.order, cp.zone));
                }
                available.Sort((a, b) => a.order.CompareTo(b.order));

                if (available.Count == 0)
                {
                    Debug.LogError("[OBELISK] No available checkpoints");
                    return;
                }

                // Cycle through checkpoints on each click
                if (!_obeliskClickIndex.ContainsKey(connId))
                    _obeliskClickIndex[connId] = 0;
                int idx = _obeliskClickIndex[connId] % available.Count;
                _obeliskClickIndex[connId] = idx + 1;

                var selected = available[idx];
                Debug.LogError($"[OBELISK] Teleporting to '{selected.zone}' (checkpoint {selected.id}, index {idx}/{available.Count})");

                var checkpoint = DatabaseLoader.Checkpoints.FirstOrDefault(c =>
                    c.id.Equals(selected.id, StringComparison.OrdinalIgnoreCase));
                if (checkpoint == null) return;

                var destZone = _zones.Values.FirstOrDefault(z =>
                    z.name.Equals(checkpoint.zone, StringComparison.OrdinalIgnoreCase));
                if (destZone != null)
                {
                    conn.PendingSpawnX = destZone.spawnX;
                    conn.PendingSpawnY = destZone.spawnY;
                    conn.PendingSpawnZ = destZone.spawnZ;
                }

                ChangeZone(conn, checkpoint.zone, "");
            }
            catch (Exception ex)
            {
                Debug.LogError($"[OBELISK] Error: {ex.Message}");
            }
        }

        private void HandleSavedPlaceTeleport(RRConnection conn)
        {
            try
            {
                // Saved Place = town portal return point
                if (conn.HasSavedTownPortal && !string.IsNullOrEmpty(conn.TownPortalZoneName))
                {
                    Debug.LogError($"[SAVED-PLACE] Teleporting to saved portal: {conn.TownPortalZoneName}");
                    ChangeZone(conn, conn.TownPortalZoneName, "");
                }
                else
                {
                    Debug.LogError("[SAVED-PLACE] No saved town portal — defaulting to town");
                    ChangeZone(conn, "town", "");
                }
            }
            catch (Exception ex)
            {
                Debug.LogError($"[SAVED-PLACE] Error: {ex.Message}");
            }
        }




        public void SendSystemMessage(RRConnection conn, string message)
        {
            var writer = new LEWriter();
            writer.WriteByte(0x06);
            writer.WriteByte(0x00);
            writer.WriteByte(0x0D);
            foreach (char c in message)
            {
                writer.WriteByte((byte)c);
            }
            writer.WriteByte(0x00);
            SendCompressedA(conn, 0x01, 0x0F, writer.ToArray());
        }

        // ===========================================================================
        // SendBossGatePopup - fires the on-screen popup via the proven QuestManager
        // wire path. TTD-verified call stack from a working wolf-tracking quest kill:
        //
        //   ClientEntityManager::processMessage
        //   -> processComponentUpdate (CEM 0x35)
        //   -> QuestManager::processUpdate (vtable lookup by component id)
        //   -> processUpdateQuest (submsg 0x03)
        //   -> Quest::processUpdate (submsg 0x01 = readObjectives)
        //   -> on objective state change, fires DFCEvent 0x4C400
        //   -> EventChannel::doEvent -> WorldUI::doEvent -> WorldUI::addInfo
        //   -> on-screen popup appears with the objective label as text
        //
        // Sequence: Add fake quest -> Progress packet (state change fires popup) ->
        // Remove fake quest. The fake quest uses Q02_a2 type hash so the client can
        // resolve the type, instanceId 0xFFFFFF00 to avoid conflicts with real quests.
        // Wire format mirrors QuestManager.SendAddPacket / SendProgressPacket /
        // SendRemovePacket exactly, but the objective label is written as raw text
        // (no ": current / required" suffix) so the popup shows clean text.
        // ===========================================================================
        private void SendBossGatePopup(RRConnection conn)
        {
            if (conn == null || !conn.IsConnected || conn.QuestManagerId == 0) return;

            const uint fakeInstanceId = 0xFFFFFF00u;
            // EXPERIMENT: try wrapping in chat-style font tags. If WorldUI::addInfo shares
            // the chat renderer, you get big white glowing text. If it uses a different
            // renderer, you will see literal "<font...>" text and we revert to plain.
            const string popupText = "<font color=white effect=glow>The boss gate is open!</font>";

            // Resolve the Q02_a2 type hash from the loaded quest database. The client
            // already knows this quest type from BossGate-related .gc files, so the
            // GCClassRegistry lookup inside processAddQuest will succeed.
            var q02a2 = DatabaseLoader.Quests.FirstOrDefault(q =>
                string.Equals(q.id, "world.dungeon00.quest.Q02_a2", StringComparison.OrdinalIgnoreCase));
            if (q02a2 == null)
            {
                Debug.LogError("[BOSS-POPUP] Q02_a2 quest not found in database; cannot send popup");
                return;
            }
            uint typeHash = q02a2.hash != 0 ? q02a2.hash : DatabaseLoader.ComputeDJB2Hash(q02a2.id);

            // ----- 1. AddPacket: create fake quest with one INCOMPLETE objective -----
            var addW = new LEWriter();
            addW.WriteByte(0x07);                       // BeginStream
            addW.WriteByte(0x35);                       // processComponentUpdate (CEM)
            addW.WriteUInt16(conn.QuestManagerId);      // QM component
            addW.WriteByte(0x01);                       // QM submsg = AddQuest
            addW.WriteByte(0x04);                       // type marker = uint32 hash
            addW.WriteUInt32(typeHash);                 // Q02_a2 hash
            addW.WriteUInt32(fakeInstanceId);           // synthetic instance id
            addW.WriteByte(0x00);                       // allComplete = false
            addW.WriteByte(0x01);                       // 1 objective
            addW.WriteByte(0x02);                       // flags = has-required (0x02), not-complete
            // Raw label, NO count suffix
            foreach (char c in popupText) addW.WriteByte((byte)c);
            addW.WriteByte(0x00);                       // cstring null terminator
            addW.WriteUInt16(0x0002);                   // required = 2 (Progress will use 1 for state change)
            if (!WritePlayerEntitySynch(conn, addW)) return;
            addW.WriteByte(0x06);                       // EndStream
            SendCompressedA(conn, 0x01, 0x0F, addW.ToArray());

            // ----- 2. ProgressPacket: state change WITHOUT marking complete -----
            // The Add packet wrote required=2; this Progress writes required=1 with the
            // SAME label. Quest::processUpdate sees the field change and fires the popup
            // event, but flags=0x02 (no 0x01 complete bit) means the client should NOT
            // append " (complete)" to the displayed label.
            var progW = new LEWriter();
            progW.WriteByte(0x07);
            progW.WriteByte(0x35);
            progW.WriteUInt16(conn.QuestManagerId);
            progW.WriteByte(0x03);                      // QM submsg = processUpdateQuest
            progW.WriteUInt32(fakeInstanceId);          // same instance
            progW.WriteByte(0x01);                      // Quest submsg = readObjectives
            progW.WriteByte(0x01);                      // 1 objective
            progW.WriteByte(0x02);                      // flags = has-required ONLY (no complete bit)
            foreach (char c in popupText) progW.WriteByte((byte)c);
            progW.WriteByte(0x00);                      // cstring terminator
            progW.WriteUInt16(0x0001);                  // required = 1 (Add had 2 so state changes)
            if (!WritePlayerEntitySynch(conn, progW)) return;
            progW.WriteByte(0x06);                      // EndStream
            SendCompressedA(conn, 0x01, 0x0F, progW.ToArray());

            // ----- 3. RemovePacket: clean up the fake quest from the client log -----
            var rmW = new LEWriter();
            rmW.WriteByte(0x07);
            rmW.WriteByte(0x35);
            rmW.WriteUInt16(conn.QuestManagerId);
            rmW.WriteByte(0x02);                        // QM submsg = RemoveQuest
            rmW.WriteUInt32(fakeInstanceId);
            if (!WritePlayerEntitySynch(conn, rmW)) return;
            rmW.WriteByte(0x06);                        // EndStream
            SendCompressedA(conn, 0x01, 0x0F, rmW.ToArray());

            Debug.LogError($"[BOSS-POPUP] Sent Add+Progress+Remove popup sequence to {conn.LoginName} (instance=0x{fakeInstanceId:X8} hash=0x{typeHash:X8})");
        }

        /// <summary>
        /// Wraps a message in font color/effect tags for the client's HTML renderer.
        /// Supported: color=#RRGGBB, effect=glow
        /// If the message already contains font tags, returns it unchanged.
        /// </summary>
        public static string WrapChatColor(string message, string color, string effect)
        {
            if (string.IsNullOrEmpty(message)) return message;
            // Don't double-wrap if message already has font tags
            if (message.Contains("<font")) return message;

            bool hasColor = !string.IsNullOrEmpty(color);
            bool hasEffect = !string.IsNullOrEmpty(effect) && effect != "none";

            if (!hasColor && !hasEffect) return message;

            string attrs = "";
            if (hasColor) attrs += $" color={color}";
            if (hasEffect) attrs += $" effect={effect}";

            return $"<font{attrs}>{message}</font>";
        }

        /// <summary>
        /// Send a UDP packet to DSOUND.dll. Uses NAT-punched endpoint if available (remote),
        /// otherwise falls back to direct send to tcpIP:2605 (localhost/LAN).
        /// </summary>
        private void SendToDll(RRConnection conn, byte[] packet)
        {
            System.Net.IPEndPoint natEP = null;
            if (conn.LoginName != null) { lock (_dllEndpoints) { _dllEndpoints.TryGetValue(conn.LoginName, out natEP); } }
            if (natEP != null)
            {
                _udpListener.Send(packet, packet.Length, natEP);
            }
            else
            {
                var tcpEP = conn.Client?.Client?.RemoteEndPoint as System.Net.IPEndPoint;
                if (tcpEP == null) return;
                var fallback = new System.Net.IPEndPoint(tcpEP.Address, 2605);
                using (var sender = new System.Net.Sockets.UdpClient()) { sender.Send(packet, packet.Length, fallback); }
            }
        }

        /// <summary>
        /// Send 0xE0 UDP packet to DSOUND.dll on port 2605 to trigger hotbar UI refresh.
        /// DLL fires 0x141F event from main thread which rebuilds Skills UI.
        /// </summary>
        private void SendHotbarRefreshToDll(RRConnection conn, string skillName, uint slotId)
        {
            try
            {
                var tcpEP = conn.Client.Client.RemoteEndPoint as System.Net.IPEndPoint;
                if (tcpEP == null) { Debug.LogError("[HOTBAR-DLL] Cannot get client IP"); return; }
                byte[] nameBytes = System.Text.Encoding.ASCII.GetBytes(skillName);
                byte[] packet = new byte[6 + nameBytes.Length];
                packet[0] = 0xE0;
                BitConverter.GetBytes(slotId).CopyTo(packet, 1);
                packet[5] = (byte)nameBytes.Length;
                System.Array.Copy(nameBytes, 0, packet, 6, nameBytes.Length);
                SendToDll(conn, packet);
                Debug.LogError($"[HOTBAR-DLL] Sent 0xE0 slot={slotId} '{skillName}'");
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"[HOTBAR-DLL] Send failed: {ex.Message}");
            }
        }

        /// <summary>
        /// Send 0x10 UDP packet to DSOUND.dll on port 2605 with GlobalKnobs overrides.
        /// DLL patches RPGSettings in memory.
        /// Per-player: checks free_KEY or member_KEY prefix first, falls back to KEY.
        /// Protocol: [0x10][count:u8][{offset:u16, writeType:u8, value:u32}...]
        ///   writeType: 0=uint32, 1=uint16
        /// </summary>
        private void SendGlobalKnobsToDLL(RRConnection conn)
        {
            Debug.LogError("[KNOBS] RPGSettings override packet skipped; native GlobalKnobs stay package-authored");
        }

        /// <summary>
        /// Send 0x12 UDP to DSOUND.dll — controls membership mode.
        /// DLL calls setFreePlayer/clearFreePlayer + patches XP multiplier.
        /// Protocol: [0x12][u8 isFree][f32 xpMult]
        /// </summary>
        private void SendMembershipToDLL(RRConnection conn)
        {
            try
            {
                var tcpEP = conn.Client.Client.RemoteEndPoint as System.Net.IPEndPoint;
                if (tcpEP == null) return;

                bool isFree = IsPlayerFree(conn.LoginName);
                bool isAdmin = IsPlayerAdmin(conn.LoginName);
                float xpMult = GCDatabase.Instance.GetKnob("FreePlayerExperienceMult", 0.87f);

                byte[] packet = new byte[11];
                packet[0] = 0x12;
                packet[1] = isFree ? (byte)1 : (byte)0;
                System.BitConverter.GetBytes(xpMult).CopyTo(packet, 2);
                packet[6] = isAdmin ? (byte)1 : (byte)0;
                System.BitConverter.GetBytes(conn.DllSessionToken).CopyTo(packet, 7);

                SendToDll(conn, packet);
                Debug.LogError($"[MEMBER] Sent isFree={isFree} isAdmin={isAdmin} xpMult={xpMult} token=0x{conn.DllSessionToken:X8} to DLL");
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"[MEMBER] Send failed: {ex.Message}");
            }
        }

        /// <summary>
        /// Load account flags from DB on login. Returns false if banned.
        /// Sets _playerIsAdmin and _playerIsFree caches, updates last_login.
        /// </summary>
        private bool LoadAccountFlags(string loginName)
        {
            try
            {
                using (var db = Database.GameDatabase.GetConnection())
                {
                    using (var reader = Database.GameDatabase.ExecuteReader(db,
                        "SELECT is_member, is_banned, is_admin FROM accounts WHERE username = @name",
                        ("@name", loginName)))
                    {
                        if (reader.Read())
                        {
                            int isMember = reader.GetInt32(0);
                            int isBanned = reader.GetInt32(1);
                            int isAdmin = reader.GetInt32(2);

                            _playerIsFree[loginName] = (isMember == 0);
                            _playerIsAdmin[loginName] = (isAdmin != 0);

                            Debug.LogError($"[ACCOUNT] {loginName}: member={isMember} banned={isBanned} admin={isAdmin}");

                            if (isBanned != 0)
                            {
                                Debug.LogError($"[ACCOUNT] ⛔ {loginName} is BANNED — rejecting connection");
                                return false;
                            }
                        }
                    }

                    // Update last_login
                    Database.GameDatabase.ExecuteNonQuery(db,
                        "UPDATE accounts SET last_login = datetime('now') WHERE username = @name",
                        ("@name", loginName));
                }
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"[ACCOUNT] Error loading flags for {loginName}: {ex.Message}");
            }
            return true;
        }

        /// <summary>
        /// Check if player has admin role.
        /// </summary>
        public bool IsPlayerAdmin(string loginName)
        {
            if (_playerIsAdmin.TryGetValue(loginName, out bool cached))
                return cached;
            // Not cached — load from DB
            try
            {
                using (var db = Database.GameDatabase.GetConnection())
                {
                    object result = Database.GameDatabase.ExecuteScalar(db,
                        "SELECT is_admin FROM accounts WHERE username = @name",
                        ("@name", loginName));
                    if (result != null && result != System.DBNull.Value)
                    {
                        bool isAdmin = System.Convert.ToInt32(result) != 0;
                        _playerIsAdmin[loginName] = isAdmin;
                        return isAdmin;
                    }
                }
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"[ACCOUNT] Admin check error for {loginName}: {ex.Message}");
            }
            return false;
        }

        /// <summary>
        /// Set admin flag in DB.
        /// </summary>
        private void SetPlayerAdmin(string loginName, bool isAdmin)
        {
            _playerIsAdmin[loginName] = isAdmin;
            try
            {
                using (var db = Database.GameDatabase.GetConnection())
                {
                    Database.GameDatabase.ExecuteNonQuery(db,
                        "UPDATE accounts SET is_admin = @admin WHERE username = @name",
                        ("@name", loginName), ("@admin", isAdmin ? 1 : 0));
                    // Admins are always members — set is_member=1 in DB
                    if (isAdmin)
                    {
                        Database.GameDatabase.ExecuteNonQuery(db,
                            "UPDATE accounts SET is_member = 1 WHERE username = @name",
                            ("@name", loginName));
                        Debug.LogError($"[ACCOUNT] {loginName} admin=true, is_member=1 (admin→member)");
                    }
                    else
                        Debug.LogError($"[ACCOUNT] {loginName} admin={isAdmin}");
                }
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"[ACCOUNT] Set admin error: {ex.Message}");
            }
        }

        /// <summary>
        /// Set banned flag in DB.
        /// </summary>
        private void SetPlayerBanned(string loginName, bool isBanned)
        {
            try
            {
                using (var db = Database.GameDatabase.GetConnection())
                    Database.GameDatabase.ExecuteNonQuery(db,
                        "UPDATE accounts SET is_banned = @ban WHERE username = @name",
                        ("@name", loginName), ("@ban", isBanned ? 1 : 0));
                Debug.LogError($"[ACCOUNT] {loginName} banned={isBanned}");
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"[ACCOUNT] Set banned error: {ex.Message}");
            }
        }

        public void SetPlayerAdminPublic(string loginName, bool isAdmin) { SetPlayerAdmin(loginName, isAdmin); }
        public void SetPlayerBannedPublic(string loginName, bool isBanned) { SetPlayerBanned(loginName, isBanned); }

        private IEnumerator DelayedBanDisconnect(RRConnection conn)
        {
            yield return new UnityEngine.WaitForSeconds(3.0f);
            try { SendSystemMessage(conn, "Your account has been banned. Contact an administrator."); } catch { }
            yield return new UnityEngine.WaitForSeconds(2.0f);
            Debug.LogError($"[ACCOUNT] Disconnecting banned user: {conn.LoginName}");
            try { conn.Client.Close(); } catch { }
        }
        private bool IsPlayerFree(string loginName)
        {
            // Admins always get member settings
            if (IsPlayerAdmin(loginName)) return false;

            if (_playerIsFree.TryGetValue(loginName, out bool cached))
                return cached;

            // Check DB
            try
            {
                using (var db = Database.GameDatabase.GetConnection())
                {
                    object result = Database.GameDatabase.ExecuteScalar(db,
                        "SELECT is_member FROM accounts WHERE username = @name",
                        ("@name", loginName));
                    if (result != null && result != System.DBNull.Value)
                    {
                        bool isFree = System.Convert.ToInt32(result) == 0;  // is_member=0 → free
                        _playerIsFree[loginName] = isFree;
                        return isFree;
                    }
                }
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"[MEMBER] DB read error for {loginName}: {ex.Message}");
            }

            _playerIsFree[loginName] = false;
            Debug.LogError($"[MEMBER] Missing DB membership for {loginName}; defaulting to MEMBER");
            return false;
        }

        /// <summary>
        /// Set a player's membership in DB + cache. true=free, false=member.
        /// </summary>
        private void SetPlayerMembership(string loginName, bool isFree)
        {
            _playerIsFree[loginName] = isFree;
            try
            {
                using (var db = Database.GameDatabase.GetConnection())
                    Database.GameDatabase.ExecuteNonQuery(db,
                        "UPDATE accounts SET is_member = @member WHERE username = @name",
                        ("@name", loginName), ("@member", isFree ? 0 : 1));
                Debug.LogError($"[MEMBER] Saved {loginName} = {(isFree ? "FREE" : "MEMBER")}");
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"[MEMBER] DB save error: {ex.Message}");
            }
        }



        private void HandleInitialConnection(RRConnection conn, byte messageType, byte[] data)
        {
            if (VerbosePacketLogging)
                Debug.Log($"Initial connection message type: 0x{messageType:X2}, data length: {data.Length}");

            // 🔧 CRITICAL FIX: Ignore empty 0x02 messages (heartbeat/keep-alive)
            if (messageType == 0x02 && data.Length == 0)
            {
                if (VerbosePacketLogging)
                    Debug.Log("Ignoring empty channel 0 type 0x02 message (heartbeat/keep-alive)");
                return;
            }

            if (messageType == 0x00 && data.Length >= 5)
            {
                var reader = new LEReader(data);
                byte subtype = reader.ReadByte();
                uint oneTimeKey = reader.ReadUInt32();

                Debug.Log($"OneTimeKey: 0x{oneTimeKey:X8}");

                if (!GlobalSessions.TryConsume(oneTimeKey, out var user) || string.IsNullOrEmpty(user))
                {
                    if (conn.LoginName != null)
                    {
                        user = conn.LoginName;
                        Debug.LogError($"[QUEUE] Accepting queue connection for {user} (no OneTimeKey needed)");
                    }
                    else
                    {
                        Debug.LogError($"Invalid OneTimeKey 0x{oneTimeKey:X8}");
                        return;
                    }
                }

                conn.LoginName = user;
                _users[conn.ConnId] = user;
                LoadAccountFlags(user);  // Load flags, ban check at spawn time
                if (conn.DllSessionToken == 0)
                {
                    conn.DllSessionToken = (uint)(new System.Random().Next(1, int.MaxValue));
                    Debug.LogError($"[DLL-TOKEN] Generated token 0x{conn.DllSessionToken:X8} for {user}");
                }
                Debug.Log($"Initial login SUCCESS for user '{user}'");

                // Send 0x10 message with channel 0x0A
                var ack = new LEWriter();
                ack.WriteByte(0x03);
                SendMessage0x10(conn, 0x0A, ack.ToArray());

                // Send A-lane advance message
                var advance = new LEWriter();
                advance.WriteUInt24(0x00B2B3B4);
                advance.WriteByte(0x00);
                SendCompressedA(conn, 0x00, 0x03, advance.ToArray());
                Debug.Log($"Sent advance message");

                // Start character flow
                StartCharacterFlow(conn);
            }
            else
            {
                Debug.LogWarning($"Unhandled initial connection: type=0x{messageType:X2}, length={data.Length}");
            }
        }

        private void StartCharacterFlow(RRConnection conn)
        {
            Debug.LogError($"[STARTFLOW] StartCharacterFlow for {conn.LoginName}");

            // Force reload from JSON to get latest data
            /* DB always current — no reload needed */
            ;

            // Load characters from JSON into _persistentCharacters
            var savedCharacters = CharacterRepository.GetCharactersForAccount(conn.LoginName);
            Debug.LogError($"[STARTFLOW] GetCharactersForAccount('{conn.LoginName}') returned {savedCharacters?.Count ?? 0} characters");

            _persistentCharacters[conn.LoginName] = new List<GCObject>();

            foreach (var savedChar in savedCharacters)
            {
                var gcObj = new GCObject
                {
                    Id = savedChar.id,
                    NativeClass = "Player",
                    GCClass = "Player",
                    Name = savedChar.name
                };
                _persistentCharacters[conn.LoginName].Add(gcObj);
                Debug.LogError($"[STARTFLOW] Added character: {savedChar.name} (ID={savedChar.id})");
            }

            Debug.LogError($"[STARTFLOW] Total characters loaded: {_persistentCharacters[conn.LoginName].Count}");
        }

        private void SendMessage0x10(RRConnection conn, byte channel, byte[] payload)
        {
            try
            {
                uint clientId = GetClientId24(conn.ConnId);
                uint bodyLen = (uint)(payload?.Length ?? 0);

                var writer = new LEWriter();
                writer.WriteByte(0x10);
                writer.WriteUInt24((int)clientId);
                writer.WriteUInt24((int)bodyLen);
                writer.WriteByte(channel);
                if (bodyLen > 0) writer.WriteBytes(payload);

                byte[] data = writer.ToArray();
                lock (conn.SendLock)
                {
                    conn.Stream.Write(data, 0, data.Length);
                }

                Debug.Log($"Sent 0x10: peer=0x{clientId:X6}, bodyLen={bodyLen}, channel=0x{channel:X2}");
            }
            catch (Exception ex)
            {
                Debug.LogError($"SendMessage0x10 error: {ex.Message}");
            }
        }

        private void HandleCharacterChannel(RRConnection conn, byte messageType, byte[] data)
        {
            Debug.LogError($"[CHARACTER-CHANNEL] Received message type: 0x{messageType:X2}, data length: {data?.Length ?? 0}");

            switch (messageType)
            {
                case 0: // CharacterConnected request
                    Debug.Log($"Client sent 4/0 request - sending character connected response");
                    var connMsg = new LEWriter();
                    connMsg.WriteByte(4);
                    connMsg.WriteByte(0);
                    SendCompressedA(conn, 0x01, 0x0F, connMsg.ToArray());
                    Debug.Log($"Sent 4/0 character connected response");
                    break;

                case 1: // UI nudge
                    Debug.Log($"Client sent UI nudge (4/1) - sending ack");
                    var ack = new LEWriter();
                    ack.WriteByte(4);
                    ack.WriteByte(1);
                    ack.WriteUInt32(0);
                    SendCompressedA(conn, 0x01, 0x0F, ack.ToArray());
                    Debug.Log($"Sent 4/1 ack");
                    break;

                case 2: // 🔥 CHARACTER CREATION REQUEST
                    Debug.LogError($"[CHAR-CREATE] *** RECEIVED CHARACTER CREATION REQUEST (4/2) ***");
                    Debug.LogError($"[CHAR-CREATE] Data: {BitConverter.ToString(data ?? new byte[0])}");
                    HandleCharacterCreate(conn, data);
                    break;

                case 3: // Get character list
                    Debug.LogError($"[CHAR-CHANNEL] Case 3 - calling SendCharacterList NOW");
                    try
                    {
                        SendCharacterList(conn);
                    }
                    catch (Exception ex)
                    {
                        Debug.LogError($"[CHAR-CHANNEL] EXCEPTION in SendCharacterList: {ex.Message}\n{ex.StackTrace}");
                    }
                    Debug.LogError($"[CHAR-CHANNEL] Case 3 - SendCharacterList returned");
                    break;

                case 4: // 🔥 CHARACTER DELETE REQUEST
                    Debug.LogError($"[CHAR-DELETE] *** RECEIVED CHARACTER DELETE REQUEST (4/4) ***");
                    Debug.LogError($"[CHAR-DELETE] Data: {BitConverter.ToString(data ?? new byte[0])}");
                    HandleCharacterDelete(conn, data);
                    break;

                case 5: // Play character
                    HandleCharacterPlay(conn, data);
                    break;

                default:
                    Debug.LogWarning($"Unhandled character message: 0x{messageType:X2}");
                    Debug.LogWarning($"Data: {BitConverter.ToString(data ?? new byte[0])}");
                    break;
            }
        }
        private void HandleCharacterCreate(RRConnection conn, byte[] data)
        {
            Debug.LogError("[CHAR-CREATE] ═══════════════════════════════════════════════════════════");
            Debug.LogError($"[CHAR-CREATE] Data hex: {BitConverter.ToString(data)}");

            try
            {
                var reader = new LEReader(data);
                string characterName = reader.ReadCString();
                string avatarClass = reader.ReadCString();

                Debug.LogError($"[CHAR-CREATE] Name: '{characterName}', AvatarClass: '{avatarClass}'");

                // Read appearance bytes (5 bytes after avatar class)
                byte skin = 0, face = 0, faceFeature = 0, hair = 0, hairColor = 0;
                if (reader.Remaining >= 5)
                {
                    skin = reader.ReadByte();
                    face = reader.ReadByte();
                    faceFeature = reader.ReadByte();
                    hair = reader.ReadByte();
                    hairColor = reader.ReadByte();
                    Debug.LogError($"[CHAR-CREATE] Appearance: Skin={skin}, Face={face}, FaceFeature={faceFeature}, Hair={hair}, HairColor={hairColor}");
                }

                // Map avatar class to class name
                string className = "Fighter";
                if (avatarClass.Contains("Fighter")) className = "Fighter";
                else if (avatarClass.Contains("Warlock") || avatarClass.Contains("Mage")) className = "Mage";
                else if (avatarClass.Contains("Ranger")) className = "Ranger";

                // Create character in ClassConfig (this saves to JSON)
                var savedChar = CharacterRepository.CreateCharacter(characterName, className, AccountRepository.GetAccountId(conn.LoginName), conn.LoginName, avatarClass);
                if (savedChar == null)
                {
                    Debug.LogError("[CHAR-CREATE] ❌ CharacterRepository.CreateCharacter returned null!");
                    return;
                }

                // Save the full avatar class for gender AND appearance
                savedChar.avatarClass = avatarClass;
                savedChar.skin = skin;
                savedChar.face = face;
                savedChar.faceFeature = faceFeature;
                savedChar.hair = hair;
                savedChar.hairColor = hairColor;
                CharacterRepository.SaveCharacter(savedChar);

                Debug.LogError($"[CHAR-CREATE] ✅ Created saved character ID={savedChar.id}, AvatarClass={avatarClass}");

                // Create GCObject for persistent characters list
                var newCharacter = new GCObject
                {
                    Id = savedChar.id,
                    NativeClass = "Player",
                    GCClass = "Player",
                    Name = characterName
                };

                if (!_persistentCharacters.ContainsKey(conn.LoginName))
                {
                    _persistentCharacters[conn.LoginName] = new List<GCObject>();
                }
                _persistentCharacters[conn.LoginName].Add(newCharacter);

                // Build full Player object for response
                GCObject tempChar = GCObjectFactory.NewPlayer(characterName);
                tempChar.Id = savedChar.id;

                var avatar = GCObjectFactory.LoadAvatar(savedChar);
                avatar.Id = _nextEntityId++;

                // Assign IDs to avatar children
                foreach (var child in avatar.Children)
                {
                    child.Id = _nextEntityId++;
                    if (child.Children != null)
                    {
                        foreach (var grandchild in child.Children)
                        {
                            if (grandchild.Id == 0)
                                grandchild.Id = _nextEntityId++;
                        }
                    }
                }

                tempChar.AddChild(avatar);

                var procMod = GCObjectFactory.NewProcModifier();
                procMod.Id = _nextEntityId++;
                tempChar.AddChild(procMod);

                // Send create response: [channel][type][ID][name][Player object]
                var writer = new LEWriter();
                writer.WriteByte(4);
                writer.WriteByte(2);
                writer.WriteUInt32(savedChar.id);
                writer.WriteCString(characterName);
                tempChar.WriteFullGCObject(writer);

                SendCompressedA(conn, 0x01, 0x0F, writer.ToArray());
                Debug.LogError($"[CHAR-CREATE] ✅ Sent create response with full Player object");
            }
            catch (Exception ex)
            {
                Debug.LogError($"[CHAR-CREATE] ❌ Error: {ex.Message}\n{ex.StackTrace}");
            }
        }
        private void SendCharacterCreateResponse(RRConnection conn, bool success, string errorMessage)
        {
            var writer = new LEWriter();
            writer.WriteByte(4);
            writer.WriteByte(2);
            writer.WriteByte(success ? (byte)1 : (byte)0);
            SendCompressedA(conn, 0x01, 0x0F, writer.ToArray());
            Debug.LogError($"[CHAR-CREATE] Sent response: success={success}");
        }
        private void HandleCharacterDelete(RRConnection conn, byte[] data)
        {
            Debug.LogError($"[CHAR-DELETE] ═══════════════════════════════════════");
            try
            {
                if (data == null || data.Length == 0)
                {
                    Debug.LogError($"[CHAR-DELETE] ❌ No data received!");
                    return;
                }

                var reader = new LEReader(data);
                string characterName = reader.ReadCString();
                uint characterId = reader.ReadUInt32();
                Debug.LogError($"[CHAR-DELETE] Name: '{characterName}', ID: {characterId}");

                // ═══════════════════════════════════════════════════════════════
                // STEP 1: Remove from persistent list (server-side memory)
                // ═══════════════════════════════════════════════════════════════
                if (_persistentCharacters.TryGetValue(conn.LoginName, out var characters))
                {
                    var toRemove = characters.Find(c => c.Id == characterId);
                    if (toRemove != null)
                    {
                        characters.Remove(toRemove);
                        Debug.LogError($"[CHAR-DELETE] ✅ Removed from persistent list");
                    }
                }

                bool deleted = CharacterRepository.DeleteCharacter(characterId);
                if (!deleted)
                {
                    Debug.LogError($"[CHAR-DELETE] Delete failed for ID={characterId}");
                    SendCharacterList(conn);
                    return;
                }
                Debug.LogError($"[CHAR-DELETE] Deleted from SQLite");

                // ═══════════════════════════════════════════════════════════════
                // STEP 3: Send ONLY the delete ack - nothing else!
                // Client handles UI update locally from its cached character data
                // ═══════════════════════════════════════════════════════════════
                var writer = new LEWriter();
                writer.WriteByte(4);   // Channel
                writer.WriteByte(4);   // Delete ack type
                writer.WriteUInt32(characterId);
                SendCompressedA(conn, 0x01, 0x0F, writer.ToArray());
                Debug.LogError($"[CHAR-DELETE] ✅ Sent delete ack for ID={characterId}");
                Debug.LogError($"[CHAR-DELETE] ✅ Done - NO character list resend (client handles locally)");
                // 🔥 FIX: Send fresh character list so client rebuilds UI with correct data
                SendCharacterList(conn);
                // Debug.LogError($"[CHAR-DELETE] ✅ Sent fresh character list after delete");
            }
            catch (Exception ex)
            {
                Debug.LogError($"[CHAR-DELETE] ❌ ERROR: {ex.Message}");
            }
        }


        // ═══════════════════════════════════════════════════════════════════════════════
        // ENTITY CHANNEL HANDLER — Refactored: single handler per opcode, no duplication
        // ═══════════════════════════════════════════════════════════════════════════════

        private void HandleClientEntityChannel(RRConnection conn, byte messageType, byte[] data)
        {
            var reader = new LEReader(data);

            if (messageType == 0x07)
            {
                // BeginStream - contains wrapped sub-messages terminated by 0x06
                ParseEntityStream(conn, reader);
                return;
            }

            // Top-level entity channel message — dispatch by opcode
            switch (messageType)
            {
                // --- Handled opcodes (known wire format) ---
                case 0x03: HandleOpcode_SendUpdate(conn, reader); break;
                case 0x04: HandleEntityRequest(conn, reader, data); break;
                case 0x08: HandleOpcode_CombatTick(conn, reader); break;
                case 0x09: HandleOpcode_Aggro(conn, reader); break;
                case 0x0C: HandleOpcode_RngSeed(conn, reader); break;
                case 0x34:
                case 0x35: HandleOpcode_ComponentUpdate(conn, reader, messageType); break;
                case 0x36: HandleOpcode_EntitySyncHP(conn, reader); break;
                case 0x64: HandleOpcode_StateMachine(conn, reader); break;
                case 0x66: HandleOpcode_ClientRngState(conn, reader); break;

                // --- Missing opcodes — log full payload for wire format analysis ---
                case 0x01: LogMissingOpcode(0x01, "BehaviorNotify", data, conn); break;
                // ...etc for all 11 cases (same pattern, just added conn)
                // ...etc for all 11 cases (same pattern, just added conn)
                case 0x0A: LogMissingOpcode(0x0A, "EntityChannel0A", data); break;
                case 0x0B: LogMissingOpcode(0x0B, "EntityChannel0B", data); break;
                case 0x23: LogMissingOpcode(0x23, "PathBehavior", data); break;
                case 0x25: LogMissingOpcode(0x25, "ActionCmd_25", data); break;
                case 0x26: LogMissingOpcode(0x26, "ActionCmd_26", data); break;
                case 0x27: LogMissingOpcode(0x27, "ActionCmd_27", data); break;
                case 0x28: LogMissingOpcode(0x28, "PathTarget_Simple", data); break;
                case 0x29: LogMissingOpcode(0x29, "PathTarget_Extended", data); break;
                case 0x32: HandleOpcode_ComponentUpdate(conn, reader, messageType); break;  // ComponentRequest (same format as 0x35)
                case 0x58: LogMissingOpcode(0x58, "EntityChannel58", data); break;

                default:
                    Debug.LogWarning($"[ENTITY-CH] Unknown type=0x{messageType:X2} len={data?.Length ?? 0}");
                    if (data != null && data.Length > 0)
                        LogMissingOpcode(messageType, $"Unknown_0x{messageType:X2}", data, conn);
                    break;
            }
        }

        /// <summary>
        /// Parses a BeginStream (0x07) sequence of sub-messages until EndStream (0x06).
        /// Only dispatches opcodes with known wire formats to avoid corrupting the stream.
        /// </summary>
        private void ParseEntityStream(RRConnection conn, LEReader reader)
        {
            int loopCount = 0;
            while (reader.Remaining > 0)
            {
                byte subType = reader.ReadByte();
                if (subType == 0x06) break; // EndStream
                loopCount++;

                switch (subType)
                {
                    case 0x03: HandleOpcode_SendUpdate(conn, reader); break;
                    case 0x04: HandleEntityRequest(conn, reader, null); break;
                    case 0x08: HandleOpcode_CombatTick(conn, reader); break;
                    case 0x09: HandleOpcode_Aggro(conn, reader); break;
                    case 0x0C: HandleOpcode_RngSeed(conn, reader); break;
                    case 0x32:
                    case 0x34:
                    case 0x35: HandleOpcode_ComponentUpdate(conn, reader, subType); break;
                    case 0x36: HandleOpcode_EntitySyncHP(conn, reader); break;
                    case 0x64: HandleOpcode_StateMachine(conn, reader); break;
                    case 0x66: HandleOpcode_ClientRngState(conn, reader); break;
                    default:
                        byte[] leftover = reader.Remaining > 0 ? reader.PeekRemaining() : new byte[0];
                        Debug.LogWarning($"[ENTITY-STREAM] Unknown sub=0x{subType:X2} remain={reader.Remaining}");
                        if (leftover.Length > 0 && leftover.Length < 128)
                        {
                            byte[] fakePacket = new byte[leftover.Length + 1];
                            fakePacket[0] = subType;
                            Array.Copy(leftover, 0, fakePacket, 1, leftover.Length);
                            LogMissingOpcode(subType, $"StreamSub_0x{subType:X2}", fakePacket, conn);
                        }
                        reader.Skip(reader.Remaining);
                        break;
                }
            }
        }

        // ═══════════════════════════════════════════════════════════════════════════════
        // ENTITY OPCODE HANDLERS — Called from both ParseEntityStream and top-level
        // ═══════════════════════════════════════════════════════════════════════════════

        private void HandleOpcode_RngSeed(RRConnection conn, LEReader reader)
        {
            if (reader.Remaining < 4) return;
            uint clientSeed = reader.ReadUInt32();
            uint roomSeed = CombatManager.Instance.IsRoomRngReady ? CombatManager.Instance.RoomSeed : 0u;
            Debug.LogError($"[RNG-SEED] Ignored client seed: 0x{clientSeed:X8} current=0x{roomSeed:X8} ready={CombatManager.Instance.IsRoomRngReady}");
        }

        /// <summary>
        /// Opcode 0x66 — DungeonRunners_RNG.exe sends its absolute Random::generate
        /// call counter for the room RNG (ClientEntityManager+0x44). Server uses this
        /// to fast-forward _roomRng to match client's position before each swing,
        /// achieving byte-identical damage rolls without mirroring every client
        /// RNG consumer (behavior states, fidgets, CC rolls, etc.).
        /// Wire format: [uint32 absoluteCallCount].
        /// </summary>
        private void HandleOpcode_ClientRngState(RRConnection conn, LEReader reader)
        {
            // P1 per-swing event format: [uint32 mobId][uint32 absoluteRngCount] — replayed per
            // player. Legacy single-count format: [uint32 absoluteRngCount] (test-bridge channel).
            if (CombatManager.UseClientEventReplay && reader.Remaining >= 8)
            {
                uint mobId = reader.ReadUInt32();
                uint clientCount = reader.ReadUInt32();
                uint playerId = conn?.Avatar?.Id ?? 0;
                if (playerId != 0)
                    CombatManager.Instance.ApplyClientSwingEvent(playerId, mobId, clientCount);
                if (VerbosePacketLogging)
                    Debug.LogError($"[CLIENT-RNG] event mob={mobId} count={clientCount} player={playerId} from {conn?.LoginName}");
                return;
            }
            if (reader.Remaining < 4) return;
            uint count = reader.ReadUInt32();
            CombatManager.Instance.ObserveClientRoomRngState(count);
            if (VerbosePacketLogging)
                Debug.LogError($"[CLIENT-RNG] received clientCount={count} from {conn?.LoginName}");
        }

        private void HandleOpcode_EntitySyncHP(RRConnection conn, LEReader reader)
        {
            if (reader.Remaining < 3) return;
            ushort syncEntityId = reader.ReadUInt16();
            byte syncFlags = reader.ReadByte();
            Debug.LogError($"[HP-SYNC] 0x36: entity={syncEntityId} flags=0x{syncFlags:X2} remaining={reader.Remaining}");
            if ((syncFlags & 0x02) != 0)
            {
                if (reader.Remaining >= 4)
                {
                    uint clientHP = reader.ReadUInt32();
                    Debug.LogError($"[HP-SYNC] entity={syncEntityId} HP={clientHP} ({clientHP / 256} actual)");
                    // Try by EntityId first, then by ANY component ID (BehaviorId, SkillsId, etc.)
                    var monster = CombatManager.Instance.GetMonster(syncEntityId)
                                ?? CombatManager.Instance.GetMonsterByComponent(syncEntityId);
                    if (monster != null)
                    {
                        int serverActual = (int)(CombatManager.Instance.PeekMonsterCurrentHPWire(monster) / 256);
                        int clientActual = (int)(clientHP / 256);
                        int delta = serverActual - clientActual;
                        Debug.LogError($"[HP-SYNC] Monster {monster.Name} (eid={monster.EntityId}) SERVER_HP={serverActual} CLIENT_HP={clientActual} DELTA={delta}");
                        CombatManager.Instance.ObserveClientMonsterHP(monster, clientHP, "HP-SYNC-0x36");
                    }
                    else if (IsAvatarOrAvatarComponentId(conn, syncEntityId))
                    {
                        PlayerState state = GetPlayerState(conn.ConnId.ToString());
                        if (state != null)
                        {
                            int clientActual = (int)(clientHP / 256);
                            int serverMax = (int)(state.MaxHPWire / 256);
                            int serverCurrent = (int)(state.CurrentHPWire / 256);

                            // Verify: client HP should never exceed server MaxHP (+ small tolerance)
                            int tolerance = 5; // allow small rounding difference
                            if (clientActual > serverMax + tolerance)
                            {
                                Debug.LogError($"[HP-VERIFY] ⚠️ Client HP {clientActual} EXCEEDS server MaxHP {serverMax}! Delta=+{clientActual - serverMax}. Possible cheat or missing equipment bonus.");
                            }
                            else if (clientActual < 0)
                            {
                                Debug.LogError($"[HP-VERIFY] ⚠️ Client HP negative: {clientActual}. Ignoring.");
                                return;
                            }

                            Debug.LogError($"[HP-SYNC] Player HP: {serverCurrent} -> {clientActual} (serverMax={serverMax})");
                            ObserveClientPlayerHP(conn, clientHP, "HP-SYNC-0x36");

                            // Extra bytes: unknown format, skip
                            if (reader.Remaining > 0)
                                reader.Skip(reader.Remaining);
                        }
                    }
                    else
                    {
                        Debug.LogError($"[HP-SYNC] Ignored HP for non-avatar entity={syncEntityId} hp={clientHP}");
                        if (reader.Remaining > 0)
                            reader.Skip(reader.Remaining);
                    }
                }
                else
                {
                    Debug.LogError($"[HP-SYNC] BUG: flags=0x02 but only {reader.Remaining} bytes left!");
                    if (reader.Remaining > 0)
                    {
                        byte[] leftover = reader.PeekRemaining();
                        Debug.LogError($"[HP-SYNC] leftover={BitConverter.ToString(leftover)}");
                    }
                }
            }
        }


        private bool IsAvatarEntityId(RRConnection conn, uint entityId)
        {
            return conn?.Avatar != null && entityId == (uint)conn.Avatar.Id;
        }

        private bool IsAvatarHPSyncComponentId(RRConnection conn, uint entityId)
        {
            if (IsAvatarEntityId(conn, entityId))
                return true;

            if (conn == null || entityId == 0)
                return false;

            return entityId == conn.UnitBehaviorId
                || entityId == conn.BehaviorComponentId
                || entityId == conn.SkillsComponentId
                || entityId == conn.ManipulatorsComponentId
                || entityId == conn.ModifiersId
                || entityId == conn.ModifiersComponentId
                || entityId == conn.UnitContainerId;
        }

        private bool IsAvatarOrAvatarComponentId(RRConnection conn, uint entityId)
        {
            return IsAvatarHPSyncComponentId(conn, entityId);
        }

        private bool IsNonUnitPlayerComponentId(RRConnection conn, uint entityId)
        {
            if (conn == null || entityId == 0)
                return false;

            return (conn.Player != null && entityId == (uint)conn.Player.Id)
                || entityId == conn.DialogManagerId
                || entityId == conn.QuestManagerId;
        }

        private bool IsPlayerOwnedComponentId(RRConnection conn, uint entityId)
        {
            return IsNonUnitPlayerComponentId(conn, entityId);
        }

        private void LogPlayerHPVisibleEvent(RRConnection conn, string reason)
        {
            if (conn == null) return;
            PlayerState state = GetPlayerState(conn.ConnId.ToString());
            Debug.LogError($"[PLAYER-HP-TRUTH] VISIBLE-EVENT player={conn.LoginName ?? conn.ConnId.ToString()} serverHP={(state != null ? state.CurrentHPWire / 256f : 0f):F2}/{(state != null ? state.MaxHPWire / 256f : 0f):F2} syncHP={(state != null ? state.SynchHP / 256f : 0f):F2} reason={reason ?? "native monster attack"}");
        }

        private void RecordPlayerHPKnown(RRConnection conn, string source, uint acceptedHPWire)
        {
            if (conn == null) return;
            PlayerState state = GetPlayerState(conn.ConnId.ToString());
            uint playerEntityId = conn.Avatar != null ? (uint)conn.Avatar.Id : 0;
            if (playerEntityId != 0 && state != null)
                HpSyncService.Instance.RecordPlayerOutboundHP(conn, state, playerEntityId, acceptedHPWire, source ?? "unknown");
            else
            {
                conn.LastOutboundHPWire = acceptedHPWire;
                conn.LastOutboundHPTime = Time.time;
                conn.LastOutboundHPSource = source ?? "unknown";
            }
            Debug.LogError($"[PLAYER-HP-TRUTH] KNOWN source={source} player={conn.LoginName ?? conn.ConnId.ToString()} hp={acceptedHPWire / 256f:F2}");
        }

        private void CommitPlayerHPTruth(RRConnection conn, PlayerState state, string source, uint hpWire, bool updateRuntimeHP, bool applyNativeDamageCooldown)
        {
            if (conn == null || state == null) return;
            uint beforeCurrent = state.CurrentHPWire;
            uint beforeSync = state.SynchHP;
            uint beforeMax = state.MaxHPWire;
            if (updateRuntimeHP)
                state.SetCurrentHP(hpWire, applyNativeDamageCooldown);
            uint playerEntityId = conn.Avatar != null ? (uint)conn.Avatar.Id : 0;
            if (playerEntityId != 0)
                HpSyncService.Instance.RegisterPlayer(conn, state, playerEntityId);
            RecordPlayerHPKnown(conn, source, state.SynchHP);
            Debug.LogError($"[PLAYER-HP-TRUTH] COMMIT source={source} player={conn.LoginName ?? conn.ConnId.ToString()} currentHP={beforeCurrent}->{state.CurrentHPWire}/{state.MaxHPWire} syncHP={beforeSync}->{state.SynchHP} maxHP={beforeMax}->{state.MaxHPWire} runtimeUpdate={updateRuntimeHP}");
        }

        private static bool IsWithinHPWireTolerance(uint a, uint b, uint tolerance)
        {
            return a >= b ? a - b <= tolerance : b - a <= tolerance;
        }

        private bool CanSendPlayerSynchronizedHP(RRConnection conn, string packetName)
        {
            if (conn == null) return false;
            RefreshZoneSpawnInvulnerability(conn);
            PlayerState state = GetPlayerState(conn.ConnId.ToString());
            if (state == null) return false;
            uint playerEntityId = conn.Avatar != null ? (uint)conn.Avatar.Id : 0;
            GetNativeValidationCutoff(out _, out float validationCutoffTime);
            bool canAdvanceClientSync = CanAdvancePlayerClientSyncHP(playerEntityId);
            if (playerEntityId != 0 && !IsZoneSpawnInvulnerabilityBlockingCombat(conn))
            {
                SyncContext context = SyncContextFromTag(packetName);
                if (CanApplyPlayerHPBeforeSuffix(context, packetName))
                {
                    CombatManager.Instance.UpdatePlayerPosition(playerEntityId, conn.PlayerPosX, conn.PlayerPosY);
                    FlushPendingKills();
                    FlushWeaponCycleBeforeSynch(conn, $"CanSendPlayerSynchronizedHP:{packetName}", true, validationCutoffTime);
                    CombatManager.Instance.FlushPlayerCombatBeforeSync(playerEntityId, 0f, $"CanSendPlayerSynchronizedHP:{packetName}", validationCutoffTime);
                    if (!CombatManager.Instance.FlushPlayerHPRuntimeBeforeSync(playerEntityId, packetName, out uint runtimeHPWire, out bool unsafeAttack, validationCutoffTime))
                    {
                        Debug.LogError($"[{packetName}] player HP runtime flush incomplete for {conn.LoginName ?? conn.ConnId.ToString()}: serverHP={state.CurrentHPWire / 256f:F2}/{state.MaxHPWire / 256f:F2} syncHP={state.SynchHP / 256f:F2} runtimeHP={runtimeHPWire / 256f:F2} unsafeAttack={unsafeAttack}");
                    }
                }
            }
            if (canAdvanceClientSync)
                state.AdvanceClientSyncHP(validationCutoffTime, packetName);
            return true;
        }

        private bool TryFindPlayerComponentUpdate(RRConnection conn, byte[] innerData, out ushort componentId, out byte subtype)
        {
            return TryFindPlayerComponentUpdate(conn, innerData, out componentId, out subtype, out _);
        }

        private bool TryFindPlayerComponentUpdate(RRConnection conn, byte[] innerData, out ushort componentId, out byte subtype, out int componentOffset)
        {
            componentId = 0;
            subtype = 0;
            componentOffset = -1;
            if (conn == null || innerData == null) return false;
            for (int i = 0; i + 2 < innerData.Length; i++)
            {
                if (innerData[i] != 0x35 && innerData[i] != 0x36) continue;
                if (innerData[i] == 0x35 && i + 3 >= innerData.Length) continue;
                if (innerData[i] == 0x36 && i + 2 >= innerData.Length) continue;
                ushort cid = (ushort)(innerData[i + 1] | (innerData[i + 2] << 8));
                if (!IsAvatarHPSyncComponentId(conn, cid) && !IsNonUnitPlayerComponentId(conn, cid)) continue;
                componentId = cid;
                subtype = innerData[i] == 0x35 ? innerData[i + 3] : (byte)0;
                componentOffset = i;
                return true;
            }
            return false;
        }

        private bool TryFindMonsterComponentUpdate(byte[] innerData, out Monster monster, out ushort componentId, out byte subtype)
        {
            return TryFindMonsterComponentUpdate(innerData, out monster, out componentId, out subtype, out _);
        }

        private bool TryFindMonsterComponentUpdate(byte[] innerData, out Monster monster, out ushort componentId, out byte subtype, out int componentOffset)
        {
            monster = null;
            componentId = 0;
            subtype = 0;
            componentOffset = -1;
            if (innerData == null || CombatManager.Instance == null) return false;
            for (int i = 0; i + 2 < innerData.Length; i++)
            {
                byte opcode = innerData[i];
                if (opcode != 0x35 && opcode != 0x36) continue;
                if (opcode == 0x35 && i + 3 >= innerData.Length) continue;
                ushort cid = (ushort)(innerData[i + 1] | (innerData[i + 2] << 8));
                Monster candidate = ResolveMonsterForComponent(cid, 0);
                if (candidate == null) continue;
                monster = candidate;
                componentId = cid;
                subtype = opcode == 0x35 ? innerData[i + 3] : (byte)0;
                componentOffset = i;
                return true;
            }
            return false;
        }

        private static bool TryGetNativeComponentPayloadEnd(byte[] innerData, int componentOffset, byte subtype, out int payloadEnd)
        {
            payloadEnd = -1;
            if (innerData == null || componentOffset < 0 || componentOffset + 4 > innerData.Length || innerData[componentOffset] != 0x35)
                return false;

            int payloadStart = componentOffset + 4;
            switch (subtype)
            {
                case 0x64:
                    payloadEnd = payloadStart + 1;
                    return payloadEnd <= innerData.Length;
                case 0x65:
                    if (payloadStart + 2 > innerData.Length) return false;
                    int moveCount = innerData[payloadStart + 1];
                    long end = (long)payloadStart + 2L + moveCount * 13L;
                    if (end > int.MaxValue) return false;
                    payloadEnd = (int)end;
                    return payloadEnd <= innerData.Length;
                default:
                    return false;
            }
        }

        private bool TryReadTrailingEntitySynchHP(byte[] innerData, int componentOffset, byte subtype, out uint hpWire)
        {
            hpWire = 0;
            if (innerData == null || innerData.Length < 6) return false;
            int terminator = FindCH07Terminator(innerData);
            if (terminator <= 0) return false;
            int flagsOffset = -1;
            if (TryGetNativeComponentPayloadEnd(innerData, componentOffset, subtype, out int payloadEnd) && payloadEnd <= terminator)
                flagsOffset = payloadEnd;
            else if (terminator >= 5)
                flagsOffset = terminator - 5;
            if (flagsOffset < 0 || flagsOffset >= terminator) return false;
            if ((innerData[flagsOffset] & 0x02) == 0) return false;
            if (flagsOffset + 5 > terminator) return false;
            hpWire = (uint)(innerData[flagsOffset + 1]
                | (innerData[flagsOffset + 2] << 8)
                | (innerData[flagsOffset + 3] << 16)
                | (innerData[flagsOffset + 4] << 24));
            return true;
        }

        private bool TryReadTrailingEntitySynchHP(byte[] innerData, out uint hpWire)
        {
            hpWire = 0;
            if (innerData == null || innerData.Length < 6) return false;
            int terminator = FindCH07Terminator(innerData);
            if (terminator < 5) return false;
            int flagsOffset = terminator - 5;
            if ((innerData[flagsOffset] & 0x02) == 0) return false;
            hpWire = (uint)(innerData[flagsOffset + 1]
                | (innerData[flagsOffset + 2] << 8)
                | (innerData[flagsOffset + 3] << 16)
                | (innerData[flagsOffset + 4] << 24));
            return true;
        }

        private bool TryNormalizeCH07RuntimeStream(RRConnection conn, byte[] innerData, SyncContext context, string packetName, out byte[] normalizedData, out bool drop)
        {
            normalizedData = innerData;
            drop = false;
            return false;
        }

        private static int FindCH07Terminator(byte[] innerData)
        {
            if (innerData == null || innerData.Length == 0) return -1;
            int i = innerData.Length - 1;
            while (i > 0 && innerData[i] == 0x00)
                i--;
            return innerData[i] == 0x06 ? i : -1;
        }

        private bool ObserveClientPlayerHP(RRConnection conn, uint clientHP, string source)
        {
            // T1 diagnostic — fires on EVERY entry to ObserveClientPlayerHP, regardless of any
            // gating below. This measures the actual rate at which the client is autonomously
            // reporting its HP to the server, which is the load-bearing assumption for Path X.
            // If we see <2 reports per 30s of combat, Path X is infeasible as designed.
            Debug.LogError(
                $"[CLIENT-REPORT-FREQ] source={source} reportedHP={clientHP} " +
                $"conn={conn?.LoginName ?? conn?.ConnId.ToString() ?? "?"} t={Time.time:F2}");

            if (conn == null) return false;
            PlayerState state = GetPlayerState(conn.ConnId.ToString());
            if (state == null) return false;
            uint playerEntityId = conn.Avatar != null ? (uint)conn.Avatar.Id : 0;
            if (playerEntityId != 0)
                HpSyncService.Instance.RegisterPlayer(conn, state, playerEntityId);

            uint tolerance = 5u * 256u;
            if (clientHP > state.MaxHPWire + tolerance)
            {
                Debug.LogError($"[{source}] Client HP {clientHP / 256} exceeds server MaxHP {state.MaxHPWire / 256}; ignored");
                return false;
            }

            uint oldHP = state.SynchHP;
            HpReportDecision hpDecision = HpReportDecision.AcceptObserved("legacy");
            bool hpServiceAccepted = false;
            if (playerEntityId != 0 && HpSyncService.Instance.TryResolvePlayerOwner(conn, state, playerEntityId, out HpOwnerRef owner))
            {
                hpServiceAccepted = HpSyncService.Instance.ObserveClientHpReport(owner, clientHP, HpSyncService.ClassifyReportSource(source), source ?? "client-player-hp", true, out hpDecision);
                if (!hpServiceAccepted)
                {
                    Debug.LogError($"[{source}] Client player HP rejected by HpSyncService: hp={clientHP / 256f:F2}/{state.MaxHPWire / 256f:F2} reason={hpDecision.Reason}");
                    return false;
                }
            }
            uint acceptedClientHP = Math.Min(clientHP, state.MaxHPWire);
            state.SetCurrentHP(acceptedClientHP);
            state.ObserveClientHP(acceptedClientHP, source);
            conn.LastObservedClientHPWire = state.LastObservedClientHPWire;
            conn.LastObservedClientHPTime = state.LastObservedClientHPTime;
            conn.LastObservedClientHPSource = state.LastObservedClientHPSource;
            if (playerEntityId != 0)
                HpSyncService.Instance.RegisterPlayer(conn, state, playerEntityId);
            if (!hpServiceAccepted)
                RecordPlayerHPKnown(conn, source, state.SynchHP);
            if (acceptedClientHP < oldHP)
                Debug.LogError($"[{source}] CLIENT PLAYER HP lower observed: {(oldHP - acceptedClientHP) / 256f:F2} HP ({oldHP}->{acceptedClientHP}) serverHP={state.CurrentHPWire}");
            else if (acceptedClientHP > oldHP)
                Debug.LogError($"[{source}] CLIENT PLAYER HP higher observed: {(acceptedClientHP - oldHP) / 256f:F2} HP ({oldHP}->{acceptedClientHP}) serverHP={state.CurrentHPWire}");
            else
                Debug.LogError($"[{source}] Player HP unchanged: {acceptedClientHP / 256f:F2} wire={acceptedClientHP}");

            LogSimulatorDelta(conn, state, acceptedClientHP, source);
            return true;
        }

        // Stage 2 diagnostic — fired whenever the client reports its HP to the server.
        // Compares the just-observed client HP against the server-side simulator's HP value
        // (state.SimulatedHPWire == _currentHPWire, populated by CombatManager.ResolveMonsterAttackDamage
        // when a server-simulated monster swing lands). Captures enough context (last sim attack
        // mob+result+damage+RNG-pos, max HP, time since last attack) to attribute the delta to
        // a specific simulator bug class:
        //
        //   delta ≈ 0                                     → simulator agrees with client (good)
        //   delta > 0, no recent sim attack               → server missed a swing the client landed
        //   delta > 0, recent sim attack with HIT result  → server damage value diverges
        //   delta > 0, recent sim attack with MISS/BLOCK  → server's hit roll diverges
        //   delta < 0                                     → server applied damage client didn't (timing/cadence ahead)
        //
        // Read alongside the [PLAYER-DAMAGE] / [COMBAT-EVENT] log lines from CombatManager
        // and an x32dbg breakpoint capture of client's Weapon::applyDamage @ 0x00597e50 to
        // pinpoint which roll diverged.
        private void LogSimulatorDelta(RRConnection conn, PlayerState state, uint clientHPWire, string source)
        {
            if (state == null || conn == null) return;
            uint simHP = state.SimulatedHPWire;
            long delta = (long)simHP - (long)clientHPWire;
            string verdict;
            if (Math.Abs(delta) <= 256) verdict = "AGREE";        // within 1 wire-HP — fine
            else if (delta > 0)         verdict = "SERVER-HIGH";  // server thinks player has MORE HP — missed a swing
            else                        verdict = "SERVER-LOW";   // server thinks player has LESS HP — phantom damage
            float nativeNow = GetNativeCombatNow();
            float timeSinceAttack = state.LastSimMonsterAttackNativeTime >= 0f
                ? nativeNow - state.LastSimMonsterAttackNativeTime
                : -1f;
            Debug.LogError(
                $"[SIM-DELTA] {verdict} player={conn.LoginName ?? conn.ConnId.ToString()} " +
                $"reported={clientHPWire} simulated={simHP} delta={delta} (wire) | " +
                $"max={state.MaxHPWire} sync={state.SynchHP} | " +
                $"lastSimAttack mob={state.LastSimMonsterAttackMonsterId} " +
                $"result={state.LastSimMonsterAttackResult ?? "none"} " +
                $"dmg={state.LastSimMonsterAttackDamageWire} " +
                $"rngPos={state.LastSimMonsterAttackRoomRngPos} " +
                $"sinceAttack={timeSinceAttack:F3}s | " +
                $"source={source} roomSeed=0x{CombatManager.Instance.RoomSeed:X8} " +
                $"roomRngPos={CombatManager.Instance.RoomRngCallsSinceReseed}");
        }

        private bool TryConsumeClientSyncSuffix(RRConnection conn, LEReader reader, string source)
        {
            return TryConsumeClientSyncSuffix(conn, reader, source, null);
        }

        private bool TryConsumeClientSyncSuffix(RRConnection conn, LEReader reader, string source, Monster targetMonster)
        {
            return TryConsumeClientSyncSuffix(conn, reader, source, targetMonster, out _);
        }

        private bool TryConsumeClientSyncSuffix(RRConnection conn, LEReader reader, string source, Monster targetMonster, out bool acceptedMonsterHP)
        {
            acceptedMonsterHP = false;
            if (reader == null || reader.Remaining < 1) return false;

            byte syncFlags = reader.ReadByte();
            if ((syncFlags & 0x02) == 0)
            {
                Debug.LogError($"[{source}] syncFlags=0x{syncFlags:X2} (no HP)");
                return false;
            }

            if (reader.Remaining < 4)
            {
                Debug.LogError($"[{source}] syncFlags=0x{syncFlags:X2} but HP missing remaining={reader.Remaining}");
                return false;
            }

            uint syncHP = reader.ReadUInt32();
            Debug.LogError($"[{source}] syncFlags=0x{syncFlags:X2} HP={syncHP} ({syncHP / 256} actual)");
            if (ObserveClientMonsterHPFromActionSuffix(conn, targetMonster, syncHP, source))
            {
                acceptedMonsterHP = true;
                return true;
            }
            if (targetMonster != null && CombatManager.Instance != null && FitsMonsterHP(targetMonster, syncHP))
            {
                CombatManager.Instance.RecordMonsterHPObservation(targetMonster, syncHP, source);
                acceptedMonsterHP = true;
                return true;
            }
            return ObserveClientPlayerHP(conn, syncHP, source);
        }

        private bool ObserveClientMonsterHPFromActionSuffix(RRConnection conn, Monster targetMonster, uint syncHP, string source)
        {
            if (targetMonster == null || CombatManager.Instance == null) return false;
            if (string.IsNullOrEmpty(source) || !source.StartsWith("ACTION-0x50-SYNC", StringComparison.Ordinal)) return false;
            if (!FitsMonsterHP(targetMonster, syncHP)) return false;
            CombatManager.Instance.RecordMonsterHPObservation(targetMonster, syncHP, source);
            return true;
        }

        private static bool FitsMonsterHP(Monster monster, uint hpWire)
        {
            if (monster == null) return false;
            uint toleranceWire = 5u * 256u;
            return hpWire <= monster.MaxHPWire || hpWire - monster.MaxHPWire <= toleranceWire;
        }

        private void HandleOpcode_CombatTick(RRConnection conn, LEReader reader)
        {
            Debug.LogError($"[COMBAT-TICK] 0x08 remain={reader.Remaining}");
            if (reader.Remaining < 7) return;

            byte combatSub = reader.ReadByte();
            ushort combatSize = reader.ReadUInt16();
            int combatDamage = reader.ReadInt32();
            Debug.LogError($"[COMBAT-TICK] sub={combatSub} size={combatSize} damage={combatDamage}");

            if (combatDamage > 0)
            {
                foreach (var m in CombatManager.Instance.GetActiveMonsters())
                {
                    if (m.State == MonsterState.Combat && m.IsAlive)
                    {
                        Debug.LogError($"[COMBAT-TICK] CLIENT_DMG={combatDamage} on {m.Name} (target ambiguous; waiting for HP sync) SERVER_HP={CombatManager.Instance.PeekMonsterCurrentHPWire(m) / 256}");
                        break;
                    }
                }
            }

            if (reader.Remaining >= 4) reader.ReadUInt32();
        }

        private void HandleOpcode_Aggro(RRConnection conn, LEReader reader)
        {
            if (reader.Remaining < 3) return;
            ushort aggroEntityId = reader.ReadUInt16();
            byte aggroLevel = reader.ReadByte();
            Debug.LogError($"[AGGRO] 0x09: entityId={aggroEntityId} level={aggroLevel}");
            var monster = CombatManager.Instance.GetMonster(aggroEntityId)
                       ?? CombatManager.Instance.GetMonsterByComponent(aggroEntityId);
            if (monster != null && conn?.Avatar != null)
            {
                uint playerEntityId = (uint)conn.Avatar.Id;
                CombatManager.Instance.EngageMonsterFromClientAction(monster, playerEntityId);
            }
        }

        private void HandleOpcode_SendUpdate(RRConnection conn, LEReader reader)
        {
            if (reader.Remaining < 3) return;
            ushort entityId = reader.ReadUInt16();
            byte updateType = reader.ReadByte();
            Debug.LogError($"[SEND-UPDATE] 0x03: entity={entityId} updateType=0x{updateType:X2}");

            if (reader.Remaining < 1) return;
            byte flags = reader.ReadByte();

            if ((flags & 0x02) != 0 && reader.Remaining >= 4)
            {
                uint hp = reader.ReadUInt32();
                Debug.LogError($"[SEND-UPDATE] HP: entity={entityId} HP={hp} ({hp / 256} actual)");

                var monster = CombatManager.Instance.GetMonster(entityId)
                             ?? CombatManager.Instance.GetMonsterByComponent(entityId);
                if (monster != null)
                {
                    int serverActual = (int)(CombatManager.Instance.PeekMonsterCurrentHPWire(monster) / 256);
                    int clientActual = (int)(hp / 256);
                    Debug.LogError($"[SEND-UPDATE] Monster {monster.Name} SERVER_HP={serverActual} CLIENT_HP={clientActual} DELTA={serverActual - clientActual}");
                    CombatManager.Instance.ObserveClientMonsterHP(monster, hp, "SEND-UPDATE-0x03");
                }
                else if (IsAvatarOrAvatarComponentId(conn, entityId))
                {
                    PlayerState state = GetPlayerState(conn.ConnId.ToString());
                    if (state != null)
                    {
                        ObserveClientPlayerHP(conn, hp, "SEND-UPDATE");
                    }
                }
                else
                {
                    Debug.LogError($"[SEND-UPDATE] Ignored HP for non-avatar entity={entityId} HP={hp}");
                }
            }
        }

        private void HandleOpcode_StateMachine(RRConnection conn, LEReader reader)
        {
            if (reader.Remaining < 1) return;
            byte stateFlags = reader.ReadByte();

            ushort stateType = 0xFFFF;
            ushort scope = 0xFFFF;
            ushort target = 0;
            uint stateValue = 0;

            // Binary-verified flag format from StateMachine::ReadMessage @ 0x5F0C70
            if ((stateFlags & 0x02) != 0 && reader.Remaining >= 2)
                stateType = reader.ReadUInt16();
            if ((stateFlags & 0x04) != 0 && reader.Remaining >= 2)
                scope = reader.ReadUInt16();
            if ((stateFlags & 0x08) != 0 && reader.Remaining >= 2)
                target = reader.ReadUInt16();
            if ((stateFlags & 0x20) != 0 && reader.Remaining >= 4)
                stateValue = reader.ReadUInt32();
            if ((stateFlags & 0x10) != 0 && reader.Remaining >= 2)
            {
                ushort wCount = reader.ReadUInt16();
                for (int w = 0; w < wCount && reader.Remaining >= 2; w++)
                    reader.ReadUInt16();
            }

            Debug.LogError($"[STATE-MACHINE] 0x64: flags=0x{stateFlags:X2} type={stateType} scope={scope} target={target} value={stateValue}");
        }

        private void HandleOpcode_ComponentUpdate(RRConnection conn, LEReader reader, byte opcode)
        {
            if (reader.Remaining >= 2)
            {
                byte[] peek = reader.PeekRemaining();
                ushort cid = (ushort)(peek[0] | (peek[1] << 8));
                if (cid >= 50000 && cid < 60000)
                {
                    int posBefore = reader.Position;
                    HandleComponentUpdate(conn, reader);
                    int posAfter = reader.Position;
                    int consumed = posAfter - posBefore;
                    if (consumed > 0 && VerbosePacketLogging)
                        Debug.LogError($"[RELAY] Skipped client-origin monster component echo cid={cid} opcode=0x{opcode:X2} len={consumed}");
                    return;
                }
            }
            HandleComponentUpdate(conn, reader);
        }

        // ═══════════════════════════════════════════════════════════════════════════════
        // MISSING OPCODE LOGGER — Captures full payload for wire format analysis
        // These opcodes are sent by the client but had no server handler.
        // Once wire formats are decoded from captured payloads, replace with real handlers.
        // ═══════════════════════════════════════════════════════════════════════════════

        private void LogMissingOpcode(byte opcode, string name, byte[] data, RRConnection conn = null)
        {
            if (!VerbosePacketLogging) return;
            int len = data?.Length ?? 0;
            string hex = len > 0 ? BitConverter.ToString(data, 0, Math.Min(len, 256)) : "(empty)";
            Debug.LogError($"[DIAG-0x{opcode:X2}] ══════════════════════════════════════════════════════");
            string playerPos = conn != null ? $"player=({conn.PlayerPosX:F1},{conn.PlayerPosY:F1})" : "player=?";
            Debug.LogError($"[DIAG-0x{opcode:X2}] {name} len={len} {playerPos} raw={hex}");

            if (data == null || len < 2) return;

            // Try every uint16 as potential entity/component ID
            var sb = new System.Text.StringBuilder();
            sb.Append($"[DIAG-0x{opcode:X2}] uint16 scan: ");
            for (int i = 0; i <= len - 2; i += 2)
            {
                ushort val = (ushort)(data[i] | (data[i + 1] << 8));
                string tag = "";
                if (val >= 50000 && val < 60000)
                {
                    var mon = CombatManager.Instance.GetMonsterByComponent(val);
                    tag = mon != null ? $"=MON:{mon.Name}" : "=MON_RANGE";
                }
                sb.Append($"[{i}]=0x{val:X4}({val}){tag} ");
            }
            Debug.LogError(sb.ToString());

            // Try every uint32 as potential fixed-point coordinate (÷256)
            if (len >= 4)
            {
                var sb2 = new System.Text.StringBuilder();
                sb2.Append($"[DIAG-0x{opcode:X2}] int32/coord scan: ");
                for (int i = 0; i <= len - 4; i += 4)
                {
                    int val = data[i] | (data[i + 1] << 8) | (data[i + 2] << 16) | (data[i + 3] << 24);
                    float coord = val / 256f;
                    string tag = (coord > -500 && coord < 1000 && coord != 0) ? " <COORD?>" : "";
                    sb2.Append($"[{i}]={val}({coord:F1}){tag} ");
                }
                Debug.LogError(sb2.ToString());
            }

            // Try as: entityId(2) + subType(1) + payload
            if (len >= 3)
            {
                ushort eid = (ushort)(data[0] | (data[1] << 8));
                byte sub = data[2];
                var mon = CombatManager.Instance.GetMonsterByComponent(eid);
                string monTag = mon != null ? $" MONSTER={mon.Name}(pos={mon.PosX:F1},{mon.PosY:F1})" : "";
                Debug.LogError($"[DIAG-0x{opcode:X2}] as [eid={eid}(0x{eid:X4}) sub=0x{sub:X2}]{monTag} remain={len - 3}b");
            }

            // Try as: componentId(2) + data
            if (len >= 5)
            {
                ushort cid = (ushort)(data[0] | (data[1] << 8));
                var mon = CombatManager.Instance.GetMonsterByComponent(cid);
                if (mon != null)
                {
                    Debug.LogError($"[DIAG-0x{opcode:X2}] *** MONSTER CID HIT *** cid={cid} -> {mon.Name} EntityId={mon.EntityId} BehaviorId={mon.BehaviorId}");
                }
            }

            Debug.LogError($"[DIAG-0x{opcode:X2}] ══════════════════════════════════════════════════════");
        }




        // ═══════════════════════════════════════════════════════════════════════════════
        // CENTRALIZED KILL HANDLER — ALL monster death events route through here.
        // This prevents double-XP, double-quest-credit, and level desync bugs.
        // 
        // Session 24+: TryFinalizeMonsterKill is the single entry point.
        // HashSet _finalizedMonsterKills prevents any double processing.
        // Multiple paths may detect HP=0 (0x36, 0x03, 0x65, server damage) — first wins.
        // ═══════════════════════════════════════════════════════════════════════════════
        private static int _serverKillCount = 0;
        private HashSet<uint> _finalizedMonsterKills = new HashSet<uint>();
        private uint _lastClientXP = 0; // XP reported by DLL from client — used as truth when available
        private volatile int _dllPreConfirmCount = 0;    // DEPRECATED — kept for compat, always 0
        private HashSet<uint> _dllPreConfirmedEntities = new HashSet<uint>(); // entity IDs the DLL pre-confirmed

        /// <summary>
        /// Public reset for callers that just sent admin XP packets and want to prevent
        /// the client DLL's echo from contaminating the next mob kill's XP award.
        /// Called from ChatCommandHandler @level after the SendAdminXPUpdate loop, and
        /// from ProcessPendingAdminActions after the web admin level action.
        /// </summary>
        public void ResetLastClientXP()
        {
            _lastClientXP = 0;
        }

        // DLL entity position tracking
        private HashSet<uint> _positionReportedMonsters = new HashSet<uint>();
        private int _e1PacketCount = 0;
        private System.Collections.Concurrent.ConcurrentQueue<PendingSpell> _pendingSpells = new System.Collections.Concurrent.ConcurrentQueue<PendingSpell>();
        private long _nextPendingSpellProjectileSequence;

        private struct PendingSpell
        {
            public long Sequence;
            public RRConnection Conn;
            public PlayerState State;
            public Combat.Monster Monster;
            public Combat.SpellData Spell;
            public byte ManipId;
            public byte UseFlags;
            public ushort ComponentId;
            public float StartX;
            public float StartY;
            public float AimX;
            public float AimY;
            public float DueTime;
            public float ProjectileHitDistance;
            public float ProjectileDelay;
            public bool QueuedWithoutInitialTarget;
            public bool ProjectileRuntimeInitialized;
            public float FireTime;
            public int FireNativeTick;
            public int LastUpdateNativeTick;
            public int UpdatesCompleted;
            public int MaxLifetimeTicks;
            public float ProjectileSpeed;
            public float ProjectileSize;
            public float StepDistance;
            public float InitialDistance;
            public float CurrentDistance;
            public float MaxDistance;
        }

        private struct SpellPreSuffixFlushResult
        {
            public uint TargetEntityId;
            public int PendingBefore;
            public int PendingAfter;
            public int DueForTarget;
            public int DueOther;
            public int Applied;
            public int SkippedDead;
            public int RequeuedFuture;
            public int RequeuedOther;
            public uint BeforeHPWire;
            public uint AfterHPWire;
        }

        private RRConnection FindConnectionByAvatarEntityId(uint entityId)
        {
            if (entityId == 0) return null;
            foreach (var conn in _connections.Values)
            {
                if (conn?.Avatar == null) continue;
                if ((uint)conn.Avatar.Id == entityId)
                    return conn;
            }
            return null;
        }

        private void DrainPendingModifierKills()
        {
            while (CombatManager.Instance.HasPendingModifierKills)
            {
                var kill = CombatManager.Instance.DequeuePendingModifierKill();
                if (kill == null)
                    break;

                var monster = CombatManager.Instance.GetMonster(kill.TargetEntityId);
                var conn = FindConnectionByAvatarEntityId(kill.SourceEntityId);
                Debug.LogError($"[POISON-SHOT-MOD-KILL] drain target={kill.TargetEntityId} sourceEntity={kill.SourceEntityId} nativeDamageTime={kill.NativeDamageTime:F3} conn={(conn != null ? conn.ConnId.ToString() : "null")} source={kill.Source ?? "modifier-tick"}");
                if (monster == null)
                {
                    Debug.LogError($"[POISON-SHOT-MOD-KILL] missing monster target={kill.TargetEntityId}");
                    continue;
                }

                CombatManager.Instance.CancelMonsterPendingAttack(monster, "SPELL-MOD-tick-kill");
                try
                {
                    bool finalized = TryFinalizeMonsterKill(conn, monster, "SPELL-MOD-tick");
                    Debug.LogError($"[POISON-SHOT-MOD-KILL] finalize result={finalized} monster={monster.Name} eid={monster.EntityId}");
                }
                catch (Exception ex)
                {
                    Debug.LogError($"[KILL-ERROR] SPELL-MOD-tick finalize failed for {monster.Name}: {ex.Message}\n{ex.StackTrace}");
                    if (IsUseTargetingMonster(conn, monster))
                        ClearUseTargetAndReleaseControl(conn, "SPELL-MOD-tick-error");
                }

                if (conn != null && IsUseTargetingMonster(conn, monster))
                    ClearUseTargetAndReleaseControl(conn, "SPELL-MOD-tick-kill", sendClientControlReset: true, requireActiveUseTargetForReset: true);
            }
        }

        private void DrainWeaponCycleKills(string source)
        {
            while (Combat.WeaponCycleTracker.Instance.HasPendingKills)
            {
                var kill = Combat.WeaponCycleTracker.Instance.DequeueKill();
                if (kill == null || !kill.Killed)
                    continue;

                Debug.LogError($"[WEAPON-CYCLE] ★ KILL: {kill.Monster?.Name ?? "monster"} killed by {kill.ConnKey} ({kill.DamageDealt} final dmg) source={source ?? "unknown"}");
                if (kill.Monster != null)
                    CombatManager.Instance.CancelMonsterPendingAttack(kill.Monster, "WeaponCycle-kill");
                try
                {
                    bool finalized = TryFinalizeMonsterKill(kill.Connection, kill.Monster, source ?? "WeaponCycle-tick");
                    Debug.LogError($"[WEAPON-CYCLE] finalize result={finalized} monster={kill.Monster?.Name} eid={kill.Monster?.EntityId} source={source ?? "unknown"}");
                }
                catch (Exception ex)
                {
                    Debug.LogError($"[KILL-ERROR] WeaponCycle finalize failed for {kill.Monster?.Name}: {ex.Message}\n{ex.StackTrace}");
                    if (IsUseTargetingMonster(kill.Connection, kill.Monster))
                        ClearUseTargetAndReleaseControl(kill.Connection, "WeaponCycle-error");
                }
                if (kill.Connection != null)
                    ClearUseTargetAndReleaseControl(kill.Connection, "WeaponCycle-kill", sendClientControlReset: true, requireActiveUseTargetForReset: true);
            }
        }

        // Tick-rate diagnostic — measures how often the combat tick actually fires per wall-clock second.
        // If much higher than 30Hz, the projectile flight / chase speed / RNG consumption rate divergences
        // are all explained by Unity's Update() running at frame rate rather than fixed 30Hz.
        // The fix is wall-clock-based scheduling (DueTime = FireTime + seconds) rather than tick-discrete.
        private int _combatTickCounter = 0;
        private float _combatTickRateLogTime = -1f;
        private float _combatTickRateMinDt = float.MaxValue;
        private float _combatTickRateMaxDt = 0f;
        private float _combatTickRateLastTick = -1f;

        private void TickCombatDeterministicSystems(float tickNow, bool allowNewMonsterAttacks)
        {
            // Per-tick measurement
            float wallNow = Time.time;
            _combatTickCounter++;
            if (_combatTickRateLastTick >= 0f)
            {
                float dt = wallNow - _combatTickRateLastTick;
                if (dt < _combatTickRateMinDt) _combatTickRateMinDt = dt;
                if (dt > _combatTickRateMaxDt) _combatTickRateMaxDt = dt;
            }
            _combatTickRateLastTick = wallNow;

            // Per-second summary
            if (_combatTickRateLogTime < 0f) _combatTickRateLogTime = wallNow;
            float elapsed = wallNow - _combatTickRateLogTime;
            if (elapsed >= 1.0f)
            {
                float ticksPerSec = _combatTickCounter / elapsed;
                float avgDt = elapsed / _combatTickCounter;
                Debug.LogError(
                    $"[TICK-RATE] combat-ticks={_combatTickCounter} elapsed={elapsed:F3}s " +
                    $"rate={ticksPerSec:F1}Hz avg-dt={avgDt * 1000f:F1}ms " +
                    $"dt-min={_combatTickRateMinDt * 1000f:F1}ms " +
                    $"dt-max={_combatTickRateMaxDt * 1000f:F1}ms " +
                    $"COMBAT_TICK-const={COMBAT_TICK * 1000f:F1}ms ratio-to-30Hz={ticksPerSec / 30f:F2}x " +
                    $"tickNow={tickNow:F3}");
                _combatTickCounter = 0;
                _combatTickRateLogTime = wallNow;
                _combatTickRateMinDt = float.MaxValue;
                _combatTickRateMaxDt = 0f;
            }

            var rng = CombatManager.Instance.RoomRng;
            if (rng == null)
            {
                CombatManager.Instance.UpdateNativeMaintenance(COMBAT_TICK);
            }
            else
            {
                ProcessPendingSpellsForPlayerEntity(0, tickNow);
                Combat.WeaponCycleTracker.Instance.TickProjectileEntityPhase(rng, tickNow, "ClientEntityManager.updateEntities-subentities");
                CombatManager.Instance.MarkNativeSubEntityUpdateCompleted(CombatManager.Instance.NativeCombatTick, tickNow, "UnityGameServer.Update-subentities");

                foreach (uint entityId in CombatManager.Instance.GetNativeEntityOrderSnapshot())
                {
                    if (CombatManager.Instance.IsNativeMonsterEntity(entityId))
                    {
                        Combat.WanderSimulator.Instance.TickEntity(entityId, rng);
                        CombatManager.Instance.UpdateNativeMonsterEntity(entityId, COMBAT_TICK, allowNewMonsterAttacks, tickNow);
                    }
                    else if (CombatManager.Instance.IsNativePlayerEntity(entityId))
                    {
                        Combat.WeaponCycleTracker.Instance.TickPlayerEntity(entityId, rng, tickNow);
                    }
                }

                CombatManager.Instance.UpdateNativeMaintenance(COMBAT_TICK);
            }

            DrainPendingModifierKills();
            DrainWeaponCycleKills("WeaponCycle-tick");
        }

        private void ProcessPendingSpellsForPlayerEntity(uint playerEntityId, float now)
        {
            int pendingCount = _pendingSpells.Count;
            for (int i = 0; i < pendingCount; i++)
            {
                if (!_pendingSpells.TryDequeue(out var pending))
                    break;

                uint pendingPlayerId = pending.Conn?.Avatar != null ? (uint)pending.Conn.Avatar.Id : 0;
                if (playerEntityId != 0 && pendingPlayerId != playerEntityId)
                {
                    _pendingSpells.Enqueue(pending);
                    continue;
                }

                if (pending.ProjectileRuntimeInitialized)
                {
                    if (!UpdatePendingSpellProjectile(ref pending, now, "ProcessPendingSpells"))
                        _pendingSpells.Enqueue(pending);
                    continue;
                }

                if (!IsPendingSpellDue(pending, now))
                {
                    _pendingSpells.Enqueue(pending);
                    continue;
                }

                Combat.Monster target = ResolvePendingSpellTarget(ref pending, now, "ProcessPendingSpells");
                if (target != null && target.IsAlive)
                    HandleSpellAttack(pending.Conn, pending.State, target, pending.ManipId, pending.UseFlags, pending.AimX, pending.AimY, ResolvePendingSpellImpactTime(pending, now));
                else if (pending.QueuedWithoutInitialTarget)
                    Debug.LogError($"[SPELL-PROJECTILE] no-hit spell={pending.Spell?.DisplayName ?? pending.Spell?.SkillId ?? "UNKNOWN"} manip={pending.ManipId} aim=({pending.AimX:F1},{pending.AimY:F1}) due={pending.DueTime:F3} now={now:F3} source=ProcessPendingSpells");
            }
        }

        private PendingSpell CreatePendingSpellProjectile(
            RRConnection conn,
            PlayerState state,
            Combat.Monster monster,
            Combat.SpellData spell,
            byte manipId,
            byte useFlags,
            ushort componentId,
            float startX,
            float startY,
            float aimX,
            float aimY,
            bool queuedWithoutInitialTarget,
            float hitDistanceHint)
        {
            float dx = aimX - startX;
            float dy = aimY - startY;
            float aimDistance = Mathf.Sqrt((dx * dx) + (dy * dy));
            if (aimDistance <= 0.001f)
                aimDistance = Mathf.Max(0.001f, hitDistanceHint);

            float speed = spell != null ? Mathf.Max(1f, spell.ProjectileSpeed) : 0f;
            float size = spell != null ? Mathf.Max(0f, spell.ProjectileSize) : 0f;
            float maxDistance = spell != null && size > 0f && speed > 0f
                ? ResolveProjectileMaxDistance(spell, aimDistance)
                : Mathf.Max(0f, hitDistanceHint);
            if (maxDistance <= 0.001f)
                maxDistance = Mathf.Max(0.001f, aimDistance);

            float fireTime = GetNativeCombatNow();
            int fireTick = Combat.WeaponCycleTracker.NativeTickIndexFromTime(fireTime);
            int maxLifetimeTicks = spell != null && size > 0f && speed > 0f
                ? Math.Max(1, Combat.WeaponCycleTracker.NativeProjectileFlightTicks(maxDistance, speed))
                : 1;
            float stepDistance = spell != null && size > 0f && speed > 0f
                ? Combat.WeaponCycleTracker.NativeProjectileStepDistance(speed)
                : 0f;
            float initialDistance = spell != null && size > 0f && speed > 0f
                ? Combat.WeaponCycleTracker.NativeProjectileInitialDistance(speed, maxDistance)
                : 0f;
            float diagnosticDistance = hitDistanceHint > 0f
                ? Mathf.Min(hitDistanceHint, maxDistance)
                : maxDistance;
            float projectileDelay = ResolveProjectileImpactDelay(spell, diagnosticDistance);

            return new PendingSpell
            {
                Sequence = ++_nextPendingSpellProjectileSequence,
                Conn = conn,
                State = state,
                Monster = monster,
                Spell = spell,
                ManipId = manipId,
                UseFlags = useFlags,
                ComponentId = componentId,
                StartX = startX,
                StartY = startY,
                AimX = aimX,
                AimY = aimY,
                DueTime = fireTime + projectileDelay,
                ProjectileHitDistance = diagnosticDistance,
                ProjectileDelay = projectileDelay,
                QueuedWithoutInitialTarget = queuedWithoutInitialTarget,
                ProjectileRuntimeInitialized = spell != null && size > 0f && speed > 0f,
                FireTime = fireTime,
                FireNativeTick = fireTick,
                LastUpdateNativeTick = fireTick,
                UpdatesCompleted = initialDistance > 0f ? 1 : 0,
                MaxLifetimeTicks = maxLifetimeTicks,
                ProjectileSpeed = speed,
                ProjectileSize = size,
                StepDistance = stepDistance,
                InitialDistance = initialDistance,
                CurrentDistance = initialDistance,
                MaxDistance = maxDistance
            };
        }

        private bool UpdatePendingSpellProjectile(ref PendingSpell pending, float now, string source)
        {
            Combat.SpellData spell = pending.Spell;
            if (spell == null)
            {
                Combat.SpellDatabase.Initialize();
                spell = ResolveSpellFromManip(pending.Conn, pending.ManipId);
                pending.Spell = spell;
            }

            if (spell == null || pending.ProjectileSpeed <= 0f || pending.ProjectileSize <= 0f)
                return IsPendingSpellDue(pending, now);

            int nowTick = Combat.WeaponCycleTracker.NativeTickIndexFromTime(now);
            if (nowTick <= pending.LastUpdateNativeTick)
                return false;

            float beforeDistance = pending.CurrentDistance;
            float afterDistance = Mathf.Min(pending.MaxDistance, beforeDistance + Mathf.Max(0.001f, pending.StepDistance));
            pending.UpdatesCompleted++;
            pending.LastUpdateNativeTick = nowTick;

            if (TryResolvePendingSpellTargetAlongSegment(ref pending, beforeDistance, afterDistance, out Combat.Monster target, out float hitDistance, out bool worldBlocked))
            {
                pending.Monster = target;
                pending.ProjectileHitDistance = hitDistance;
                pending.ProjectileDelay = Mathf.Max(0f, now - pending.FireTime);
                pending.DueTime = now;
                pending.CurrentDistance = hitDistance;
                Debug.LogError($"[SPELL-PROJECTILE] subentity impact spell={spell.DisplayName ?? spell.SkillId ?? "spell"} seq={pending.Sequence} target={target.Name}#{target.EntityId} segment={beforeDistance:F2}->{afterDistance:F2} hitDist={hitDistance:F2} tick={nowTick} updates={pending.UpdatesCompleted}/{pending.MaxLifetimeTicks} radius={(Mathf.Max(0f, target.CollisionRadius) + pending.ProjectileSize):F2} worldBlocked={worldBlocked} source={source ?? "unknown"}");
                if (target.IsAlive && CombatManager.Instance.PeekMonsterCurrentHPWire(target) != 0)
                    HandleSpellAttack(pending.Conn, pending.State, target, pending.ManipId, pending.UseFlags, pending.AimX, pending.AimY, now);
                return true;
            }

            pending.CurrentDistance = afterDistance;
            if (pending.CurrentDistance + 0.0001f >= pending.MaxDistance || pending.UpdatesCompleted >= pending.MaxLifetimeTicks)
            {
                Debug.LogError($"[SPELL-PROJECTILE] expired no-hit spell={spell.DisplayName ?? spell.SkillId ?? "spell"} seq={pending.Sequence} manip={pending.ManipId} aim=({pending.AimX:F1},{pending.AimY:F1}) current={pending.CurrentDistance:F2}/{pending.MaxDistance:F2} updates={pending.UpdatesCompleted}/{pending.MaxLifetimeTicks} source={source ?? "unknown"}");
                return true;
            }

            return false;
        }

        private bool TryResolvePendingSpellTargetAlongSegment(ref PendingSpell pending, float segmentStart, float segmentEnd, out Combat.Monster hitMonster, out float hitDistance, out bool worldBlocked)
        {
            hitMonster = null;
            hitDistance = segmentEnd;
            worldBlocked = false;
            Combat.SpellData spell = pending.Spell;
            if (spell == null || pending.Conn == null)
                return false;

            float dx = pending.AimX - pending.StartX;
            float dy = pending.AimY - pending.StartY;
            float lenSq = (dx * dx) + (dy * dy);
            if (lenSq <= 0.0001f)
                return false;

            float pathDistance = Mathf.Sqrt(lenSq);
            float dirX = dx / pathDistance;
            float dirY = dy / pathDistance;
            string zoneName = !string.IsNullOrWhiteSpace(pending.Monster?.ZoneName)
                ? pending.Monster.ZoneName
                : pending.Conn.CurrentZoneName;
            float projectileSize = Mathf.Max(0f, pending.ProjectileSize);
            float scanRange = Mathf.Max(segmentEnd + projectileSize + 20f, pending.MaxDistance + projectileSize + 20f);

            Combat.Monster best = null;
            float bestAlong = float.MaxValue;
            float bestDistSq = float.MaxValue;
            bool bestBlocked = false;
            foreach (var candidate in CombatManager.Instance.GetActiveMonsters())
            {
                if (candidate == null || !candidate.IsAlive)
                    continue;
                if (CombatManager.Instance.PeekMonsterCurrentHPWire(candidate) == 0)
                    continue;
                if (!string.IsNullOrWhiteSpace(zoneName)
                    && !string.IsNullOrWhiteSpace(candidate.ZoneName)
                    && !string.Equals(candidate.ZoneName, zoneName, StringComparison.OrdinalIgnoreCase))
                    continue;

                CombatManager.Instance.TryGetMonsterWanderClientVisiblePosition(candidate, out float candidateX, out float candidateY);
                if (((candidateX - pending.StartX) * (candidateX - pending.StartX)) + ((candidateY - pending.StartY) * (candidateY - pending.StartY)) > scanRange * scanRange)
                    continue;

                float cx = candidateX - pending.StartX;
                float cy = candidateY - pending.StartY;
                float projected = (cx * dirX) + (cy * dirY);
                float radius = Mathf.Max(0f, candidate.CollisionRadius) + projectileSize;
                if (projected + radius < segmentStart || projected - radius > segmentEnd)
                    continue;

                float closestAlong = Mathf.Clamp(projected, segmentStart, segmentEnd);
                float closestX = pending.StartX + (dirX * closestAlong);
                float closestY = pending.StartY + (dirY * closestAlong);
                float missX = candidateX - closestX;
                float missY = candidateY - closestY;
                float distSq = (missX * missX) + (missY * missY);
                float radiusSq = radius * radius;
                if (distSq > radiusSq)
                    continue;

                float entryOffset = Mathf.Sqrt(Mathf.Max(0f, radiusSq - distSq));
                float impactAlong = Mathf.Clamp(projected - entryOffset, segmentStart, segmentEnd);
                PathMap pathMap = ResolveProjectilePathMap(pending.Conn, candidate);
                bool candidateWorldBlocked = pathMap != null && !pathMap.CanReachPoint(pending.StartX, pending.StartY, pending.StartX + (dirX * impactAlong), pending.StartY + (dirY * impactAlong));
                if (impactAlong < bestAlong || (Mathf.Abs(impactAlong - bestAlong) <= 0.0001f && distSq < bestDistSq))
                {
                    best = candidate;
                    bestAlong = impactAlong;
                    bestDistSq = distSq;
                    bestBlocked = candidateWorldBlocked;
                }
            }

            if (best == null)
                return false;

            CombatManager.Instance.SyncMonsterWanderClientVisiblePosition(best, "SpellProjectileChecker-subentity-hit");
            hitMonster = best;
            hitDistance = Mathf.Max(0f, bestAlong);
            worldBlocked = bestBlocked;
            return true;
        }

        private Combat.Monster ResolvePendingSpellTarget(ref PendingSpell pending, float now, string source)
        {
            if (pending.Monster != null && pending.Monster.IsAlive && CombatManager.Instance.PeekMonsterCurrentHPWire(pending.Monster) != 0)
                return pending.Monster;

            Combat.SpellData spell = pending.Spell;
            if (spell == null)
            {
                Combat.SpellDatabase.Initialize();
                spell = ResolveSpellFromManip(pending.Conn, pending.ManipId);
                pending.Spell = spell;
            }

            if (spell == null || spell.ProjectileSize <= 0f)
                return null;

            float startX = pending.StartX;
            float startY = pending.StartY;
            if (pending.Conn != null && Math.Abs(startX) <= 0.0001f && Math.Abs(startY) <= 0.0001f)
            {
                startX = pending.Conn.PlayerPosX;
                startY = pending.Conn.PlayerPosY;
            }

            Combat.Monster target = ResolvePositionSpellTargetFromStart(pending.Conn, spell, startX, startY, pending.AimX, pending.AimY, out float hitDistance);
            if (target == null)
                return null;

            pending.Monster = target;
            pending.ProjectileHitDistance = hitDistance;
            pending.ProjectileDelay = ResolveProjectileImpactDelay(spell, hitDistance);
            Debug.LogError($"[SPELL-PROJECTILE] resolved spell={spell.DisplayName ?? spell.SkillId ?? "spell"} target={target.Name}#{target.EntityId} hitDist={hitDistance:F2} due={pending.DueTime:F3} now={now:F3} source={source ?? "unknown"} queuedWithoutInitialTarget={pending.QueuedWithoutInitialTarget}");
            return target;
        }

        private bool IsPendingSpellDue(PendingSpell pending, float now)
        {
            return pending.DueTime <= 0f || now + 0.0001f >= pending.DueTime;
        }

        private float ResolvePendingSpellImpactTime(PendingSpell pending, float now)
        {
            return pending.DueTime > 0f ? pending.DueTime : now;
        }

        private SpellPreSuffixFlushResult FlushPendingSpellsForMonsterBeforeSynch(Combat.Monster monster, float now, string source)
        {
            var result = new SpellPreSuffixFlushResult
            {
                TargetEntityId = monster != null ? monster.EntityId : 0,
                PendingBefore = _pendingSpells.Count,
                BeforeHPWire = monster != null ? CombatManager.Instance.PeekMonsterCurrentHPWire(monster) : 0u
            };

            if (monster == null || result.PendingBefore == 0)
            {
                result.PendingAfter = _pendingSpells.Count;
                result.AfterHPWire = result.BeforeHPWire;
                return result;
            }

            int pendingCount = _pendingSpells.Count;
            for (int i = 0; i < pendingCount; i++)
            {
                if (!_pendingSpells.TryDequeue(out var pending))
                    break;

                if (pending.ProjectileRuntimeInitialized)
                {
                    uint beforeProjectileHP = CombatManager.Instance.PeekMonsterCurrentHPWire(monster);
                    bool consumed = UpdatePendingSpellProjectile(ref pending, now, source);
                    if (!consumed)
                    {
                        result.RequeuedFuture++;
                        _pendingSpells.Enqueue(pending);
                        continue;
                    }

                    bool sameProjectileTarget = pending.Monster != null && pending.Monster.EntityId == monster.EntityId;
                    if (sameProjectileTarget)
                        result.DueForTarget++;
                    else
                        result.DueOther++;

                    uint afterProjectileHP = CombatManager.Instance.PeekMonsterCurrentHPWire(monster);
                    if (afterProjectileHP != beforeProjectileHP)
                        result.Applied++;
                    continue;
                }

                if (!IsPendingSpellDue(pending, now))
                {
                    result.RequeuedFuture++;
                    _pendingSpells.Enqueue(pending);
                    continue;
                }

                Combat.Monster resolvedTarget = ResolvePendingSpellTarget(ref pending, now, source);
                bool sameTarget = resolvedTarget != null && resolvedTarget.EntityId == monster.EntityId;
                if (sameTarget)
                    result.DueForTarget++;
                else
                    result.DueOther++;

                if (resolvedTarget == null || !resolvedTarget.IsAlive || CombatManager.Instance.PeekMonsterCurrentHPWire(resolvedTarget) == 0)
                {
                    result.SkippedDead++;
                    if (pending.QueuedWithoutInitialTarget)
                        Debug.LogError($"[SPELL-PRE-SUFFIX] source={source ?? "unknown"} spell={pending.Spell?.DisplayName ?? pending.Spell?.SkillId ?? "UNKNOWN"} no-hit after projectile runtime aim=({pending.AimX:F1},{pending.AimY:F1}) due={pending.DueTime:F3} now={now:F3}");
                    continue;
                }

                uint beforeHP = CombatManager.Instance.PeekMonsterCurrentHPWire(resolvedTarget);
                HandleSpellAttack(
                    pending.Conn,
                    pending.State,
                    resolvedTarget,
                    pending.ManipId,
                    pending.UseFlags,
                    pending.AimX,
                    pending.AimY,
                    ResolvePendingSpellImpactTime(pending, now));
                uint afterHP = CombatManager.Instance.PeekMonsterCurrentHPWire(resolvedTarget);
                result.Applied++;
                Debug.LogError($"[SPELL-PRE-SUFFIX] source={source ?? "unknown"} target={resolvedTarget.Name}#{resolvedTarget.EntityId} behavior={resolvedTarget.BehaviorId} due={pending.DueTime:F3} now={now:F3} delay={pending.ProjectileDelay:F3} hitDist={pending.ProjectileHitDistance:F2} hp={beforeHP}->{afterHP} sameTarget={sameTarget} applied=True");
            }

            result.PendingAfter = _pendingSpells.Count;
            result.AfterHPWire = CombatManager.Instance.PeekMonsterCurrentHPWire(monster);
            if (result.PendingBefore > 0 || result.DueForTarget > 0 || result.DueOther > 0 || result.Applied > 0)
                Debug.LogError($"[SPELL-PRE-SUFFIX] source={source ?? "unknown"} target={monster.Name}#{monster.EntityId} pending={result.PendingBefore}->{result.PendingAfter} due={result.DueForTarget} dueOther={result.DueOther} applied={result.Applied} skippedDead={result.SkippedDead} future={result.RequeuedFuture} other={result.RequeuedOther} hp={result.BeforeHPWire}->{result.AfterHPWire} now={now:F3}");
            return result;
        }

        // Pending kills: legacy queue drained by native server-side finalization.
        private Dictionary<uint, (RRConnection conn, Combat.Monster monster, string source, float time)> _pendingKills
            = new Dictionary<uint, (RRConnection, Combat.Monster, string, float)>();

        /// <summary>
        /// Kill entry point. Server-computed native damage owns monster death, despawn, XP, and loot.
        /// </summary>
        private bool TryFinalizeMonsterKill(RRConnection conn, Combat.Monster monster, string source)
        {
            if (monster == null) return false;

            string killSource = source ?? "unknown";
            Debug.LogError($"[KILL-FINALIZE] {killSource}: {monster.Name} eid={monster.EntityId} conn={(conn != null ? conn.ConnId.ToString() : "null")}");
            _pendingKills.Remove(monster.EntityId);
            if (!_finalizedMonsterKills.Add(monster.EntityId))
            {
                Debug.LogError($"[KILL-DEDUP] {killSource}: {monster.Name} already finalized");
                return false;
            }
            try
            {
                ProcessMonsterKill(conn, monster, killSource);
                return true;
            }
            catch (Exception ex)
            {
                _finalizedMonsterKills.Remove(monster.EntityId);
                Debug.LogError($"[KILL-ERROR] {killSource}: failed to finalize {monster.Name}#{monster.EntityId}: {ex}");
                throw;
            }
        }

        /// <summary>
        /// Call every tick — drains legacy pending kills through the same native server finalizer.
        /// </summary>
        private void FlushPendingKills()
        {
            if (_pendingKills.Count == 0) return;

            var pending = new System.Collections.Generic.List<uint>(_pendingKills.Keys);
            foreach (uint eid in pending)
            {
                if (!_pendingKills.ContainsKey(eid))
                    continue;
                var pk = _pendingKills[eid];
                _pendingKills.Remove(eid);
                if (pk.conn == null || pk.monster == null)
                    continue;
                TryFinalizeMonsterKill(pk.conn, pk.monster, $"{pk.source}-pending-flush");
            }
        }
        /// <summary>
        /// Clears finalized kill tracking for a monster (call on respawn/despawn).
        /// </summary>
        private void ClearFinalizedKill(uint entityId)
        {
            _finalizedMonsterKills.Remove(entityId);
        }

        private static bool IsUseTargetingMonster(RRConnection conn, Combat.Monster monster)
        {
            if (conn == null || monster == null || !conn.HasActiveUseTarget)
                return false;

            ushort targetId = conn.ActiveUseTargetId;
            return targetId == (ushort)monster.EntityId ||
                   targetId == (ushort)monster.BehaviorId ||
                   targetId == (ushort)monster.UnitId ||
                   CombatManager.Instance.GetMonster(targetId) == monster ||
                   CombatManager.Instance.GetMonsterByComponent(targetId) == monster;
        }

        private void ProcessMonsterKill(RRConnection conn, Combat.Monster monster, string source)
        {
            // Dedup handled by _finalizedMonsterKills in TryFinalizeMonsterKill
            CombatManager.Instance.SetMonsterHPWire(monster, 0, true);
            CombatManager.Instance.MarkMonsterNativeDead(monster, source);
            _serverKillCount++;
            Debug.LogError($"[KILL] ═══════════════════════════════════════════════════");
            Debug.LogError($"[KILL] ★ KILL #{_serverKillCount}: {monster.Name} via [{source}]");
            Debug.LogError($"[KILL] EntityId={monster.EntityId} GCType={monster.GCType} Level={monster.Level}");
            CombatManager.Instance.BeginNativeMonsterDeathLifecycle(monster, source);

            // Send a Path C readInit-body refresh with HP=0 to all connected players in the
            // monster's zone, so client's [Unit+0x2F0] = 0 immediately. Without this, the
            // dead mob lingers "ghost-alive" on the client (last refresh HP > 0, no further
            // refreshes fire because the mob stops moving/attacking, despawn packet doesn't
            // arrive for ~30s of CorpseLingerTicks). Verified 2026-05-25 via server.log:
            // mob 50012 died at HP=0 but client kept targeting it for 20s ("shots went
            // through it"). Refresh fires before BeginNativeMonsterDeathLifecycle's normal
            // despawn timer, so client sees the kill snap to 0 HP and the death animation
            // can play, then corpse fades and despawn packet arrives at the lifecycle end.
            try
            {
                byte[] deathRefresh = Combat.CombatPackets.BuildMonsterEntityInitHPRefreshPacket(monster, 0u);
                foreach (var zoneConn in _connections.Values)
                {
                    if (zoneConn == null || !zoneConn.IsConnected || !zoneConn.IsSpawned) continue;
                    string zoneKey = GetInstanceZoneKey(zoneConn);
                    if (!string.Equals(zoneKey, monster.ZoneName, StringComparison.OrdinalIgnoreCase) &&
                        !string.Equals(zoneConn.CurrentZoneName, monster.ZoneName, StringComparison.OrdinalIgnoreCase))
                        continue;
                    SendCompressedA(zoneConn, 0x01, 0x0F, deathRefresh, SyncContext.MonsterAction, "MON-DEATH-REFRESH");
                    Debug.LogError($"[KILL] sent HP=0 refresh to conn={zoneConn.ConnId} bodyLen={deathRefresh.Length} entity={monster.EntityId}");
                }
            }
            catch (Exception killRefreshEx)
            {
                Debug.LogError($"[KILL-ERROR] death refresh failed for {monster.Name}#{monster.EntityId}: {killRefreshEx.Message}");
            }
            PlayerState playerState = conn != null ? GetPlayerState(conn.ConnId.ToString()) : null;
            if (playerState != null)
            {
                uint packetXP = ResolveMonsterExperienceReward(monster);
                uint sourceLevel = (uint)Math.Max(1, (int)monster.Level);
                uint effectiveXP = ResolveClientVisibleExperienceReward(conn, monster, playerState, packetXP, sourceLevel);
                if (packetXP > 0 && effectiveXP > 0)
                {
                    int oldLevel = playerState.Level;
                    uint oldHPWire = playerState.CurrentHPWire;
                    uint oldMaxHPWire = playerState.MaxHPWire;
                    bool leveled = playerState.AddExperience(effectiveXP);
                    CommitPlayerHPTruth(conn, playerState, leveled ? "LEVEL-UP-XP" : "KILL-XP", playerState.CurrentHPWire, false, false);
                    SendHeroAddExperienceUpdate(conn, packetXP, sourceLevel);
                    SavePlayerLevel(conn);
                    Debug.LogError($"[KILL-XP] {monster.Name}: packetXP={packetXP} effectiveXP={effectiveXP} sourceLevel={sourceLevel} level={oldLevel}->{playerState.Level}{(leveled ? " LEVELUP" : "")} HP={oldHPWire}->{playerState.CurrentHPWire}/{playerState.MaxHPWire} maxHP={oldMaxHPWire}->{playerState.MaxHPWire}");
                }
            }
            if (conn != null)
                ClearUseTargetAndReleaseControl(conn, "ProcessMonsterKill", sendClientControlReset: true, requireActiveUseTargetForReset: false);

            // Boss gate opening — DoorsToOpenOnDeath = "Boss00ExitGate"
            if (monster.GCType != null && (
                monster.GCType.Equals("creatures.whiskers.broodling.basic.champion", StringComparison.OrdinalIgnoreCase) ||
                monster.GCType.Equals("world.dungeon00.mob.boss", StringComparison.OrdinalIgnoreCase)))
            {
                Debug.LogError($"[BOSS] ★★★ RATTLE TOOTH KILLED! Opening boss gate ★★★");

                if (WorldEntitySpawner.Instance.FindEntityByName("BossGate", monster.ZoneName, out ushort gateId, out var gateData))
                {
                    // Gate-open packet — restored to the original, known-working bytes.
                    //
                    // Format: [0x03][id:2][0x0A][0x00]
                    //   0x03 = processEntityUpdate opcode (CEM @ 0x5dae30)
                    //   id   = gate entity id (uint16 LE)
                    //   0x0A = Door sub-opcode (door activate / open)
                    //   0x00 = EntitySynchInfo.flags — NOT optional.
                    //
                    // Evidence (DungeonRunnersCrash-04102026-01-29-31-392-00.log):
                    //   ClientEntityManager::processEntityUpdate logged a
                    //   synch error for "Door / RattleGate" when flags byte
                    //   was accidentally 0x06 (= has UpdateNumber + has HP).
                    //   That means processEntityUpdate reads a sync info
                    //   block after the sub-opcode:
                    //      flags(1) | if flags&?: updateNumber(4) | ... |
                    //      position | level | HP | MP | ...
                    //   Setting flags=0 tells the client to skip the whole
                    //   sync block and just process the state flip. That's
                    //   why the 5-byte packet worked and any attempt to
                    //   strip the trailing 0x00 will corrupt the next field.
                    //
                    // Delivered via MessageQueue.Enqueue (same as before) —
                    // the per-tick flush already wraps all queued messages
                    // in a single BeginStream/EndStream envelope before
                    // SendCompressedA.
                    var gateWriter = new LEWriter();
                    gateWriter.WriteByte(0x03);  // processEntityUpdate
                    gateWriter.WriteUInt16(gateId);
                    gateWriter.WriteByte(0x0A);  // Door activate (open)
                    gateWriter.WriteByte(0x00);  // EntitySynchInfo.flags = 0 (skip sync block)
                    byte[] gatePacket = gateWriter.ToArray();

                    Debug.LogError($"[BOSS] Gate entity {gateId} (0x{gateId:X4}), monster.ZoneName={monster.ZoneName}, conn.CurrentZoneName={conn.CurrentZoneName}, conn.InstanceId={conn.InstanceId}");

                    int sentCount = 0;
                    foreach (var zoneConn in _connections.Values)
                    {
                        if (!zoneConn.IsConnected || !zoneConn.IsSpawned) continue;
                        if (!string.Equals(zoneConn.CurrentZoneName, monster.ZoneName, StringComparison.OrdinalIgnoreCase)) continue;
                        if (zoneConn.InstanceId != conn.InstanceId) continue;
                        zoneConn.MessageQueue.Enqueue(gatePacket);
                        sentCount++;
                    }

                    // Fallback: also send directly to killer if broadcast missed them
                    if (sentCount == 0)
                    {
                        Debug.LogError($"[BOSS] WARNING: Broadcast matched 0 players! Sending directly to {conn.LoginName}");
                        conn.MessageQueue.Enqueue(gatePacket);
                        sentCount = 1;
                    }

                    Debug.LogError($"[BOSS] Sent gate open (0x03/0x0A flags=0) for entity {gateId} to {sentCount} players");

                    // ═══ BOSS-GATE-OPEN CHAT-LOG MESSAGE ═══
                    // Reference: user screenshot from original live game shows
                    // "The boss gate is open!" as a small message on the right
                    // side chat/event log, NOT a center-screen red announce.
                    //
                    // Previous code used chat subtype 0x10 with extra flag+sender
                    // bytes. That's the "Announce" path and either rendered
                    // incorrectly or silently dropped in this build — the user
                    // never saw the message.
                    //
                    // Fix: use the same byte layout as SendSystemMessage (subtype
                    // 0x0D / GlobalAnnouncement, no extra fields), which is
                    // proven to render in the chat feed. Broadcast to TWO sets
                    // of receivers, dedup'd by ConnId so nobody gets doubled:
                    //   (a) everyone in the same zone+instance as the killer
                    //       (the existing scope — covers solo players and
                    //        instance-sharing group members)
                    //   (b) every member of the killer's group, regardless of
                    //       where they are (belt-and-suspenders — handles the
                    //       case where an instance-id mismatch would have
                    //       dropped a legitimate party member in (a))
                    const string bossGateMsg = "The boss gate is open!";
                    var _bossMsgSeen = new System.Collections.Generic.HashSet<int>();
                    int _bossMsgSent = 0;

                    // (0) GUARANTEED: always send to the killer first.
                    // Mirrors the gate-open fallback at the top of this block.
                    // Rationale: the existing zone+instance filter used by the
                    // gate-open loop and scope (a) below rejects the killer
                    // when conn.CurrentZoneName doesn't exactly equal
                    // monster.ZoneName — which is common in boss sub-zones
                    // (e.g. player tracked as "dungeon00_level03" while the
                    // boss entity is in "dungeon00_level03_boss", or any
                    // other race/casing drift). The gate packet has its own
                    // "if (sentCount == 0) send to killer" fallback — that's
                    // why the gate animates but a pure-filter message loop
                    // sends to nobody. Instead of trying to diagnose the
                    // filter, just always include the killer up front and
                    // let the dedup hash set handle the overlap.
                    // Boss-gate on-screen popup: UNSOLVED.
                    //
                    // What we know from the RE:
                    //   - ChatClient::processMessage (0x5ff450) has 5 top-level
                    //     cases. Cases 3 and 4 go to ChatSettings::ReadData
                    //     (config, not display). Case 0 handles all standard
                    //     chat subtypes (0x02, 0x03, 0x04, 0x05, 0x0B, 0x0C,
                    //     0x0D, 0x10) and every one of them converges at
                    //     0x5ff92a -> std::vector<ChatClient::ChatMessage>
                    //     ::push_back. That means NO chat subtype produces a
                    //     separate right-side popup — they all go to the chat
                    //     log. Firing four subtypes was a waste; dropping it.
                    //   - BossGate.gc literally has
                    //       OpenMessage = "The boss gate is open!";
                    //     and the client has PropertyDoorDescOpenMessage +
                    //     PropertyNonCombatInteractiveDescOpenMessage — so the
                    //     popup IS a real client-side mechanism, just not a
                    //     chat one. Most likely path: when the client sees the
                    //     boss die, its own engine reads
                    //     UnitDesc::DoorsToOpenOnDeath (boss.gc sets this to
                    //     "Boss00ExitGate") and locally opens the door,
                    //     which triggers the description's OpenMessage. That
                    //     requires a proper unit-death packet, not the
                    //     hand-crafted 0x03/0x0A gate update this server is
                    //     sending today.
                    //
                    // For now: send ONE 0x0D chat message to the killer only.
                    // No group broadcast, no zone broadcast, no subtype
                    // shotgun. Keeps chat clean while the real popup path is
                    // still being reversed.
                    if (conn != null && conn.IsConnected)
                    {
                        SendSystemMessage(conn, bossGateMsg);
                        _bossMsgSent = 1;
                    }

                    Debug.LogError($"[BOSS] Boss-gate message '{bossGateMsg}' sent to {_bossMsgSent} player(s) (zone+instance+group dedup'd)");

                    // === BOSS-GATE ON-SCREEN POPUP via Quest Add+Progress+Remove ===
                    // Fires LAST in the boss-kill flow so gate-open and chat are
                    // already done. Wrapped in try/catch so a failure in this path
                    // does not break the gate animation or chat fallback above.
                    // Broadcasts to every player in killer's zone+instance.
                    try
                    {
                        int _popupSent = 0;
                        var _popupSeen = new System.Collections.Generic.HashSet<int>();
                        foreach (var popupConn in _connections.Values)
                        {
                            if (popupConn == null) continue;
                            if (!popupConn.IsConnected || !popupConn.IsSpawned) continue;
                            if (popupConn.QuestManagerId == 0) continue;
                            if (!string.Equals(popupConn.CurrentZoneName, monster.ZoneName, StringComparison.OrdinalIgnoreCase)) continue;
                            if (popupConn.InstanceId != conn.InstanceId) continue;
                            if (!_popupSeen.Add(popupConn.ConnId)) continue;
                            SendBossGatePopup(popupConn);
                            _popupSent++;
                        }
                        if (conn != null && conn.IsConnected && conn.QuestManagerId != 0 && _popupSeen.Add(conn.ConnId))
                        {
                            SendBossGatePopup(conn);
                            _popupSent++;
                        }
                        Debug.LogError($"[BOSS-POPUP] Triggered popup sequence for {_popupSent} player(s)");
                    }
                    catch (Exception _popupEx)
                    {
                        Debug.LogError($"[BOSS-POPUP] FAILED (non-fatal): {_popupEx.Message}");
                    }
                }
                else
                {
                    Debug.LogError($"[BOSS] WARNING: Could not find BossGate entity in zone {monster.ZoneName}");
                }
            }

            // Pass BOTH possible match strings to QuestManager. Your DB has quest
            // targets in two namespaces:
            //   * creatures.forestCreatures.Warg.Basic.Grunt  (raw creature GCType)
            //   * world.dungeon00.mob.melee03                 (dungeon-specific SpawnGCType)
            // Depending on which namespace a quest was authored in, one or the other
            // will match. QuestManager dedupes so each objective advances exactly once.
            var candidateGcTypes = new System.Collections.Generic.List<string>();
            if (!string.IsNullOrEmpty(monster.SpawnGCType))
                candidateGcTypes.Add(monster.SpawnGCType);
            if (!string.IsNullOrEmpty(monster.GCType))
                candidateGcTypes.Add(monster.GCType);
            var questUpdates = QuestManager.Instance.OnCreatureKilled(conn, candidateGcTypes);
            if (questUpdates != null && questUpdates.Count > 0)
            {
                Debug.LogError($"[KILL] Quest objectives updated: {questUpdates.Count}");
                SavePlayerQuests(conn);  // Persist kill progress immediately
            }
            if (playerState != null)
            {
                SavePlayerLevel(conn);
                Debug.LogError($"[KILL] Saved XP={playerState.Experience} Level={playerState.Level}");
            }

            // ═══ LOOT GENERATION — DLL-confirmed kill ═══
            try
            {
                int pLevel = playerState?.Level ?? 1;
                List<LootDrop> drops;

                if (WorldObjectSpawner.IsDestroyableObject(monster.GCType))
                    drops = LootManager.Instance.GenerateBarrelLoot(pLevel);
                else
                    drops = LootManager.Instance.GenerateMobLoot(monster, pLevel);

                // Member players get Major potions (MaxStackSize=10) instead of
                // Minor potions (MaxStackSize=5). Free players keep minors.
                UpgradePotionsForMembers(drops, conn);

                foreach (var drop in drops)
                {
                    if (drop.IsGold)
                    {
                        uint lootGold = (uint)drop.GoldAmount;
                        Debug.LogError($"[LOOT] +{lootGold} gold pile from {monster.Name}");
                        try
                        {
                            float gpx = monster.PosX + (float)(_lootRng.NextDouble() * 4.0 - 2.0);
                            float gpy = monster.PosY + (float)(_lootRng.NextDouble() * 4.0 - 2.0);
                            float gpz = monster.PosZ;
                            ushort goldEntityId = GetNextLootEntityId();

                            var goldInfo = new DroppedItemInfo
                            {
                                Item = null,
                                DbId = 0,
                                Zone = conn.CurrentZoneName ?? "",
                                ZoneId = conn.CurrentZoneId,
                                InstanceId = conn.InstanceId,
                                PosX = gpx,
                                PosY = gpy,
                                PosZ = gpz,
                                PlayerLevel = playerState?.Level ?? 1,
                                DroppedBy = conn.LoginName ?? "",
                                IsGoldDrop = true,
                                GoldAmount = lootGold
                            };
                            _droppedItems[goldEntityId] = goldInfo;
                            SendGoldPileSpawnPacket(conn, goldEntityId, gpx, gpy, gpz);
                        }
                        catch (Exception goldLootEx)
                        {
                            Debug.LogError($"[LOOT] ❌ gold pile spawn failed: {goldLootEx.Message}");
                        }
                    }
                    else if (drop.IsKingsCoin)
                    {
                        // Kings Coin GROUND drop. Build a GCObject for QuestItemPAL.Token
                        // and route through the same TrackDroppedItem path the regular
                        // weapon/armor drops use. The pickup handler stacks Kings Coins
                        // automatically when added to inventory (BaseQuestItem extends Item
                        // and has Stackable=true MaxStackSize=100 in QuestItemPAL.gc).
                        //
                        // CRITICAL: this branch must exist BEFORE the regular item else,
                        // because LootDrop.KingsCoin sets GCType=null which would NPE in
                        // the NativeClass detection path. RollKingsCoin in LootManager
                        // adds these to the drops list whenever a tier-based roll succeeds.
                        try
                        {
                            int kcCount = drop.KingsCoinCount > 0 ? drop.KingsCoinCount : 1;
                            for (int kcIdx = 0; kcIdx < kcCount; kcIdx++)
                            {
                                var kcItem = new GCObject
                                {
                                    GCClass = "QuestItemPAL.Token",
                                    NativeClass = "Item",
                                    PresetScaleMod = "ScaleModPAL.Binder.Mod1",
                                    StoredRarity = (int)ItemRarity.Normal,
                                    StoredLevel = pLevel
                                };
                                float kcPx = monster.PosX + (float)(_lootRng.NextDouble() * 6.0 - 3.0);
                                float kcPy = monster.PosY + (float)(_lootRng.NextDouble() * 6.0 - 3.0);
                                float kcPz = monster.PosZ;
                                ushort kcEntityId = GetNextLootEntityId();
                                TrackDroppedItem(kcEntityId, kcItem, conn);
                                if (_droppedItems.TryGetValue(kcEntityId, out var kcInfo))
                                {
                                    kcInfo.PosX = kcPx;
                                    kcInfo.PosY = kcPy;
                                    kcInfo.PosZ = kcPz;
                                    kcInfo.PlayerLevel = pLevel;
                                }
                                SendDroppedItemSpawnPacket(conn, kcEntityId, _droppedItems[kcEntityId]);
                            }
                            Debug.LogError($"[LOOT-KC] dropped {kcCount} Kings Coin(s) on ground from {monster.Name}");
                        }
                        catch (Exception kcEx)
                        {
                            Debug.LogError($"[LOOT-KC] ground drop failed (non-fatal): {kcEx.Message}");
                        }
                    }
                    else
                    {
                        // ═══ NativeClass detection for loot drop ═══
                        // The previous code did Contains("weapon") which fails for
                        // almost every weapon item — 1hswordpal, 2haxepal, 2hmacepal,
                        // 1hstaffpal, 2hpickpal etc. don't contain the literal substring
                        // "weapon", so they were all labeled as NativeClass="Armor".
                        // The client looks up GC classes in per-NativeType tables;
                        // a weapon's class hash isn't in the Armor table → fatal
                        // "Couldn't find GC object of type X. Native Type: 'Armor'" →
                        // parser desync → "Unknown message type(10)" crash.
                        //
                        // The inventory-drop path (InventoryHandler.HandleDropItem)
                        // never had this bug because items there come from
                        // GCObjectFactory which parses the GC files and sets the
                        // correct NativeClass. This loot path bypasses that and
                        // builds a GCObject by hand, so we have to set it manually.
                        //
                        // Verified against drlive.db: zero armor or items-table rows
                        // contain any of these weapon keywords as a prefix substring,
                        // so this filter has no false positives. Rings/amulets are
                        // handled inside WriteInitForDroppedItem itself (line ~215
                        // forces NativeClass="Item" when GCClass contains "ring" or
                        // "amulet"), so we don't need a special case for them here.
                        if (string.IsNullOrEmpty(drop.GCType)) { Debug.LogError($"[LOOT] ⚠️ Skipping null GCType from {monster.Name}"); continue; }
                        string _gcLootLower = drop.GCType.ToLowerInvariant();
                        string _detectedNativeClass = "Armor";
                        if (_gcLootLower.Contains("crossbow") || _gcLootLower.Contains("bow") ||
                            _gcLootLower.Contains("gun") || _gcLootLower.Contains("cannon") ||
                            _gcLootLower.Contains("ranged"))
                        {
                            _detectedNativeClass = "RangedWeapon";
                        }
                        else if (_gcLootLower.Contains("sword") || _gcLootLower.Contains("axe") ||
                                 _gcLootLower.Contains("mace") || _gcLootLower.Contains("pick") ||
                                 _gcLootLower.Contains("staff") || _gcLootLower.Contains("club") ||
                                 _gcLootLower.Contains("katana") || _gcLootLower.Contains("polearm") ||
                                 _gcLootLower.Contains("melee"))
                        {
                            _detectedNativeClass = "MeleeWeapon";
                        }
                        // Potions, scrolls, skill books, vouchers, and other
                        // consumables all extend ActiveItem in the .gc hierarchy
                        // (BasePotion/BaseScroll/BaseSkillBook/BaseVoucher all
                        // 'extends ActiveItem'). ActiveItem is a C++ native in
                        // dr.exe — verified present as an exact string. Without
                        // this branch, potionpal.* drops from GenerateBarrelLoot
                        // get written with NativeClass='Armor' and armor-shaped
                        // init bytes (equipSlot=10, level=10), which the client's
                        // potion parser rejects → parser desync → Unknown
                        // message type(0) crash.
                        else if (_gcLootLower.Contains("potion") || _gcLootLower.Contains("scroll") ||
                                 _gcLootLower.Contains("skillbook") || _gcLootLower.Contains("voucher") ||
                                 _gcLootLower.Contains("consumable"))
                        {
                            _detectedNativeClass = "ActiveItem";
                        }

                        var item = new GCObject
                        {
                            GCClass = drop.GCType,
                            NativeClass = _detectedNativeClass,
                            PresetScaleMod = drop.ScaleMod,
                            StoredRarity = (int)drop.Rarity,
                            StoredLevel = drop.ItemLevel
                        };
                        // Use System.Random instead of UnityEngine.Random.Range —
                        // ProcessMonsterKill is called from OnUDPReceive which runs
                        // on a thread pool callback, NOT the Unity main thread.
                        // UnityEngine.Random.Range throws "Range can only be called
                        // from the main thread" and the catch swallows the item.
                        // (WeaponCycle-tick path was on the main thread so it
                        // worked there, which masked this bug for admin kills.)
                        float px = monster.PosX + (float)(_lootRng.NextDouble() * 6.0 - 3.0);
                        float py = monster.PosY + (float)(_lootRng.NextDouble() * 6.0 - 3.0);
                        float pz = monster.PosZ;

                        ushort lootEntityId = GetNextLootEntityId();
                        TrackDroppedItem(lootEntityId, item, conn);

                        if (_droppedItems.TryGetValue(lootEntityId, out var lootInfo))
                        {
                            lootInfo.PosX = px;
                            lootInfo.PosY = py;
                            lootInfo.PosZ = pz;
                            lootInfo.PlayerLevel = pLevel;
                        }

                        SendDroppedItemSpawnPacket(conn, lootEntityId, _droppedItems[lootEntityId]);
                        Debug.LogError($"[LOOT] ★ {drop.Label} ({drop.Rarity}) at ({px:F0},{py:F0},{pz:F0})");
                    }
                }

                if (drops.Count > 0)
                    Debug.LogError($"[LOOT] {monster.Name}: {drops.Count} drops");
            }
            catch (Exception lootEx)
            {
                Debug.LogError($"[LOOT] ERROR: {lootEx.Message}\n{lootEx.StackTrace}");
            }
            // ═══ END LOOT ═══

            // ═══ QUEST ITEM DROPS — KillDropTrigger from quest GC files ═══
            // For each of the player's active quests, look up drop rules
            // indexed by this monster's GCType (and SpawnGCType, since the
            // quest GC files use the world.dungeonNN.mob.* namespace while
            // the creature DB uses creatures.* — same dual-namespace problem
            // the kill objective system handles).
            //
            // Quest items are NOT spawned as world entities. The drop is
            // credited directly via NotifyQuestItemAcquired, which calls
            // QuestManager.OnItemPickedUp → progress packet → client sees the
            // counter increment. This is intentional:
            //   1. Quest items aren't equipment, so the SendDroppedItemSpawnPacket
            //      / WriteInitForDroppedItem path can't serialize them — it
            //      writes garbage and the client crashes on "Unknown message
            //      type(0)".
            //   2. Pelts/dreamcatchers/etc are logically just counters; no
            //      reason to make the player walk over and pick them up.
            //   3. Zero packet risk — we never put the item in the world.
            try
            {
                var pState = QuestManager.Instance.GetPlayerState(conn.ConnId.ToString());
                if (pState != null && pState.ActiveQuests != null && pState.ActiveQuests.Count > 0)
                {
                    var qdCandidates = new System.Collections.Generic.List<string>();
                    if (!string.IsNullOrEmpty(monster.SpawnGCType))
                        qdCandidates.Add(monster.SpawnGCType);
                    if (!string.IsNullOrEmpty(monster.GCType))
                        qdCandidates.Add(monster.GCType);

                    var activeIds = new System.Collections.Generic.HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    foreach (var aq in pState.ActiveQuests)
                        if (!string.IsNullOrEmpty(aq.QuestId)) activeIds.Add(aq.QuestId);

                    // Dedup credited items within this single kill so a wolf
                    // pelt can be credited at most once even if multiple rules
                    // match (e.g. if pup gctype matches via both SpawnGCType
                    // and creature GCType lookups).
                    var creditedItemTypes = new System.Collections.Generic.HashSet<string>(StringComparer.OrdinalIgnoreCase);

                    int qdRolled = 0, qdHit = 0;
                    foreach (var cand in qdCandidates)
                    {
                        if (string.IsNullOrEmpty(cand)) continue;
                        if (!DatabaseLoader.QuestKillDropsByMonster.TryGetValue(cand, out var rules)) continue;

                        foreach (var rule in rules)
                        {
                            if (!activeIds.Contains(rule.QuestId)) continue;
                            if (creditedItemTypes.Contains(rule.ItemGcType)) continue;
                            if (rule.Chance < 1) continue;

                            qdRolled++;
                            // Chance is 1-in-N denominator: Chance=20 → 5%
                            if (_lootRng.Next(rule.Chance) != 0) continue;

                            // Hit! Put the quest item in the player's inventory
                            // via the established GiveStackedItem path (the same
                            // path used for King's Coin rewards on quest turn-in
                            // — opcode 0x1E AddItem for new stacks, 0x22
                            // UpdateQuantity for topping up existing ones).
                            //
                            // Then notify QuestManager so the objective counter
                            // increments and the client gets a progress packet.
                            // GiveStackedItem doesn't call NotifyQuestItemAcquired
                            // internally — we have to do it explicitly.
                            creditedItemTypes.Add(rule.ItemGcType);
                            qdHit++;
                            Debug.LogError($"[QUEST-DROP] ★ {rule.ItemGcType} for {conn.LoginName} ({rule.QuestId}, 1-in-{rule.Chance})");
                            // Spawn quest item on ground near dead mob
                            var qdItem = new GCObject
                            {
                                GCClass = rule.ItemGcType,
                                NativeClass = "Item",
                                StoredLevel = 1
                            };
                            float qdPx = monster.PosX + (float)(_lootRng.NextDouble() * 4.0 - 2.0);
                            float qdPy = monster.PosY + (float)(_lootRng.NextDouble() * 4.0 - 2.0);
                            float qdPz = monster.PosZ;
                            ushort qdEntityId = GetNextLootEntityId();
                            TrackDroppedItem(qdEntityId, qdItem, conn);
                            if (_droppedItems.TryGetValue(qdEntityId, out var qdInfo))
                            {
                                qdInfo.PosX = qdPx;
                                qdInfo.PosY = qdPy;
                                qdInfo.PosZ = qdPz;
                                qdInfo.PlayerLevel = 1;
                                qdInfo.IsQuestItem = true;
                            }
                            SendDroppedItemSpawnPacket(conn, qdEntityId, _droppedItems[qdEntityId]);
                        }
                    }
                    if (qdRolled > 0)
                        Debug.LogError($"[QUEST-DROP] {monster.Name}: rolled {qdRolled}, credited {qdHit}");
                }
            }
            catch (Exception qdEx)
            {
                Debug.LogError($"[QUEST-DROP] ERROR: {qdEx.Message}\n{qdEx.StackTrace}");
            }
            // ═══ END QUEST ITEM DROPS ═══

            Debug.LogError($"[KILL] ═══════════════════════════════════════════════════");
        }

        /// <summary>
        /// Sends XP update to client via Entity::sendUpdate (0x28) type 0x0F on avatar entity.
        /// Client processes this at Hero::processUpdateAddExperience with own scaling.
        /// Payload: packet XP seed(uint32) + sourceLevel(byte); client applies native source-level/ExperienceMod scaling.
        /// </summary>
        private void SendHeroAddExperienceUpdate(RRConnection conn, uint baseXP, uint sourceLevel)
        {
            uint avatarId = GetPlayerAvatarId(conn.LoginName);
            if (avatarId == 0) return;

            var writer = new LEWriter();
            writer.WriteByte(0x07);              // BeginStream
            writer.WriteByte(0x03);              // processEntityUpdate — CEM dispatch table @ 0x5DA730
            writer.WriteUInt16((ushort)avatarId);
            writer.WriteByte(0x0F);              // update type = AddExperience
            writer.WriteUInt32(baseXP);
            writer.WriteByte((byte)sourceLevel); // source level is byte, not uint32 — binary @ 0x4F91A0
            WritePlayerEntitySynch(conn, writer);
            writer.WriteByte(0x06);              // EndStream

            SendCompressedA(conn, 0x01, 0x0F, writer.ToArray());
            Debug.LogError($"[XP-PACKET] Sent 0x03 via CompressedA: baseXP={baseXP} sourceLevel={sourceLevel}");
        }

        /// <summary>
        /// Public wrapper for admin level-up command to send XP to client.
        /// </summary>
        public void SendAdminXPUpdate(RRConnection conn, uint baseXP, uint sourceLevel)
        {
            SendHeroAddExperienceUpdate(conn, baseXP, sourceLevel);
        }

        /// <summary>
        /// Send FreePlayerExperienceModifier to client.
        /// Binary: Modifiers::processUpdate type 0x00 → processAddModifier @ 0x502280
        /// Reads GC type via readType @ 0x5E3C40, creates instance, calls readData @ 0x4FF390.
        /// TTD-PROVEN: vtable[0xB8] = Modifier::readData (NOT readInit 0x4FF4C0).
        /// readData reads 14 bytes: uint32 ID + byte Level + uint32 PowerLevel + uint32 Duration + byte SourceIsSelf.
        /// CEM reads EntitySynchInfo after processUpdate returns (0x5DB605).
        /// </summary>
        public void SendFreePlayerModifier(RRConnection conn)
        {
            if (conn.ModifiersId == 0)
            {
                Debug.LogError("[XP-MOD] Cannot send FreePlayerModifier — ModifiersId not set");
                return;
            }

            var writer = new LEWriter();
            writer.WriteByte(0x07);              // BeginStream
            writer.WriteByte(0x35);              // ComponentUpdate
            writer.WriteUInt16((ushort)conn.ModifiersId);
            writer.WriteByte(0x00);              // processAddModifier type
            WriteGCType(writer, "avatar.base.FreePlayerExperienceModifier", preserveCase: true);
            // Modifier::readData — 14 bytes (TTD-proven @ 0x4FF390):
            writer.WriteUInt32(1);               // [+0x78] ID
            writer.WriteByte(0);                 // [+0x86] Level
            writer.WriteUInt32(0);               // [+0x80] PowerLevel
            writer.WriteUInt32(0x00000000);      // [+0x7C] Duration (0=permanent)
            writer.WriteByte(0x01);              // [+0x87] SourceIsSelf bit 0 = permanent
            WritePlayerEntitySynch(conn, writer);
            writer.WriteByte(0x06);              // EndStream

            SendCompressedA(conn, 0x01, 0x0F, writer.ToArray());
            Debug.LogError($"[XP-MOD] Sent FreePlayerModifier (single) modifiersId={conn.ModifiersId}");
        }

        private System.Collections.IEnumerator SendDelayedFreePlayerModifier(RRConnection conn, float delay)
        {
            yield return new UnityEngine.WaitForSeconds(delay);
            if (!_freePlayerModifierSent.Contains(conn.LoginName + "_sent"))
            {
                _freePlayerModifierSent.Add(conn.LoginName + "_sent");
                SendFreePlayerModifier(conn);
            }
        }

        /// <summary>
        /// Send a tracked modifier to the client. Same packet format as SendFreePlayerModifier
        /// but with variable GCType/data from the ActiveModifier record.
        /// Binary: Modifiers::processUpdate type 0x00 → processAddModifier @ 0x502280
        /// </summary>
        private void SendTrackedModifier(RRConnection conn, ActiveModifier mod)
        {
            if (conn.ModifiersId == 0)
            {
                Debug.LogError($"[MOD-RESEND] Cannot send '{mod.GCType}' — ModifiersId not set");
                return;
            }

            var writer = new LEWriter();
            writer.WriteByte(0x07);              // BeginStream
            writer.WriteByte(0x35);              // ComponentUpdate
            writer.WriteUInt16((ushort)conn.ModifiersId);
            writer.WriteByte(0x00);              // processAddModifier type
            WriteGCType(writer, mod.GCType, preserveCase: true);
            // Modifier::readData — 14 bytes (TTD-proven @ 0x4FF390):
            writer.WriteUInt32(mod.Id);          // [+0x78] ID
            writer.WriteByte(mod.Level);         // [+0x86] Level
            writer.WriteUInt32(mod.PowerLevel);  // [+0x80] PowerLevel
            writer.WriteUInt32(mod.Duration);    // [+0x7C] Duration (0=permanent)
            writer.WriteByte(mod.SourceIsSelf);  // [+0x87] SourceIsSelf
            WritePlayerEntitySynch(conn, writer);
            writer.WriteByte(0x06);              // EndStream

            SendCompressedA(conn, 0x01, 0x0F, writer.ToArray());
            Debug.LogError($"[MOD-RESEND] Sent '{mod.GCType}' id={mod.Id} dur={mod.Duration} ticks ({mod.Duration * 24.0 / 1000.0:F1}s) to {conn.LoginName}");
        }

        /// <summary>
        /// Re-send all tracked modifiers after zone transition spawn.
        /// <summary>
        /// Public API for any code to track a modifier sent to a player.
        /// All tracked modifiers are automatically re-sent on zone transition.
        /// Do NOT track FreePlayerModifier — it persists on its own.
        /// </summary>
        public void TrackModifierSent(string loginName, string gcType, uint modId,
            byte level = 0, uint powerLevel = 0, uint duration = 0, byte sourceIsSelf = 0)
        {
            _modifierTracker.TrackModifier(loginName, new ActiveModifier
            {
                GCType = gcType,
                Id = modId,
                Level = level,
                PowerLevel = powerLevel,
                Duration = duration,
                SourceIsSelf = sourceIsSelf,
                AddedAt = DateTime.UtcNow
            });
        }

        /// <summary>
        /// Public API to remove a tracked modifier by GCType.
        /// </summary>
        public void UntrackModifier(string loginName, string gcType)
        {
            _modifierTracker.RemoveModifier(loginName, gcType);
        }

        /// <summary>
        /// Re-send all tracked modifiers after zone transition spawn.
        /// Called after SendPlayerEntitySpawn in both zone transition paths.
        /// Only admin buffs live here — FreePlayer persists on its own.
        /// </summary>
        private void ResendAllModifiers(RRConnection conn)
        {
            if (conn.LoginName == null || conn.ModifiersId == 0) return;

            var mods = _modifierTracker.GetModifiers(conn.LoginName);
            if (mods.Count == 0) return;

            Debug.LogError($"[MOD-RESEND] Re-sending {mods.Count} modifiers for {conn.LoginName} after zone transition");
            foreach (var mod in mods)
            {
                SendTrackedModifier(conn, mod);
            }
        }

        /// <summary>
        /// Iterates a monster's Manipulators, extracts the short GC name,
        /// and resolves it through _weaponDebuffMap then _creatureDebuffMap.
        /// Returns list of (modifierGcType, durationInTicks).
        /// </summary>
        private List<(string modGcType, uint durationTicks)> ResolveMonsterDebuffs(Combat.Monster monster)
        {
            var result = new List<(string, uint)>();
            if (monster?.Manipulators == null) return result;

            // Manipulators is Dictionary<string, ManipulatorData>; key = manipulator name/gcType
            foreach (var kvp in monster.Manipulators)
            {
                // Use the ManipulatorData.gcType if available, fall back to the key
                string gcType = !string.IsNullOrEmpty(kvp.Value?.gcType) ? kvp.Value.gcType : kvp.Key;
                if (string.IsNullOrEmpty(gcType)) continue;

                // Extract short name: "skills.creature.BasicSlow" → "basicslow"
                string shortName = gcType.ToLowerInvariant();
                int dot = shortName.LastIndexOf('.');
                if (dot >= 0) shortName = shortName.Substring(dot + 1);

                // Look up weapon map first (maps weapon GC names → debuff skill names),
                // then try direct creature debuff map lookup
                string debuffKey = null;
                if (_weaponDebuffMap.TryGetValue(shortName, out var wk)) debuffKey = wk;
                else if (_creatureDebuffMap.ContainsKey(shortName)) debuffKey = shortName;

                if (debuffKey == null) continue;
                if (!_creatureDebuffMap.TryGetValue(debuffKey, out var debuffInfo)) continue;

                uint ticks = debuffInfo.durationSec <= 0 ? 0
                    : (uint)(debuffInfo.durationSec * (1000.0 / 24.0));
                result.Add((debuffInfo.modGcType, ticks));
            }
            return result;
        }

        /// <summary>
        /// Sends processAddModifier for each resolved monster debuff and tracks it.
        /// Respects per-modifier cooldown so the same debuff is not re-applied
        /// until its duration has expired.
        /// [MON-DEBUFF] log tag.
        /// </summary>
        private void ApplyMonsterDebuffs(RRConnection conn, Combat.Monster monster)
        {
            if (conn.ModifiersId == 0 || conn.LoginName == null) return;

            var debuffs = ResolveMonsterDebuffs(monster);
            if (debuffs.Count == 0) return;

            var now = DateTime.UtcNow;
            if (!_debuffCooldowns.TryGetValue(conn.LoginName, out var cooldowns))
            {
                cooldowns = new Dictionary<string, DateTime>(StringComparer.OrdinalIgnoreCase);
                _debuffCooldowns[conn.LoginName] = cooldowns;
            }

            foreach (var (modGcType, durationTicks) in debuffs)
            {
                // Check cooldown: skip if this debuff was applied recently
                float durationSec = durationTicks * 24f / 1000f;
                if (cooldowns.TryGetValue(modGcType, out var lastApplied))
                {
                    if ((now - lastApplied).TotalSeconds < durationSec)
                    {
                        Debug.LogError($"[MON-DEBUFF] Skipping '{modGcType}' — still active for {conn.LoginName}");
                        continue;
                    }
                }

                uint modId = _modifierTracker.NextId();
                TrackModifierSent(conn.LoginName, modGcType, modId, level: 0, duration: durationTicks, sourceIsSelf: 0x00);
                cooldowns[modGcType] = now;
                Debug.LogError($"[MON-DEBUFF] Applied '{modGcType}' dur={durationTicks} ticks to {conn.LoginName}");
            }
        }


        /// <summary>
        /// Sends RemoveExperience to client via Entity::sendUpdate type 0x10.
        /// Binary: Hero::onRemoveExperience @ 0x4F88B0 — RAW subtraction, floors at level threshold.
        /// Used to correct client's auto-calculated kill XP when xpMultiplier &lt; ExperienceMod(5.0).
        /// </summary>
        private void SendHeroRemoveExperienceUpdate(RRConnection conn, uint xpAmount)
        {
            uint avatarId = GetPlayerAvatarId(conn.LoginName);
            if (avatarId == 0) return;

            var writer = new LEWriter();
            writer.WriteByte(0x07);              // BeginStream
            writer.WriteByte(0x03);              // processEntityUpdate
            writer.WriteUInt16((ushort)avatarId);
            writer.WriteByte(0x10);              // update type = RemoveExperience
            writer.WriteUInt32(xpAmount);         // XP to remove (RAW, no scaling)
            WritePlayerEntitySynch(conn, writer);
            writer.WriteByte(0x06);              // EndStream

            SendCompressedA(conn, 0x01, 0x0F, writer.ToArray());
            Debug.LogError($"[XP-PACKET] Sent RemoveExperience: {xpAmount}");
        }

        /// <summary>
        /// Send HP sync after admin level change so client updates HP bar.
        /// </summary>
        public void SendAdminHPSync(RRConnection conn, PlayerState ps)
        {
            if (conn.UnitBehaviorId == 0) return;

            var writer = new LEWriter();
            writer.WriteByte(0x07);              // BeginStream
            writer.WriteByte(0x35);              // ComponentUpdate on UnitBehavior
            writer.WriteUInt16((ushort)conn.UnitBehaviorId);
            writer.WriteByte(0x65);              // UnitMoverUpdate
            writer.WriteByte(conn.SessionID++);
            writer.WriteByte(0x01);              // Update count
            writer.WriteByte(0x03);              // Flags: heading + position
            writer.WriteInt32((int)(conn.PlayerHeading * 256));
            writer.WriteInt32((int)(conn.PlayerPosX * 256));
            writer.WriteInt32((int)(conn.PlayerPosY * 256));
            WritePlayerEntitySynch(conn, writer);
            writer.WriteByte(0x06);              // EndStream
            SendToClient(conn, writer.ToArray());
            Debug.LogError($"[ADMIN-HP] Sent HP sync via UnitBehavior: {ps.CurrentHPWire / 256}/{ps.MaxHPWire / 256}");
        }

        /// <summary>
        /// Callback for admin LevelSelf button: sends XP packets to trigger client-side
        /// level-up effects (Avatar::OnLevelUp -> LevelEffect + LevelUpSound), then HP sync.
        /// </summary>
        private void HandleAdminLevelUp(RRConnection conn, PlayerState ps, int oldLevel, int newLevel)
        {
            // Gate: only admins can use /adminui level-up
            if (!IsPlayerAdmin(conn.LoginName))
            {
                SendSystemMessage(conn, "You do not have permission.");
                return;
            }

            if (conn.Avatar != null)
                CalculateEquipmentBonuses(conn.ConnId.ToString(), conn.Avatar);
            ps.RestoreToFull();

            // Client formula: clientXP = (packetXP * ExperienceMod + 128) >> 8
            // Reverse: packetXP = threshold * 256 / ExperienceMod + margin
            for (int lv = oldLevel; lv < newLevel; lv++)
            {
                uint threshold = PlayerState.GetClientThreshold(lv + 1);
                uint packetXP = threshold * 256 / 5 + 100;
                SendAdminXPUpdate(conn, packetXP, (uint)lv);
                Debug.LogError($"[ADMIN-LEVELUP] Level {lv}->{lv + 1}: threshold={threshold} packetXP={packetXP}");
            }

            SendAdminHPSync(conn, ps);
            Debug.LogError($"[ADMIN-LEVELUP] Sent {newLevel - oldLevel} XP packet(s) + HP sync for level {oldLevel}->{newLevel}");
            // Posse: refresh other members' rosters with the new Lvl value.
            try { if (conn.CharSqlId != 0) PosseManager.Instance.NotifyMemberStateChange(conn.CharSqlId, this); }
            catch (Exception px) { Debug.LogError($"[POSSE] level-up notify failed: {px.Message}"); }
        }


        /// <summary>
        /// Handles client movement updates (0x02) - WASD or pathfinding movement
        /// </summary>
        private void HandleClientMove(RRConnection conn, LEReader reader, ushort componentId)
        {
            try
            {
                byte sessionId = reader.ReadByte();
                byte moveCount = reader.ReadByte();

                float lastX = 0, lastY = 0, lastHeading = 0;
                float previousX = conn.PlayerPosX;
                float previousY = conn.PlayerPosY;
                // Capture raw move data for multiplayer relay
                int rawStartPos = reader.Position;
                for (int i = 0; i < moveCount; i++)
                {
                    byte moveType = reader.ReadByte();
                    int heading = reader.ReadInt32();
                    int posX = reader.ReadInt32();
                    int posY = reader.ReadInt32();

                    lastX = posX / 256.0f;
                    lastY = posY / 256.0f;
                    lastHeading = heading / 256.0f;
                }
                int rawEndPos = reader.Position;
                TryConsumeClientSyncSuffix(conn, reader, "MOVE-SYNC");

                if (moveCount > 0)
                {
                    bool positionChanged = !conn.HasLivePlayerPosition || Math.Abs(lastX - previousX) > 0.001f || Math.Abs(lastY - previousY) > 0.001f;
                    if (positionChanged && IsZoneSpawnInvulnerabilityBlockingCombat(conn))
                        ClearZoneSpawnInvulnerability(conn, "MOVE");
                    conn.PlayerPosX = lastX;
                    conn.PlayerPosY = lastY;
                    conn.PlayerHeading = lastHeading;
                    conn.HasLivePlayerPosition = true;
                    conn.LivePlayerPosX = lastX;
                    conn.LivePlayerPosY = lastY;
                    conn.LivePlayerPosZ = conn.PlayerPosZ;
                    conn.LivePlayerHeading = lastHeading;
                    conn.LivePlayerPositionTime = Time.time;

                    uint avatarId = GetPlayerAvatarId(conn.LoginName);
                    if (avatarId != 0)
                    {
                        CombatManager.Instance.UpdatePlayerPosition(avatarId, lastX, lastY);
                    }
                    // Throttled proximity check for goto quest objectives (1x/sec max)
                    CheckGotoProximity(conn);
                    CheckPendingMerchantActivation(conn);
                    // CheckWorldEntityProximity removed — click activation works via TTD-proven UnitBehavior
                }
                conn.SessionID = sessionId;

                // ═══ MULTIPLAYER: Movement relay ═══
                byte[] rawMoveData = reader.GetRawBytes(rawStartPos, rawEndPos - rawStartPos);
                QueueLocalPlayerMovementAck(conn, sessionId, moveCount, rawMoveData);
                // If force relay active (clicked obelisk/world object), wait for the player
                // to move significantly, then send ONE clean walk-to and suppress.
                // First few 0x65 after click are near the start position — skip those.
                bool usedForceRelay = false;
                if (_forceRelayUntil.TryGetValue(conn.ConnId, out float relayDeadline) && Time.time < relayDeadline)
                {
                    _lastRelayPosX.TryGetValue(conn.LoginName, out float relayLastX);
                    _lastRelayPosY.TryGetValue(conn.LoginName, out float relayLastY);
                    float rdx = lastX - relayLastX;
                    float rdy = lastY - relayLastY;
                    float rDistSq = rdx * rdx + rdy * rdy;

                    if (rDistSq > 4.0f)  // Moved > 2 units — real pathfinding movement
                    {
                        _forceRelayUntil.Remove(conn.ConnId);
                        BroadcastWalkToPosition(conn, lastX, lastY);
                        usedForceRelay = true;
                        Debug.LogError($"[MP-WALK] Force-relay: walk-to ({lastX:F1}, {lastY:F1}) dist={Math.Sqrt(rDistSq):F1}");
                    }
                }
                if (!usedForceRelay)
                {
                    BroadcastPlayerMovement(conn, sessionId, moveCount, rawMoveData);
                }
            }
            catch (Exception ex)
            {
                Debug.LogError($"[MOVE] ERROR: {ex.Message}");
            }
        }

        private uint ResolveMonsterExperienceReward(Combat.Monster monster)
        {
            if (monster == null) return 0;
            double difficulty = monster.ExperienceDifficulty;
            if (difficulty <= 0d) return 0;
            int sourceLevel = Math.Max(1, (int)monster.Level);
            double reward = PlayerState.GetBaseXPForLevel(sourceLevel) * difficulty;
            if (reward < 1d) reward = 1d;
            if (reward >= uint.MaxValue) return uint.MaxValue;
            return (uint)Math.Round(reward, MidpointRounding.AwayFromZero);
        }

        private uint ResolveClientVisibleExperienceReward(RRConnection conn, Combat.Monster monster, PlayerState playerState, uint packetXP, uint sourceLevel)
        {
            if (monster == null || playerState == null || packetXP == 0) return 0;
            int playerLevel = Math.Max(1, playerState.Level);
            int nativeSourceLevel = Math.Max(1, (int)Math.Min(255u, sourceLevel));
            if (nativeSourceLevel <= playerLevel - 5)
                return 0;

            int effectiveLevel = Math.Min(nativeSourceLevel, playerLevel);
            long numerator = (long)(effectiveLevel << 8) << 8;
            int denominator = playerLevel << 8;
            int ratioF32 = denominator != 0 ? (int)(numerator / denominator) : 0;
            long xpF32 = ((long)packetXP * ratioF32) >> 8;

            bool isFree = conn != null && !string.IsNullOrEmpty(conn.LoginName) && IsPlayerFree(conn.LoginName);
            if (isFree)
            {
                float freePlayerXPMult = GCDatabase.Instance.GetKnob("FreePlayerExperienceMult", 0.87f);
                int freeMultF32 = (int)(freePlayerXPMult * 256.0f);
                xpF32 = (xpF32 * freeMultF32) >> 8;
            }

            long scaledXPBase = (xpF32 * 100L) >> 8;
            float experienceMod = GCDatabase.Instance.GetKnob("ExperienceMod", 5.0f);
            int experienceModPercent = (int)(experienceMod * 100.0f);
            long finalXP = scaledXPBase * experienceModPercent / 100L;

            if (finalXP <= 0) return 0;
            if (finalXP >= uint.MaxValue) return uint.MaxValue;
            uint result = (uint)finalXP;
            Debug.LogError($"[XP-NATIVE] monster={monster.Name}#{monster.EntityId} packetXP={packetXP} difficulty={monster.ExperienceDifficulty:F2} sourceLevel={nativeSourceLevel} playerLevel={playerLevel} effectiveLevel={effectiveLevel} ratioF32={ratioF32} free={isFree} xpF32={xpF32} effectiveXP={result}");
            return result;
        }

        private void QueueLocalPlayerMovementAck(RRConnection conn, byte sessionId, byte moveCount, byte[] rawMoveData)
        {
            if (moveCount == 0 || rawMoveData == null || rawMoveData.Length == 0) return;
            const int recordSize = 13;
            int rawCount = Math.Min(moveCount, rawMoveData.Length / recordSize);
            if (rawCount <= 0) return;
            int rawBytes = rawCount * recordSize;
            var normalized = new byte[rawBytes];
            Buffer.BlockCopy(rawMoveData, 0, normalized, 0, rawBytes);
            lock (conn)
            {
                if (conn.PendingLocalMoveSessionId == sessionId && conn.PendingLocalMoveCount > 0 && conn.PendingLocalMoveData != null && conn.PendingLocalMoveData.Length > 0)
                {
                    int pendingCount = Math.Min(conn.PendingLocalMoveCount, conn.PendingLocalMoveData.Length / recordSize);
                    int pendingBytes = pendingCount * recordSize;
                    var combined = new byte[pendingBytes + rawBytes];
                    Buffer.BlockCopy(conn.PendingLocalMoveData, 0, combined, 0, pendingBytes);
                    Buffer.BlockCopy(normalized, 0, combined, pendingBytes, rawBytes);
                    int combinedCount = combined.Length / recordSize;
                    int keepCount = Math.Min(255, combinedCount);
                    int keepBytes = keepCount * recordSize;
                    var kept = new byte[keepBytes];
                    Buffer.BlockCopy(combined, combined.Length - keepBytes, kept, 0, keepBytes);
                    conn.PendingLocalMoveData = kept;
                    conn.PendingLocalMoveCount = (byte)keepCount;
                }
                else
                {
                    conn.PendingLocalMoveSessionId = sessionId;
                    conn.PendingLocalMoveCount = (byte)Math.Min(255, rawCount);
                    conn.PendingLocalMoveData = normalized;
                }
                float due = Time.time + 0.008f;
                if (conn.PendingLocalMoveFlushAt <= 0f || conn.PendingLocalMoveFlushAt > due)
                {
                    conn.PendingLocalMoveFlushAt = due;
                }
            }
        }

        private static bool TryNormalizeUnitMoverUpdateData(byte moveCount, byte[] rawMoveData, out byte safeMoveCount, out byte[] safeMoveData)
        {
            const int recordSize = 13;
            safeMoveCount = 0;
            safeMoveData = Array.Empty<byte>();
            if (moveCount == 0 || rawMoveData == null || rawMoveData.Length == 0) return false;
            int availableCount = Math.Min(moveCount, rawMoveData.Length / recordSize);
            if (availableCount <= 0) return false;
            int safeBytes = availableCount * recordSize;
            safeMoveCount = (byte)availableCount;
            if (safeBytes == rawMoveData.Length)
            {
                safeMoveData = rawMoveData;
                return true;
            }
            safeMoveData = new byte[safeBytes];
            Buffer.BlockCopy(rawMoveData, 0, safeMoveData, 0, safeBytes);
            return true;
        }

        private bool TryWritePendingLocalPlayerMovementAck(RRConnection conn, LEWriter writer)
        {
            if (conn == null || !conn.IsConnected) return false;
            if (conn.UnitBehaviorId == 0) return false;
            byte sessionId;
            byte moveCount;
            byte[] rawMoveData;
            lock (conn)
            {
                if (conn.PendingLocalMoveCount == 0 || conn.PendingLocalMoveData == null || conn.PendingLocalMoveData.Length == 0) return false;
                if (Time.time < conn.PendingLocalMoveFlushAt) return false;
                sessionId = conn.PendingLocalMoveSessionId;
                moveCount = conn.PendingLocalMoveCount;
                rawMoveData = conn.PendingLocalMoveData;
            }
            if (!TryNormalizeUnitMoverUpdateData(moveCount, rawMoveData, out byte safeMoveCount, out byte[] safeMoveData))
                return false;
            if (safeMoveCount != moveCount || !ReferenceEquals(safeMoveData, rawMoveData))
                Debug.LogError($"[WORLD-MOVERACK] normalized session=0x{sessionId:X2} count={moveCount}->{safeMoveCount} raw={rawMoveData?.Length ?? 0}->{safeMoveData.Length}");
            var ackWriter = new LEWriter();
            ackWriter.WriteByte(0x35);
            ackWriter.WriteUInt16((ushort)conn.UnitBehaviorId);
            ackWriter.WriteByte(0x65);
            ackWriter.WriteByte(sessionId);
            ackWriter.WriteByte(safeMoveCount);
            ackWriter.WriteBytes(safeMoveData);
            if (!TryWritePlayerEntitySynch(conn, ackWriter, SyncContext.MoverAck, "WorldMoverAck", true, true))
                return false;
            lock (conn)
            {
                if (conn.PendingLocalMoveSessionId == sessionId && conn.PendingLocalMoveCount == moveCount && ReferenceEquals(conn.PendingLocalMoveData, rawMoveData))
                {
                    conn.PendingLocalMoveCount = 0;
                    conn.PendingLocalMoveData = Array.Empty<byte>();
                    conn.PendingLocalMoveFlushAt = 0f;
                }
            }
            writer.WriteBytes(ackWriter.ToArray());
            return true;
        }
        // HandlePlayerAttack removed 2026-05-27 (audit Phase 1). Dead — no callers anywhere.
        // The live player-attack handler is HandlePlayerAttackMonster (called from line ~12587
        // in the HandleComponentUpdate dispatch). The removed function emitted the now-deleted
        // BuildDamagePacket (opcode 0x28 → desync popup on 666 client).

        private void HandleComponentUpdate(RRConnection conn, LEReader reader)
        {
            try
            {
                if (reader.Remaining < 3)
                {
                    Debug.LogError($"[COMPONENT] ERROR: Not enough data! Remaining={reader.Remaining}");
                    return;
                }
                ushort componentId = reader.ReadUInt16();
                byte subMessage = reader.ReadByte();

                // ═══ DIAGNOSTIC: Log ALL component updates to find skill equip ═══
                if (VerbosePacketLogging && subMessage >= 0x30 && subMessage <= 0x3F)
                {
                    byte[] diagRaw = reader.PeekRemaining();
                    string diagHex = diagRaw.Length > 0 ? BitConverter.ToString(diagRaw) : "(empty)";
                    Debug.LogError($"[DIAG-0x3x] cid=0x{componentId:X4} sub=0x{subMessage:X2} remaining={diagRaw.Length} hex={diagHex}");
                }
                // --- 0x64: State Machine dispatch ---
                if (subMessage == 0x64)
                {
                    // Monster state machine (cid 50000-60000)
                    if (componentId >= 50000 && componentId < 60000)
                    {
                        HandleMonsterStateMachineUpdate(conn, reader, componentId);
                        return;
                    }

                    // Player state machine
                    // Player state machine — binary-verified flag format from 0x5F0C70
                    if (reader.Remaining >= 1)
                    {
                        byte flags = reader.ReadByte();
                        ushort messageType = 0xFFFF;
                        ushort scope = 0xFFFF;
                        ushort target = 0;
                        uint value = 0;

                        // bit 1 (0x02): uint16 messageType
                        if ((flags & 0x02) != 0 && reader.Remaining >= 2)
                            messageType = reader.ReadUInt16();
                        // bit 2 (0x04): uint16 scope
                        if ((flags & 0x04) != 0 && reader.Remaining >= 2)
                            scope = reader.ReadUInt16();
                        // bit 3 (0x08): uint16 target
                        if ((flags & 0x08) != 0 && reader.Remaining >= 2)
                            target = reader.ReadUInt16();
                        // bit 5 (0x20): uint32 value
                        if ((flags & 0x20) != 0 && reader.Remaining >= 4)
                            value = reader.ReadUInt32();
                        // bit 4 (0x10): watcher list
                        if ((flags & 0x10) != 0 && reader.Remaining >= 2)
                        {
                            ushort wCount = reader.ReadUInt16();
                            for (int w = 0; w < wCount && reader.Remaining >= 2; w++)
                                reader.ReadUInt16();
                        }

                        // Consume sync suffix
                        if (reader.Remaining >= 1)
                        {
                            byte syncFlags = reader.ReadByte();
                            if ((syncFlags & 0x02) != 0 && reader.Remaining >= 4)
                            {
                                uint syncHP = reader.ReadUInt32();
                                ObserveClientPlayerHP(conn, syncHP, "PLAYER-STATE-SYNC");
                            }
                        }

                        if (VerbosePacketLogging) Debug.LogError($"[PLAYER-STATE] cid={componentId} flags=0x{flags:X2} type={messageType} value={value}");

                        // Type 0x1C (28) = LEVEL UP CONFIRMATION from client's Avatar::OnLevelUp
                        // Server XP is authoritative — 0x1C is just the client confirming it processed
                        // the level-up locally. Do NOT reinitialize stats or reset XP here.
                        if (messageType == 0x1C)
                        {
                            var playerState = GetPlayerState(conn.ConnId.ToString());
                            if (playerState != null)
                            {
                                Debug.LogError($"[LEVEL-UP-0x1C] Client confirms level-up. Server level={playerState.Level} XP={playerState.Experience}");
                            }
                        }
                    }
                    return;
                }

                if (subMessage == 0x65)
                {
                    if (componentId >= 50000 && componentId < 60000)
                    {
                        try
                        {
                            if (reader.Remaining > 0)
                            {
                                byte[] rawPeek = reader.PeekRemaining();
                                if (VerbosePacketLogging) Debug.LogError($"[MONSTER-0x65] cid={componentId} remaining={reader.Remaining} raw={BitConverter.ToString(rawPeek)}");
                            }

                            var monster = CombatManager.Instance.GetMonsterByComponent(componentId);
                            int componentOffset = CombatManager.Instance.GetComponentOffset(componentId);
                            if (monster != null && componentOffset == 1 && reader.Remaining >= 2)
                            {
                                byte sessionId = reader.ReadByte();
                                byte moveCount = reader.ReadByte();
                                int applied = 0;
                                for (int i = 0; i < moveCount && reader.Remaining >= 13; i++)
                                {
                                    byte moveFlags = reader.ReadByte();
                                    int headingRaw = reader.ReadInt32();
                                    int posXRaw = reader.ReadInt32();
                                    int posYRaw = reader.ReadInt32();
                                    monster.SessionId = sessionId;
                                    monster.Heading = headingRaw / 256f;
                                    monster.PosX = posXRaw / 256f;
                                    monster.PosY = posYRaw / 256f;
                                    if (monster.EntityId <= ushort.MaxValue)
                                        _allEntityPositions[(ushort)monster.EntityId] = (monster.PosX, monster.PosY, monster.PosZ);
                                    applied++;
                                    if (VerbosePacketLogging) Debug.LogError($"[MONSTER-MOVE-0x65] {monster.Name} cid={componentId} flags=0x{moveFlags:X2} session={sessionId} pos=({monster.PosX:F1},{monster.PosY:F1}) heading={monster.Heading:F1}");
                                }
                                if (applied != moveCount)
                                    Debug.LogError($"[MONSTER-MOVE-0x65] {monster.Name} cid={componentId} expected={moveCount} applied={applied} remaining={reader.Remaining}");
                            }

                            if (reader.Remaining >= 1)
                            {
                                byte syncFlags = reader.ReadByte();
                                if (VerbosePacketLogging) Debug.LogError($"[MONSTER-0x65] cid={componentId} offset={componentOffset} syncFlags=0x{syncFlags:X2}");

                                if ((syncFlags & 0x02) != 0 && reader.Remaining >= 4)
                                {
                                    uint clientHP = reader.ReadUInt32();
                                    int clientActual = (int)(clientHP / 256);
                                    if (monster != null)
                                    {
                                        int serverActual = (int)(CombatManager.Instance.PeekMonsterCurrentHPWire(monster) / 256);
                                        if (VerbosePacketLogging) Debug.LogError($"[MONSTER-0x65] {monster.Name} (eid={monster.EntityId}) CLIENT_HP={clientActual} SERVER_HP={serverActual} DELTA={serverActual - clientActual}");

                                        CombatManager.Instance.ObserveClientMonsterHP(monster, clientHP, "MONSTER-MOVE-HP-0x65");
                                    }
                                    else
                                    {
                                        if (VerbosePacketLogging) Debug.LogError($"[MONSTER-0x65] WARNING: cid={componentId} not found in CombatManager!");
                                    }
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            Debug.LogError($"[MONSTER-0x65] Parse error: {ex.Message}");
                        }
                        return;
                    }

                    HandleClientMove(conn, reader, componentId);
                    return;  // Don't fall through to other handlers
                }
                else if (subMessage == 0x02)
                {
                    if (componentId == conn.QuestManagerId || componentId == 0x0018)
                    {
                        Debug.LogError($"[QUEST-0x02] CLOSE/CANCEL - clearing pending state");
                        // CLEAR pending state, DO NOT accept!
                        conn.PendingQuestHash = 0;
                        conn.PendingQuestNpcEntityId = 0;
                        conn.ViewingQuestInstanceId = 0;
                    }
                }
                // In 0x03 handler:
                // subMessage 0x03 = ABANDON QUEST (from quest log panel)
                // In 0x03 handler:
                else if (subMessage == 0x03)
                {
                    // ROOT CAUSE FIX: must match conn.QuestManagerId (typically 0x0210),
                    // not the hardcoded 0x0018. The actual quest manager component id is
                    // assigned per-session at SendPlayerEntitySpawn time. With the old
                    // hardcoded check, every abandon click fell through to HandleCancelAction
                    // which read the first byte of the instanceId as a "sessionId" and sent
                    // back a malformed 0x35 response. The client's processUpdateQuest then
                    // misinterpreted the response bytes as instanceId+questSubmsg+leftovers,
                    // and the sync trailer reader picked up a byte from GetSynchValue()'s
                    // u32 as the sync flag - if that byte was 0x01 the validator crashed
                    // with "Entity synch error" because the player avatar entity expects
                    // either flag 0x00 or 0x02, never 0x01.
                    if (componentId == 0x0018 || componentId == conn.QuestManagerId)
                    {
                        // QUEST ABANDON.
                        // Wire format from binary RE: client abandon() at 0x5c06c0 writes
                        // exactly 4 bytes (u32 instanceId) and calls sendRequest with type
                        // 0x03. The server receives [opcode 0x35][cid:u16][submsg:u8 = 0x03]
                        // [instanceId:u32]. We respond with SendRemovePacket which writes
                        // submsg 0x02 (= processRemoveQuest in client dispatch table at
                        // 0x5c3630). The client's processRemoveQuest at 0x5c3970 reads u32
                        // instanceId, calls findQuestByInstanceId at 0x5c11b0, and removes
                        // the quest from the local quest log.
                        try
                        {
                            uint instanceId = reader.ReadUInt32();
                            Debug.LogError($"[QUEST-ABANDON] cid=0x{componentId:X4} instanceId=0x{instanceId:X8}");

                            // Drain any trailing bytes (binary RE shows client always sends
                            // exactly 4, but be defensive).
                            while (reader.Remaining > 0)
                            {
                                byte trail = reader.ReadByte();
                                Debug.LogError($"[QUEST-ABANDON] drained trailing byte 0x{trail:X2}");
                            }

                            // Remove from server-side active quest list.
                            var playerState = QuestManager.Instance.GetPlayerState(conn.ConnId.ToString());
                            if (playerState != null)
                            {
                                var abandoned = playerState.ActiveQuests.FirstOrDefault(q => q.InstanceId == instanceId);
                                if (abandoned != null)
                                {
                                    playerState.ActiveQuests.Remove(abandoned);
                                    Debug.LogError($"[QUEST-ABANDON] Removed {abandoned.QuestId} from server-side active list");
                                }
                                else
                                {
                                    Debug.LogError($"[QUEST-ABANDON] WARNING: instanceId 0x{instanceId:X8} not found in active list");
                                }
                            }

                            // Tell the client to remove the quest from its local quest log.
                            QuestManager.Instance.SendRemovePacket(conn, instanceId);

                            // Persist so the abandon survives zone transitions.
                            SavePlayerQuests(conn);

                            Debug.LogError($"[QUEST-ABANDON] complete");
                        }
                        catch (Exception ex)
                        {
                            Debug.LogError($"[QUEST-ABANDON] EXCEPTION: {ex.GetType().Name}: {ex.Message}\n{ex.StackTrace}");
                        }
                    }
                    else
                    {
                        Debug.LogError($"[COMPONENT] 0x03 from componentId={componentId} - not quest");
                        HandleCancelAction(conn, reader, componentId);
                    }
                }
                else if (subMessage == 0x05)
                {
                    if (componentId == conn.QuestManagerId)
                    {
                        // 0x05 is sent for BOTH Accept AND Complete Quest clicks
                        if (conn.PendingTurnInInstanceId != 0)
                        {
                            // TURN-IN: client clicked "Complete Quest" — complete() sends submsg 0x05
                            Debug.LogError($"[QUEST-TURNIN] 0x05 = COMPLETE QUEST! InstanceId={conn.PendingTurnInInstanceId}");
                            uint instanceId = conn.PendingTurnInInstanceId;
                            conn.PendingTurnInInstanceId = 0;

                            var completingQuest = QuestManager.Instance.GetQuestByInstanceId(conn.ConnId.ToString(), instanceId);
                            QuestData completedQuestData = null;
                            if (completingQuest != null)
                                completedQuestData = DatabaseLoader.Quests
                                    .FirstOrDefault(q => q.id.Equals(completingQuest.QuestId, StringComparison.OrdinalIgnoreCase));

                            RemoveQuestItemsFromInventory(conn, completingQuest);
                            QuestManager.Instance.HandleTurnInConfirmed(conn, instanceId);
                            SavePlayerQuests(conn);

                            // Apply quest rewards using GC formulas (gold/XP/King's Coins/XP buff)
                            ApplyQuestRewards(conn, completedQuestData);
                        }
                        else
                        {
                            // ACCEPT: client clicked "Accept" on quest offer
                            Debug.LogError($"[QUEST] 📨 Received submessage 0x05 (Accept Button)");
                            uint npcEntityId = reader.ReadUInt32();
                            byte gcTypeIndicator = reader.ReadByte();
                            uint questHash = reader.ReadUInt32();
                            Debug.LogError($"[QUEST-ACCEPT] NPC={npcEntityId}, Hash=0x{questHash:X8}");
                            QuestManager.Instance.HandleAcceptConfirmed(conn, npcEntityId, questHash);
                            // Give onAcceptItem if quest has one
                            if (DatabaseLoader.QuestsByHash.TryGetValue(questHash, out var acceptedQuest1) && !string.IsNullOrEmpty(acceptedQuest1.onAcceptItem))
                                GiveOnAcceptItem(conn, acceptedQuest1.onAcceptItem);
                            TryAutoCompleteWishingWellQuest(conn, questHash);
                        }
                    }
                }
                else if (subMessage == 0x06)
                {
                    if (componentId == conn.QuestManagerId)
                    {
                        uint npcEntityId = reader.ReadUInt32();
                        byte gcTypeIndicator = reader.ReadByte();
                        uint questHash = reader.ReadUInt32();
                        Debug.LogError($"[QUEST] NPC={npcEntityId}, Hash=0x{questHash:X8}, Pending=0x{conn.PendingQuestHash:X8}");

                        if (conn.PendingQuestHash == questHash)
                        {
                            // Second 0x06 with same hash = Accept clicked
                            Debug.LogError($"[QUEST] ✅ ACCEPTING QUEST");
                            conn.PendingQuestHash = 0;
                            QuestManager.Instance.HandleAcceptConfirmed(conn, npcEntityId, questHash);
                            if (DatabaseLoader.QuestsByHash.TryGetValue(questHash, out var acceptedQuest2) && !string.IsNullOrEmpty(acceptedQuest2.onAcceptItem))
                                GiveOnAcceptItem(conn, acceptedQuest2.onAcceptItem);
                            TryAutoCompleteWishingWellQuest(conn, questHash);
                        }
                        else
                        {
                            // First 0x06 = show dialog
                            Debug.LogError($"[QUEST] 📋 SHOWING DIALOG");
                            conn.PendingQuestHash = questHash;
                            conn.PendingQuestNpcEntityId = npcEntityId;
                            QuestManager.Instance.SendQueryResponse(conn, questHash, npcEntityId);
                        }
                    }
                }

                // subMessage 0x04 = VIEW QUEST from quest log (just clicking, not abandoning)
                // subMessage 0x04 = TURN-IN or VIEW quest (clicking yellow ? OR viewing from quest log)
                else if (subMessage == 0x04)
                {
                    if (componentId == conn.QuestManagerId || componentId == 0x0018)
                    {
                        uint instanceId = reader.ReadUInt32();
                        Debug.LogError($"[QUEST-0x04] instanceId={instanceId} - checking if turn-in...");

                        var playerState = QuestManager.Instance.GetPlayerState(conn.ConnId.ToString());
                        var activeQuest = playerState?.ActiveQuests.FirstOrDefault(q => q.InstanceId == instanceId);

                        if (activeQuest != null)
                        {
                            var objectives = activeQuest.Objectives ?? new System.Collections.Generic.List<DungeonRunners.Managers.QuestProgress>();
                            bool allComplete = objectives.Count > 0 && objectives.All(o => o.IsComplete);
                            Debug.LogError($"[QUEST-0x04] Found quest {activeQuest.QuestId}, allComplete={allComplete}");

                            if (allComplete)
                            {
                                Debug.LogError($"[QUEST-0x04] 🎯 SENDING TURN-IN DIALOG for instanceId={instanceId}");
                                QuestManager.Instance.SendTurnInDialog(conn, instanceId);
                            }
                            else
                            {
                                Debug.LogError($"[QUEST-0x04] Quest not complete yet, just viewing");
                            }
                        }
                        else
                        {
                            Debug.LogError($"[QUEST-0x04] No active quest with instanceId={instanceId}");
                        }
                    }
                }
                else if (subMessage == 0x0A)
                {
                    if (componentId == conn.QuestManagerId || componentId == 0x0018)
                    {
                        Debug.LogError($"[QUEST-0x0A] TOWN PORTAL USE from obelisk!");
                        if (conn.HasSavedTownPortal)
                        {
                            Debug.LogError($"[QUEST-0x0A] Teleporting to {conn.TownPortalZoneName} at ({conn.TownPortalPosX:F1}, {conn.TownPortalPosY:F1})");
                            ChangeZoneToPosition(conn, conn.TownPortalZoneName,
                                conn.TownPortalPosX, conn.TownPortalPosY, conn.TownPortalPosZ);
                            // Don't clear HasSavedTownPortal here — SpawnReturnTownPortal needs it on zone-in
                        }
                        else
                        {
                            Debug.LogError($"[QUEST-0x0A] No saved town portal!");
                        }
                    }
                }
                else if (subMessage == 0x01)
                {
                    // QUEST ACCEPT: 0x01 with empty payload from QuestManager (0x0018)
                    if ((componentId == conn.QuestManagerId || componentId == 0x0018) && reader.Remaining == 0)
                    {
                        if (conn.PendingQuestHash != 0)
                        {
                            Debug.LogError($"[QUEST-ACCEPT] 0x01 empty = ACCEPT! Hash=0x{conn.PendingQuestHash:X8}");
                            uint questHash = conn.PendingQuestHash;
                            uint npcEntityId = conn.PendingQuestNpcEntityId;
                            conn.PendingQuestHash = 0;
                            conn.PendingQuestNpcEntityId = 0;
                            QuestManager.Instance.HandleAcceptConfirmed(conn, npcEntityId, questHash);
                            if (DatabaseLoader.QuestsByHash.TryGetValue(questHash, out var acceptedQuest3) && !string.IsNullOrEmpty(acceptedQuest3.onAcceptItem))
                                GiveOnAcceptItem(conn, acceptedQuest3.onAcceptItem);
                            TryAutoCompleteWishingWellQuest(conn, questHash);
                            SavePlayerQuests(conn);
                        }
                        else if (conn.PendingTurnInInstanceId != 0)
                        {
                            Debug.LogError($"[QUEST-TURNIN] 0x01 empty = COMPLETE! InstanceId={conn.PendingTurnInInstanceId}");
                            uint instanceId = conn.PendingTurnInInstanceId;
                            conn.PendingTurnInInstanceId = 0;

                            // Get quest data BEFORE completing so we can award rewards
                            var completingQuest = QuestManager.Instance.GetQuestByInstanceId(conn.ConnId.ToString(), instanceId);
                            QuestData completedQuestData = null;
                            if (completingQuest != null)
                                completedQuestData = DatabaseLoader.Quests
                                    .FirstOrDefault(q => q.id.Equals(completingQuest.QuestId, StringComparison.OrdinalIgnoreCase));

                            RemoveQuestItemsFromInventory(conn, completingQuest);
                            QuestManager.Instance.HandleTurnInConfirmed(conn, instanceId);
                            SavePlayerQuests(conn);

                            // Apply quest rewards using GC formulas (gold/XP/King's Coins/XP buff)
                            ApplyQuestRewards(conn, completedQuestData);
                        }
                        else
                        {
                            Debug.LogError($"[QUEST-0x01] Empty but no pending quest - viewing quest");
                            conn.ViewingQuestInstanceId = 1;
                        }
                        return;
                    }
                    Debug.LogError($"[SUBMSG-0x01] PASSED QUEST CHECK - about to read action! remaining={reader.Remaining}");

                    // 🔥 ACTIVATE ACTION (NPC or Item Pickup)
                    byte responseId = reader.ReadByte();
                    Debug.LogError($"[ACTION-READ] responseId={responseId}, remaining={reader.Remaining}");

                    byte actionType = reader.ReadByte();
                    Debug.LogError($"[ACTION-READ] actionType=0x{actionType:X2}, remaining={reader.Remaining}");

                    // ── 0x52 SELF-CAST SPELLS (Gaseous Blast, buffs) ──
                    // 0x52 self-cast only has 2 bytes remaining: sessionID(1) + slotID(1)
                    // Must intercept BEFORE the uint16 read which would underflow/throw
                    // Checkpoint 0x52 has more bytes (targetEntityID + gcType string) so falls through
                    if (actionType == 0x52 && reader.Remaining <= 2)
                    {
                        byte spellSessionID = reader.Remaining >= 1 ? reader.ReadByte() : (byte)0;
                        byte slotID = reader.Remaining >= 1 ? reader.ReadByte() : (byte)0;
                        Debug.LogError($"[SPELL-0x52] ═══ SELF-CAST! sessionID={spellSessionID}, slotID={slotID}, componentId={componentId}, remaining={reader.Remaining}");
                        if (conn.HasActiveUseTarget)
                            ClearUseTargetAndReleaseControl(conn, "ACTION-0x52", componentId);

                        // Response: Rainbow format via MessageQueue (same delivery as 0x51)
                        var msg52 = new LEWriter();
                        msg52.WriteByte(0x35);              // ComponentUpdate
                        msg52.WriteUInt16(componentId);
                        msg52.WriteByte(0x01);              // ActionResponse
                        msg52.WriteByte(responseId);
                        msg52.WriteByte(0x52);              // BehaviourActionUse
                        msg52.WriteByte(spellSessionID);    // sessionID
                        msg52.WriteByte(slotID);            // echo slotID back
                        if (!TryWriteEntitySynchForComponent(conn, msg52, componentId, 0x01, SyncContext.PlayerActionResponse, "PlayerActionResponse", false))
                        {
                            Debug.LogError($"[SPELL-0x52] failed ActionResponse sync: component={componentId} slot={slotID}");
                            return;
                        }
                        ClearZoneSpawnInvulnerability(conn, $"ACTION-0x{actionType:X2}");
                        conn.MessageQueue.Enqueue(msg52.ToArray());
                        Debug.LogError($"[SPELL-0x52] <<< Sent ActionResponse via MessageQueue");

                        // MULTIPLAYER: Relay self-cast animation to other players
                        BroadcastSelfCast(conn, responseId, spellSessionID, slotID);

                        // Server-side: mana cost + AoE damage to nearby monsters
                        if (componentId < 50000)
                        {
                            PlayerState state52 = GetPlayerState(conn.ConnId.ToString());
                            if (state52 != null)
                            {
                                HandleSelfCastSpell(conn, state52, slotID, componentId);
                            }
                        }
                        // All bytes consumed — no sync suffix to read
                        return;
                    }

                    byte sessionID = reader.ReadByte();
                    Debug.LogError($"[ACTION-READ] sessionID={sessionID}, remaining={reader.Remaining}");

                    ushort targetEntityID = reader.ReadUInt16();
                    Debug.LogError($"[ACTION-READ] targetEntityID={targetEntityID}, remaining={reader.Remaining}");

                    // 🔥 LOG ALL ACTION TYPES TO SEE WHAT CLIENT SENDS
                    Debug.LogError($"[ACTION] ActionType=0x{actionType:X2}, ResponseId={responseId}, SessionID={sessionID}, Target={targetEntityID}");
                    if (actionType != 0x50 && conn.HasActiveUseTarget)
                        ClearUseTargetAndReleaseControl(conn, $"ACTION-0x{actionType:X2}", componentId);

                    if (actionType == 0x06) // BehaviourActionActivate (left-click)
                                            // ... rest of your existing code continues here
                    {
                        // MULTIPLAYER: Broadcast walk-to-target for other players.
                        // Do NOT update conn.PlayerPosX/Y here — that field is only
                        // updated from actual movement packets (HandleClientMove).
                        // Overwriting it with the target's position would cause the
                        // tick to echo the wrong position back to the player → screen snap.
                        bool broadcastSent = false;
                        if (_npcPositions.TryGetValue(targetEntityID, out var npcPos))
                        {
                            BroadcastWalkToPosition(conn, npcPos.X, npcPos.Y);
                            broadcastSent = true;
                        }
                        else if (_portalEntities.TryGetValue(targetEntityID, out var portal2))
                        {
                            BroadcastWalkToPosition(conn, portal2.PosX, portal2.PosY);
                            broadcastSent = true;
                        }
                        else if (_checkpointEntities.TryGetValue(targetEntityID, out var cp))
                        {
                            BroadcastWalkToPosition(conn, cp.PosX, cp.PosY);
                            broadcastSent = true;
                        }

                        // Fallback for ANY unknown entity (obelisks, quest objects, etc.)
                        // Use tracked entity position if available
                        if (!broadcastSent && targetEntityID != 0)
                        {
                            if (_allEntityPositions.TryGetValue(targetEntityID, out var entityPos))
                            {
                                Debug.LogError($"[MP-WALK] Entity {targetEntityID} found in position tracker at ({entityPos.X}, {entityPos.Y})");
                                BroadcastWalkToPosition(conn, entityPos.X, entityPos.Y);
                            }
                            else
                            {
                                // Unknown entity — broadcast current player position as walk start
                                Debug.LogError($"[MP-WALK] Unknown entity {targetEntityID} — broadcasting current pos + enabling force-relay");
                                BroadcastWalkToPosition(conn, conn.PlayerPosX, conn.PlayerPosY);
                                _forceRelayUntil[conn.ConnId] = Time.time + 3.0f;
                            }
                        }

                        // Dropped item pickup -> straight to inventory bag.
                        // The DR client sends the same actionType 0x06 with no modifier flag
                        // regardless of which mouse button or modifier key is held (verified
                        // from server packet diagnostics: every click had identical bytes,
                        // remaining=0, no shift state in the wire format). So we just route
                        // every dropped-item click through the auto-bag handler. If the bag
                        // is full it falls back to HandleItemPickup (cursor) automatically.
                        if (IsDroppedItem(targetEntityID))
                        {
                            Debug.LogError($"[PICKUP] Player clicked dropped item, auto-bagging. Target={targetEntityID}");
                            HandleItemRightClickPickup(conn, componentId, targetEntityID, responseId, sessionID);
                        }
                        // Check if this is a portal
                        else if (IsPortal(targetEntityID, out var portal))
                        {
                            Debug.LogError($"[PORTAL] Player clicked portal! Target={targetEntityID} → {portal.TargetZone}");
                            HandlePortalActivation(conn, componentId, targetEntityID, responseId, sessionID, portal);
                        }
                        // Check if this is a treasure chest
                        else if (IsChest(targetEntityID, out var chestData))
                        {
                            Debug.LogError($"[CHEST] Player clicked chest! Target={targetEntityID} ({chestData.Label})");
                            HandleChestActivation(conn, componentId, targetEntityID, responseId, sessionID, chestData);
                        }
                        // Check if this is a checkpoint
                        else if (IsCheckpoint(targetEntityID, out var checkpoint))
                        {
                            Debug.LogError($"[CHECKPOINT] Player clicked checkpoint! Target={targetEntityID}");
                            HandleCheckpointActivation(conn, componentId, targetEntityID, responseId, sessionID, checkpoint);
                        }
                        // Check if this is a world entity (teleporter, shrine, gate, etc)
                        else if (WorldEntitySpawner.Instance.TryGetEntity(targetEntityID, out var weData))
                        {
                            Debug.LogError($"[WORLD-ENTITY] Player clicked {weData.EntityType}: {weData.Label} (id=0x{targetEntityID:X4})");
                            if (weData.IsTeleporter)
                            {
                                HandleTeleporterActivation(conn, componentId, targetEntityID, responseId, sessionID, weData);
                            }
                            else if (weData.IsGate)
                            {
                                // Boss gates only open on boss kill — block manual click
                                // ACK the behavior action (unfreezes player WASD)
                                var ackMsg = new LEWriter();
                                ackMsg.WriteByte(0x35);
                                ackMsg.WriteUInt16(componentId);
                                ackMsg.WriteByte(0x01);
                                ackMsg.WriteByte(responseId);
                                ackMsg.WriteByte(0x06);
                                ackMsg.WriteByte(sessionID);
                                ackMsg.WriteUInt16(targetEntityID);
                                WritePlayerEntitySynch(conn, ackMsg);
                                conn.MessageQueue.Enqueue(ackMsg.ToArray());

                                SendSystemMessage(conn, "The gate is sealed. Defeat the boss to open it.");
                                Debug.LogError($"[WORLD-ENTITY] Gate click BLOCKED — boss must be killed first: {weData.Label}");
                            }
                            else
                            {
                                // ACK the behavior action first (unfreezes player WASD)
                                var ackMsg = new LEWriter();
                                ackMsg.WriteByte(0x35);
                                ackMsg.WriteUInt16(componentId);
                                ackMsg.WriteByte(0x01);
                                ackMsg.WriteByte(responseId);
                                ackMsg.WriteByte(0x06);
                                ackMsg.WriteByte(sessionID);
                                ackMsg.WriteUInt16(targetEntityID);
                                WritePlayerEntitySynch(conn, ackMsg);
                                conn.MessageQueue.Enqueue(ackMsg.ToArray());

                                // NCI::processUpdate type 0x0A = activate
                                var nciMsg = new LEWriter();
                                nciMsg.WriteByte(0x03);               // processEntityUpdate
                                nciMsg.WriteUInt16(targetEntityID);    // entityId
                                nciMsg.WriteByte(0x0A);               // NCI activate
                                nciMsg.WriteUInt32(0x00000000);       // activation data (counter)
                                WriteNonCombatInteractiveEntitySynchInfo(nciMsg, weData.GCType);
                                conn.MessageQueue.Enqueue(nciMsg.ToArray());
                                Debug.LogError($"[WORLD-ENTITY] Sent NCI activate (0x03/0x0A) for {weData.EntityType}: {weData.Label}");

                                // ═══ PORTRAIT QUEST HOOK — Q02_a2 "Suspicious portrait" ═══
                                // The Rattle Tooth quest Q02_a2 has two objectives:
                                //   MainObjective1: kill Rattle Tooth (works)
                                //   MainObjective2: "Suspicious portrait" (item type,
                                //     target=QuestItemPAL2.D00_Q02_a2_01) — the
                                //     tracker shows it but clicking the portrait
                                //     never ticked it because the generic NCI
                                //     click handler only sends the activate
                                //     response and returns.
                                //
                                // The portrait entity in dungeon00_level03_boss is
                                // registered in zone_world_entities as:
                                //   name='NCIPortrait'
                                //   gc_type='world.dungeon00.npc.NCIPortrait'
                                //   entity_type='npc'
                                //
                                // Fix: detect the portrait by gc_type suffix and
                                // call OnItemPickedUp with the quest-item target.
                                // OnItemPickedUp runs through QuestManager's normal
                                // item-objective match (type='item' + target match)
                                // and fires SendProgressPacket, which is what
                                // updates the on-screen tracker. No DB changes,
                                // no .gc changes, no client modifications.
                                try
                                {
                                    if (!string.IsNullOrEmpty(weData.GCType) &&
                                        weData.GCType.IndexOf("NCIPortrait", StringComparison.OrdinalIgnoreCase) >= 0)
                                    {
                                        Debug.LogError($"[QUEST] Portrait clicked ({weData.GCType}) — ticking Q02_a2 'Suspicious portrait' objective");
                                        var _portraitUpdates = QuestManager.Instance.OnItemPickedUp(conn, "QuestItemPAL2.D00_Q02_a2_01");
                                        if (_portraitUpdates != null && _portraitUpdates.Count > 0)
                                        {
                                            foreach (var _pu in _portraitUpdates)
                                                Debug.LogError($"[QUEST] Portrait tick: quest={_pu.QuestId} objective={_pu.ObjectiveName} now {_pu.Current}/{_pu.Required}");
                                        }
                                        else
                                        {
                                            Debug.LogError($"[QUEST] Portrait click produced no objective updates — either Q02_a2 not active or objective already complete");
                                        }
                                    }
                                }
                                catch (Exception _portraitEx)
                                {
                                    Debug.LogError($"[QUEST] Portrait quest hook failed (non-fatal): {_portraitEx.Message}");
                                }

                                // ═══ HERMIT LOCKBOX QUEST HOOK — Q03_a1 "The Hermit's Hoop" ═══
                                // When player clicks Entity_HermitLockbox, drop HermitRing quest item.
                                // GC: ActivateDropTrigger → EntityType=world.dungeon00.data.Entity_HermitLockbox,
                                //     Chance=100, Item=QuestItemPAL2.D00_Q03_a1_01
                                try
                                {
                                    if (!string.IsNullOrEmpty(weData.Name) &&
                                        weData.Name.Equals("HermitLockbox", StringComparison.OrdinalIgnoreCase))
                                    {
                                        Debug.LogError($"[QUEST] Hermit Lockbox clicked ({weData.GCType}) — dropping HermitRing on ground");
                                        var hermitItem = new GCObject
                                        {
                                            GCClass = "QuestItemPAL2.D00_Q03_a1_01",
                                            NativeClass = "Item",
                                            StoredLevel = 1
                                        };
                                        float hpx = weData.PosX + (float)(_lootRng.NextDouble() * 4.0 - 2.0);
                                        float hpy = weData.PosY + (float)(_lootRng.NextDouble() * 4.0 - 2.0);
                                        ushort hermitEid = GetNextLootEntityId();
                                        TrackDroppedItem(hermitEid, hermitItem, conn);
                                        if (_droppedItems.TryGetValue(hermitEid, out var hermitInfo))
                                        {
                                            hermitInfo.PosX = hpx;
                                            hermitInfo.PosY = hpy;
                                            hermitInfo.PosZ = weData.PosZ;
                                            hermitInfo.PlayerLevel = 1;
                                            hermitInfo.IsQuestItem = true;
                                        }
                                        SendDroppedItemSpawnPacket(conn, hermitEid, _droppedItems[hermitEid]);
                                    }
                                }
                                catch (Exception _hermitEx)
                                {
                                    Debug.LogError($"[QUEST] Hermit Lockbox hook failed (non-fatal): {_hermitEx.Message}");
                                }

                                // For chests, generate loot
                                if (weData.EntityType == "chest" || weData.EntityType == "boss_chest")
                                {
                                    PlayerState chestPS = GetPlayerState(conn.ConnId.ToString());
                                    int chestLevel = chestPS?.Level ?? 1;
                                    string chestGen = !string.IsNullOrEmpty(weData.ItemGenerator) ? weData.ItemGenerator : "TreasureChestIG";
                                    int chestCount = weData.ItemCount > 0 ? weData.ItemCount : 2;
                                    string chestGen2 = weData.ItemGenerator2;
                                    int chestCount2 = weData.ItemCount2;
                                    var chestDrops = LootManager.Instance.GenerateChestLoot(chestGen, chestCount, chestLevel);
                                    if (!string.IsNullOrEmpty(chestGen2) && chestCount2 > 0)
                                        chestDrops.AddRange(LootManager.Instance.GenerateChestLoot(chestGen2, chestCount2, chestLevel));
                                    Debug.LogError($"[CHEST-WE] {weData.Label}: {chestGen} x{chestCount} → {chestDrops.Count} drops");
                                    foreach (var drop in chestDrops)
                                    {
                                        if (drop.IsGold)
                                        {
                                            Debug.LogError($"[CHEST-WE] +{drop.GoldAmount} gold from {weData.Label}");
                                        }
                                        else
                                        {
                                            if (string.IsNullOrEmpty(drop.GCType)) { Debug.LogError("[CHEST-WE] ⚠️ Skipping null GCType"); continue; }
                                            string _gcWELower = drop.GCType.ToLowerInvariant();
                                            string _weNative = "Armor";
                                            if (_gcWELower.Contains("crossbow") || _gcWELower.Contains("bow") || _gcWELower.Contains("gun") || _gcWELower.Contains("cannon") || _gcWELower.Contains("ranged"))
                                                _weNative = "RangedWeapon";
                                            else if (_gcWELower.Contains("sword") || _gcWELower.Contains("axe") || _gcWELower.Contains("mace") || _gcWELower.Contains("pick") || _gcWELower.Contains("staff") || _gcWELower.Contains("club") || _gcWELower.Contains("katana") || _gcWELower.Contains("polearm") || _gcWELower.Contains("melee"))
                                                _weNative = "MeleeWeapon";
                                            var item = new GCObject { GCClass = drop.GCType, NativeClass = _weNative, PresetScaleMod = drop.ScaleMod, StoredRarity = (int)drop.Rarity, StoredLevel = drop.ItemLevel };
                                            float lpx = weData.PosX + (float)(_lootRng.NextDouble() * 8.0 - 4.0);
                                            float lpy = weData.PosY + (float)(_lootRng.NextDouble() * 8.0 - 4.0);
                                            ushort lootId = GetNextLootEntityId();
                                            TrackDroppedItem(lootId, item, conn);
                                            if (_droppedItems.TryGetValue(lootId, out var lInfo)) { lInfo.PosX = lpx; lInfo.PosY = lpy; lInfo.PosZ = weData.PosZ; lInfo.PlayerLevel = chestLevel; }
                                            SendDroppedItemSpawnPacket(conn, lootId, _droppedItems[lootId]);
                                            Debug.LogError($"[CHEST-WE] ★ {drop.Label} ({drop.Rarity}) from {weData.Label}");
                                        }
                                    }
                                }
                            }
                        }
                        else
                        {
                            Debug.LogError($"[NPC] Player clicked NPC! Target={targetEntityID}");
                            HandleNPCClick(conn, componentId, targetEntityID, responseId, sessionID);
                        }
                    }
                    else if (actionType == 0x52) // BehaviourActionUse (checkpoint teleport)
                    {
                        Debug.LogError($"[ACTION] 🎯 CHECKPOINT USE (0x52)! Target={targetEntityID}");
                        HandleCheckpointUse(conn, componentId, responseId, sessionID, reader);
                    }
                    else if (actionType == 0xA0) // BehaviourActionRetrieveItem - never observed in logs, kept as no-op for safety
                    {
                        Debug.LogError($"[ACTION] 0xA0 received (unexpected) target={targetEntityID}");
                    }
                    else if (actionType == 0x50) // BehaviourActionUseTarget (melee/Lightning)
                    {
                        // UseTarget has DIFFERENT format than Activate!
                        byte manipulatorId = sessionID;
                        byte useFlags = (byte)(targetEntityID & 0xFF);
                        byte targetIdLow = (byte)((targetEntityID >> 8) & 0xFF);
                        byte targetIdHigh = reader.ReadByte();
                        ushort actualTargetId = (ushort)(targetIdLow | (targetIdHigh << 8));
                        var gnomeManager = BlingGnomeManager.Instance;
                        bool isBlingGnomeTarget = gnomeManager.TryResolveGnomeTarget(conn, actualTargetId,
                            out uint gnomeEntityId, out ushort gnomeBehaviorId, out bool gnomeBootstrapped, out string gnomeTargetReason);
                        Combat.Monster actionTargetMonster = isBlingGnomeTarget ? null : Combat.CombatManager.Instance.FindMonsterForTarget(actualTargetId, conn.PlayerPosX, conn.PlayerPosY);
                        TryConsumeClientSyncSuffix(conn, reader, "ACTION-0x50-SYNC", actionTargetMonster, out bool acceptedActionMonsterHP);

                        Debug.LogError($"[ATTACK] 0x50: componentId={componentId}, manipulatorId={manipulatorId}, flags={useFlags}, targetId={actualTargetId}, gnome={gnomeEntityId}, gnomeBehavior={gnomeBehaviorId}, gnomeBootstrapped={gnomeBootstrapped}, gnomeMatch={gnomeTargetReason}");
                        if (isBlingGnomeTarget)
                        {
                            if (componentId != 0)
                                conn.UnitBehaviorId = componentId;

                            var msg = new LEWriter();
                            msg.WriteByte(0x07);
                            msg.WriteByte(0x35);
                            msg.WriteUInt16(componentId);
                            msg.WriteByte(0x01);
                            msg.WriteByte(responseId);
                            msg.WriteByte(0x50);
                            msg.WriteByte(manipulatorId);
                            msg.WriteByte(useFlags);
                            msg.WriteUInt16(actualTargetId);
                            const SyncContext actionResponseContext = SyncContext.PlayerActionResponse;
                            const string actionResponseSyncTag = "PlayerActionResponse";
                            if (!TryWriteEntitySynchForComponent(conn, msg, componentId, 0x01, actionResponseContext, actionResponseSyncTag, true))
                            {
                                Debug.LogError($"[GNOME-ACTIVATE] failed ActionResponse sync: component={componentId} target={actualTargetId} flags={useFlags}; sending release fallback");
                                ClearUseTargetAndReleaseControl(conn, "GNOME-ACTIVATE-sync-failed", componentId);
                                return;
                            }
                            msg.WriteByte(0x06);
                            bool actionResponseSent = SendCompressedA(conn, 0x01, 0x0F, msg.ToArray(), actionResponseContext, actionResponseSyncTag);

                            bool activated = false;
                            try
                            {
                                activated = gnomeManager.ActivateGnome(conn, actualTargetId);
                                Debug.LogError($"[GNOME-ACTIVATE] UseTarget target={actualTargetId} manip={manipulatorId} flags={useFlags} component={componentId} sent={actionResponseSent} activated={activated}");
                            }
                            catch (Exception ex)
                            {
                                Debug.LogError($"[GNOME-ACTIVATE] exception target={actualTargetId} component={componentId}: {ex}");
                            }

                            if (!actionResponseSent)
                            {
                                ClearUseTargetAndReleaseControl(conn, "GNOME-ACTIVATE-send-failed", componentId);
                                return;
                            }

                            if (!activated)
                                Debug.LogError($"[GNOME-ACTIVATE] UseTarget target={actualTargetId} did not start conversion");
                        }
                        else if (componentId >= 50000 && componentId < 60000)
                        {
                            Debug.LogError($"[ATTACK] >>> MONSTER->PLAYER! Monster component={componentId}, target player={actualTargetId}");
                            var attackingMonster = Combat.CombatManager.Instance.GetMonsterByComponent(componentId);
                            if (attackingMonster != null)
                                Debug.LogError($"[ATTACK] Monster {attackingMonster.Name} attacking player {actualTargetId}");
                            else
                                Debug.LogError($"[ATTACK] WARNING: No monster found for component {componentId}");
                        }
                        else
                        {
                            if (componentId != 0)
                                conn.UnitBehaviorId = componentId;
                            Debug.LogError($"[ATTACK] >>> PLAYER UseTarget! component={componentId}, target={actualTargetId}, manip={manipulatorId}, flags={useFlags}");
                            bool handled = false;
                            try
                            {
                                var monster = actionTargetMonster ?? Combat.CombatManager.Instance.FindMonsterForTarget(actualTargetId, conn.PlayerPosX, conn.PlayerPosY);
                                if (monster != null)
                                {
                                    HandlePlayerAttackMonster(conn, componentId, responseId, manipulatorId, useFlags, actualTargetId, monster, acceptedActionMonsterHP);
                                    handled = true;
                                }
                                else
                                {
                                    Debug.LogError($"[ATTACK] No monster for target {actualTargetId}");
                                }
                            }
                            catch (Exception ex)
                            {
                                Debug.LogError($"[ATTACK] EXCEPTION: {ex.Message}\n{ex.StackTrace}");
                            }

                            if (!handled)
                            {
                                var unresolvedMonster = Combat.CombatManager.Instance.GetMonster(actualTargetId)
                                                       ?? Combat.CombatManager.Instance.GetMonsterByComponent(actualTargetId);
                                if (unresolvedMonster != null)
                                {
                                    uint unresolvedHP = Combat.CombatManager.Instance.PeekMonsterCurrentHPWire(unresolvedMonster);
                                    bool deadUseTarget = !unresolvedMonster.IsAlive || unresolvedMonster.CurrentHPWire == 0 || unresolvedHP == 0 || _finalizedMonsterKills.Contains((uint)actualTargetId);
                                    Debug.LogError($"[ATTACK] Unresolved UseTarget target={actualTargetId} alive={unresolvedMonster.IsAlive} hp={unresolvedMonster.CurrentHPWire} resolvedHP={unresolvedHP} dead={deadUseTarget}");
                                    if (deadUseTarget)
                                    {
                                        bool sent = SendUseTargetActionResponse(conn, componentId, responseId, manipulatorId, useFlags, actualTargetId, SyncContext.PlayerActionResponse, "PlayerActionResponse", "dead-target");
                                        if (!sent)
                                            Debug.LogError($"[ATTACK] failed dead-target ActionResponse target={actualTargetId} component={componentId} flags={useFlags}");
                                        ClearUseTargetAndReleaseControl(conn, "ATTACK-dead-target", componentId, true, false);
                                    }
                                    else
                                    {
                                        var msg = new LEWriter();
                                        msg.WriteByte(0x07);
                                        msg.WriteByte(0x35);
                                        msg.WriteUInt16(componentId);
                                        msg.WriteByte(0x01);
                                        msg.WriteByte(responseId);
                                        msg.WriteByte(0x50);
                                        msg.WriteByte(manipulatorId);
                                        msg.WriteByte(useFlags);
                                        msg.WriteUInt16(actualTargetId);
                                        WritePlayerEntitySynch(conn, msg);
                                        msg.WriteByte(0x06);
                                        SendCompressedA(conn, 0x01, 0x0F, msg.ToArray());
                                        Debug.LogError($"[ATTACK] <<< Sent unresolved live-target ActionResponse target={actualTargetId} alive={unresolvedMonster.IsAlive} hp={unresolvedMonster.CurrentHPWire}");
                                        ClearUseTargetAndReleaseControl(conn, "ATTACK-unresolved-live-target", componentId);
                                    }
                                }
                                else
                                {
                                    if (_finalizedMonsterKills.Contains((uint)actualTargetId))
                                    {
                                        bool sent = SendUseTargetActionResponse(conn, componentId, responseId, manipulatorId, useFlags, actualTargetId, SyncContext.PlayerActionResponse, "PlayerActionResponse", "finalized-dead-target");
                                        if (!sent)
                                            Debug.LogError($"[ATTACK] failed finalized dead-target ActionResponse target={actualTargetId} component={componentId} flags={useFlags}");
                                        ClearUseTargetAndReleaseControl(conn, "ATTACK-finalized-target-missing", componentId, true, false);
                                    }
                                    else
                                    {
                                        var msg = new LEWriter();
                                        msg.WriteByte(0x07);
                                        msg.WriteByte(0x35);
                                        msg.WriteUInt16(componentId);
                                        msg.WriteByte(0x01);
                                        msg.WriteByte(responseId);
                                        msg.WriteByte(0x50);
                                        msg.WriteByte(manipulatorId);
                                        msg.WriteByte(useFlags);
                                        msg.WriteUInt16(actualTargetId);
                                        WritePlayerEntitySynch(conn, msg);
                                        msg.WriteByte(0x06);
                                        SendCompressedA(conn, 0x01, 0x0F, msg.ToArray());
                                        Debug.LogError($"[ATTACK] <<< Sent fallback ActionResponse target={actualTargetId}");
                                        ClearUseTargetAndReleaseControl(conn, "ATTACK-fallback-target-missing", componentId);

                                        // MULTIPLAYER: Still broadcast swing animation even when monster not found
                                        BroadcastMeleeAttack(conn, responseId, manipulatorId, useFlags);
                                    }
                                }
                            }
                        }
                    }
                    else if (actionType == 0x51) // BehaviourActionUsePosition (Fire Bolt, etc.)
                    {
                        // Rainbow server format: after header, reads actionID(1) + posX(4) + posY(4) + posZ(4)
                        // Our header already consumed targetEntityID (2 bytes of that 13).
                        // Read remaining 11 bytes of position data.
                        byte manipulatorId = sessionID;
                        byte actionID = (byte)(targetEntityID & 0xFF);
                        byte posXByte0 = (byte)((targetEntityID >> 8) & 0xFF);
                        byte[] posRemain = reader.Remaining >= 11 ? reader.ReadBytes(11) : reader.ReadBytes(reader.Remaining);

                        // Reconstruct position from bytes
                        int posX = 0, posY = 0, posZ = 0;
                        if (posRemain.Length >= 11)
                        {
                            posX = posXByte0 | (posRemain[0] << 8) | (posRemain[1] << 16) | (posRemain[2] << 24);
                            posY = posRemain[3] | (posRemain[4] << 8) | (posRemain[5] << 16) | (posRemain[6] << 24);
                            posZ = posRemain[7] | (posRemain[8] << 8) | (posRemain[9] << 16) | (posRemain[10] << 24);
                        }
                        float fPosX = posX / 256f;
                        float fPosY = posY / 256f;
                        float fPosZ = posZ / 256f;
                        Debug.LogError($"[SPELL-0x51] UsePosition: manip={manipulatorId} actionID={actionID} pos=({fPosX:F1},{fPosY:F1},{fPosZ:F1})");

                        PlayerState state = componentId < 50000 ? GetPlayerState(conn.ConnId.ToString()) : null;
                        var resolvedSpell = state != null ? ResolveActionSpell(conn, state, actionID) : null;
                        if (resolvedSpell != null && IsActiveSkillBusy(conn, componentId, actionID, resolvedSpell, out float skillBusyRemaining))
                        {
                            Debug.LogError($"[SPELL-BUSY] UsePosition native-overlap actionID={actionID} spell={resolvedSpell.DisplayName ?? resolvedSpell.SkillId ?? "UNKNOWN"} remaining={skillBusyRemaining:F3}s accepting request");
                        }

                        // Rainbow response format: 0x35 + cid + 0x01 + responseId + 0x51 + sessionID + actionID + pos + sync
                        // Via MessageQueue (no 0x07/0x06 wrappers)
                        var msg = new LEWriter();
                        msg.WriteByte(0x35);
                        msg.WriteUInt16(componentId);
                        msg.WriteByte(0x01);              // ActionResponse
                        msg.WriteByte(responseId);
                        msg.WriteByte(0x51);              // UsePosition (HAS sessionID per Rainbow)
                        msg.WriteByte(manipulatorId);     // sessionID
                        msg.WriteByte(actionID);          // echo actionID
                        msg.WriteUInt32((uint)posX);      // echo posX
                        msg.WriteUInt32((uint)posY);      // echo posY
                        msg.WriteUInt32((uint)posZ);      // echo posZ
                        if (!TryWriteEntitySynchForComponent(conn, msg, componentId, 0x01, SyncContext.PlayerActionResponse, "PlayerActionResponse", false))
                        {
                            Debug.LogError($"[SPELL-0x51] failed ActionResponse sync: component={componentId} actionID={actionID}");
                            return;
                        }
                        ClearZoneSpawnInvulnerability(conn, $"ACTION-0x{actionType:X2}");
                        conn.MessageQueue.Enqueue(msg.ToArray());
                        StartActiveSkillBusy(conn, componentId, actionID, resolvedSpell);
                        Debug.LogError($"[SPELL-0x51] <<< Sent ActionResponse via MessageQueue");

                        // MULTIPLAYER: Relay spell cast to other players
                        BroadcastSpellCast(conn, responseId, manipulatorId, actionID, posX, posY, posZ);

                        // Server-side damage tracking
                        if (componentId < 50000)
                        {
                            if (state != null)
                            {
                                // Try to resolve actionID as a slot ID for spell lookup
                                Debug.LogError($"[SPELL-0x51] actionID={actionID} → {resolvedSpell?.DisplayName ?? "NOT RESOLVED"} | sessionCtr={manipulatorId} pos=({fPosX:F1},{fPosY:F1})");

                                if (!IsSpellPositionWithinServerRange(conn, resolvedSpell, fPosX, fPosY, out float positionDistance, out float positionRange))
                                {
                                    Debug.LogError($"[SPELL-0x51] Aim outside range: {resolvedSpell?.DisplayName ?? "UNKNOWN"} dist={positionDistance:F1} range={positionRange:F1} pos=({fPosX:F1},{fPosY:F1})");
                                }
                                else
                                {
                                    var nearest = ResolvePositionSpellTarget(conn, resolvedSpell, fPosX, fPosY, out float projectileHitDistance);
                                    if (resolvedSpell != null && resolvedSpell.ProjectileSize > 0f && resolvedSpell.ProjectileSpeed > 0f)
                                    {
                                        if (nearest != null && nearest.IsAlive)
                                            nearest.UseTargetCount++;
                                        float startX = conn.PlayerPosX;
                                        float startY = conn.PlayerPosY;
                                        float hitHint = nearest != null && nearest.IsAlive
                                            ? projectileHitDistance
                                            : 0f;
                                        var pending = CreatePendingSpellProjectile(conn, state, nearest, resolvedSpell, actionID, actionID, componentId, startX, startY, fPosX, fPosY, nearest == null || !nearest.IsAlive, hitHint);
                                        _pendingSpells.Enqueue(pending);
                                        Debug.LogError($"[SPELL-0x51] Queued projectile runtime spell={resolvedSpell?.DisplayName ?? resolvedSpell?.SkillId ?? "UNKNOWN"} slotId={actionID} initialTarget={(nearest != null ? nearest.Name + "#" + nearest.EntityId.ToString() : "none")} delay={pending.ProjectileDelay:F3}s hitHint={pending.ProjectileHitDistance:F2} speed={pending.ProjectileSpeed:F1} step={pending.StepDistance:F3} initPreStep={pending.InitialDistance:F3} maxDist={pending.MaxDistance:F2} seq={pending.Sequence}");
                                    }
                                    else
                                    {
                                        if (nearest != null && nearest.IsAlive)
                                        {
                                            nearest.UseTargetCount++;
                                            float projectileDelay = ResolveProjectileImpactDelay(resolvedSpell, projectileHitDistance);
                                            float dueTime = GetNativeCombatNow() + projectileDelay;
                                            _pendingSpells.Enqueue(new PendingSpell { Conn = conn, State = state, Monster = nearest, Spell = resolvedSpell, ManipId = actionID, UseFlags = actionID, ComponentId = componentId, StartX = conn.PlayerPosX, StartY = conn.PlayerPosY, AimX = fPosX, AimY = fPosY, DueTime = dueTime, ProjectileHitDistance = projectileHitDistance, ProjectileDelay = projectileDelay });
                                            Debug.LogError($"[SPELL-0x51] Queued damage on {nearest.Name} slotId={actionID} delay={projectileDelay:F3}s hitDist={projectileHitDistance:F2} speed={resolvedSpell?.ProjectileSpeed ?? 0f:F1}");
                                        }
                                        else
                                        {
                                            Debug.LogError($"[SPELL-0x51] No target for non-projectile spell={resolvedSpell?.DisplayName ?? resolvedSpell?.SkillId ?? "UNKNOWN"} slotId={actionID} aim=({fPosX:F1},{fPosY:F1})");
                                        }
                                    }
                                }
                            }
                        }
                    }
                    else
                    {
                        // Unknown action type — log only, don't send response
                        Debug.LogError($"[ACTION] Unhandled actionType=0x{actionType:X2} target={targetEntityID}");
                    }

                    // ── READ SYNC SUFFIX ──
                    // Binary: 0x5DD840 — every ComponentUpdate ends with [syncFlags] [optional HP]
                    // 0x51 already consumed its position bytes + sync above, so only 0x50 hits this
                    if (reader.Remaining >= 1)
                    {
                        TryConsumeClientSyncSuffix(conn, reader, "ACTION-SYNC");
                    }

                }
                else if (subMessage == 0x64)
                {
                    // Client responding to our FollowClient message
                    Debug.LogError($"[COMPONENT] Client sent 0x64 response - consuming data");
                    HandleClientControlResponse(conn, reader, componentId);
                }
                else if ((subMessage == 0x35 || subMessage == 0x36))
                {
                    string connKey = conn.ConnId.ToString();
                    SavedCharacter savedChar = null;
                    if (conn.LoginName != null && _selectedCharacter.ContainsKey(conn.LoginName))
                        savedChar = CharacterRepository.GetCharacter(_selectedCharacter[conn.LoginName].Id);
                    if (savedChar == null) { while (reader.Remaining > 0) reader.ReadByte(); return; }
                    if (savedChar.hotbarSlots == null) savedChar.hotbarSlots = new List<HotbarSlotEntry>();
                    if (!_playerManipMap.ContainsKey(connKey)) _playerManipMap[connKey] = new Dictionary<uint, string>();

                    if (subMessage == 0x36 && reader.Remaining >= 4)
                    {
                        uint slot = reader.ReadUInt32();
                        Debug.LogError($"[HOTBAR] REMOVE slot {slot}");
                        string removedSkill = null;
                        if (_playerManipMap[connKey].ContainsKey(slot))
                        {
                            removedSkill = _playerManipMap[connKey][slot];
                            _playerManipMap[connKey].Remove(slot);
                        }
                        var removedSlotEntry = savedChar.hotbarSlots.FirstOrDefault(h => h.slot == slot);
                        if (removedSkill == null && removedSlotEntry != null)
                            removedSkill = removedSlotEntry.skill;
                        savedChar.hotbarSlots.RemoveAll(h => h.slot == slot);
                        if (removedSkill != null)
                            savedChar.hotbarSlots.RemoveAll(h => string.Equals(h.skill, removedSkill, StringComparison.OrdinalIgnoreCase));
                        CharacterRepository.SaveCharacter(savedChar);
                        if (IsPassiveSkill(removedSkill))
                            RecalculateHotbarPassiveBonuses(conn, savedChar);
                        Debug.LogError($"[HOTBAR] Saved remove: slot {slot}, was '{removedSkill}'");

                        // ═══ Bling Gnome: despawn when skill is removed from tray ═══
                        if (removedSkill != null &&
                            (removedSkill.IndexOf("BlingGnome", StringComparison.OrdinalIgnoreCase) >= 0 ||
                             removedSkill.IndexOf("SummonBling", StringComparison.OrdinalIgnoreCase) >= 0))
                        {
                            // Only despawn if BlingGnome is no longer on ANY hotbar slot
                            bool stillOnBar = savedChar.hotbarSlots.Any(h =>
                                h.skill.IndexOf("BlingGnome", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                h.skill.IndexOf("SummonBling", StringComparison.OrdinalIgnoreCase) >= 0);
                            if (!stillOnBar && BlingGnomeManager.Instance.HasGnome(conn.ConnId))
                            {
                                Debug.LogError($"[HOTBAR] BlingGnome removed from tray - despawning for {conn.LoginName}");
                                BlingGnomeManager.Instance.DespawnGnome(conn,
                                    (c, d, t, b) => SendCompressedA(c, d, t, b));
                            }
                        }

                        ushort manipCid = 0;
                        if (_playerManipulatorsIds.TryGetValue(connKey, out ushort mid))
                            manipCid = mid;
                        if (manipCid != 0 && removedSkill != null)
                        {
                            var pkt = new LEWriter();
                            pkt.WriteByte(0x07);
                            pkt.WriteByte(0x35);
                            pkt.WriteUInt16(manipCid);
                            pkt.WriteByte(0x01);                // subMsg = Remove
                            pkt.WriteUInt32(slot);              // manipulatorId (= slot ID) to remove
                            WritePlayerEntitySynch(conn, pkt);
                            pkt.WriteByte(0x06);
                            SendCompressedE(conn, pkt.ToArray());
                            Debug.LogError($"[HOTBAR-MANIP] Sent Remove slot={slot} '{removedSkill}'");
                        }
                    }
                    else if (subMessage == 0x35 && reader.Remaining >= 9)
                    {
                        uint slot = reader.ReadUInt32();
                        byte typeFlag = reader.ReadByte();
                        uint gcHash = reader.ReadUInt32();
                        Debug.LogError($"[HOTBAR] PLACE slot {slot} hash=0x{gcHash:X8}");

                        string skillGcClass = null;
                        if (_skillHashToGcClass.TryGetValue(gcHash, out string hr))
                            skillGcClass = hr;
                        if (skillGcClass == null)
                            foreach (var kv in _playerManipMap[connKey])
                            {
                                uint h = 5381;
                                foreach (char c in kv.Value.ToLower()) h = ((h << 5) + h) + (uint)c;
                                if (h == gcHash) { skillGcClass = kv.Value; break; }
                            }

                        if (skillGcClass != null)
                        {
                            string displacedSkill = null;
                            if (_playerManipMap[connKey].ContainsKey(slot))
                            {
                                string existing = _playerManipMap[connKey][slot];
                                if (!string.Equals(existing, skillGcClass, StringComparison.OrdinalIgnoreCase))
                                    displacedSkill = existing;
                            }
                            uint? oldSlot = null;
                            foreach (var kv in _playerManipMap[connKey])
                                if (string.Equals(kv.Value, skillGcClass, StringComparison.OrdinalIgnoreCase) && kv.Key != slot)
                                { oldSlot = kv.Key; break; }

                            if (oldSlot.HasValue) _playerManipMap[connKey].Remove(oldSlot.Value);
                            if (displacedSkill != null) _playerManipMap[connKey].Remove(slot);
                            _playerManipMap[connKey][slot] = skillGcClass;

                            savedChar.hotbarSlots.RemoveAll(h => h.slot == slot || string.Equals(h.skill, skillGcClass, StringComparison.OrdinalIgnoreCase));
                            if (displacedSkill != null)
                                savedChar.hotbarSlots.RemoveAll(h => string.Equals(h.skill, displacedSkill, StringComparison.OrdinalIgnoreCase));
                            savedChar.hotbarSlots.Add(new HotbarSlotEntry { slot = slot, skill = skillGcClass });
                            CharacterRepository.SaveCharacter(savedChar);
                            if (IsPassiveSkill(skillGcClass) || IsPassiveSkill(displacedSkill))
                                RecalculateHotbarPassiveBonuses(conn, savedChar);
                            Debug.LogError($"[HOTBAR] Saved: slot {slot} = '{skillGcClass}' displaced='{displacedSkill}' oldSlot={oldSlot}");

                            // ═══ Bling Gnome: spawn immediately when skill hits the tray ═══
                            if (skillGcClass.IndexOf("BlingGnome", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                skillGcClass.IndexOf("SummonBling", StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                BlingGnomeManager.Instance.SetServer(this);
                                if (!BlingGnomeManager.Instance.HasGnome(conn.ConnId))
                                {
                                    Debug.LogError($"[HOTBAR] BlingGnome placed on tray - spawning for {conn.LoginName}");
                                    BlingGnomeManager.Instance.SpawnGnome(conn,
                                        (c, d, t, b) => SendCompressedA(c, d, t, b),
                                        (c, m) => SendSystemMessage(c, m));
                                }
                            }
                            // If BlingGnome was displaced by this new skill, despawn it
                            else if (displacedSkill != null &&
                                (displacedSkill.IndexOf("BlingGnome", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                 displacedSkill.IndexOf("SummonBling", StringComparison.OrdinalIgnoreCase) >= 0))
                            {
                                bool stillOnBar = savedChar.hotbarSlots.Any(h =>
                                    h.skill.IndexOf("BlingGnome", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                    h.skill.IndexOf("SummonBling", StringComparison.OrdinalIgnoreCase) >= 0);
                                if (!stillOnBar && BlingGnomeManager.Instance.HasGnome(conn.ConnId))
                                {
                                    Debug.LogError($"[HOTBAR] BlingGnome displaced from tray - despawning for {conn.LoginName}");
                                    BlingGnomeManager.Instance.DespawnGnome(conn,
                                        (c, d, t, b) => SendCompressedA(c, d, t, b));
                                }
                            }

                            ushort manipCid = 0;
                            if (_playerManipulatorsIds.TryGetValue(connKey, out ushort mid))
                                manipCid = mid;

                            if (manipCid != 0)
                            {
                                byte skillLv = (byte)savedChar.GetSkillLevel(skillGcClass);

                                var pkt = new LEWriter();
                                pkt.WriteByte(0x07);
                                pkt.WriteByte(0x35);
                                pkt.WriteUInt16(manipCid);
                                pkt.WriteByte(0x00);                                // subMsg = Add
                                pkt.WriteByte(0xFF);
                                pkt.WriteCString(skillGcClass.ToLower());
                                pkt.WriteUInt32(slot);
                                pkt.WriteByte(skillLv);
                                WritePlayerEntitySynch(conn, pkt);
                                pkt.WriteByte(0x06);
                                SendCompressedE(conn, pkt.ToArray());
                                Debug.LogError($"[HOTBAR-MANIP] Sent Add '{skillGcClass}' slot={slot} lv={skillLv} manipCid=0x{manipCid:X4}");
                            }
                        }
                        else
                        {
                            Debug.LogError($"[HOTBAR] Could not resolve hash 0x{gcHash:X8} to any known skill");
                        }
                    }
                    else { while (reader.Remaining > 0) reader.ReadByte(); }
                }
                else if (subMessage == 0x21 || subMessage == 0x22 || subMessage == 0x23 || subMessage == 0x25 || subMessage == 0x26 || subMessage == 0x27 || subMessage == 0x28 || subMessage == 0x29)
                {
                    Debug.LogError($"[COMPONENT] Detected inventory/equipment operation 0x{subMessage:X2}");

                    string componentType = GetComponentType(conn.ConnId.ToString(), componentId);
                    Debug.LogError($"[COMPONENT-ROUTE] ComponentID 0x{componentId:X4} routed to: {componentType}");
                    if (componentType == "Equipment")
                    {
                        _equipmentHandler.HandleEquipmentUpdate(conn, reader, componentId, subMessage);
                    }
                    else if (componentType == "UnitContainer")
                    {
                        int unitContainerPayloadRemaining = reader.Remaining;
                        _inventoryHandler.HandleUnitContainerUpdate(conn, reader, componentId, subMessage);
                        if (subMessage == 0x22 && unitContainerPayloadRemaining == 0)
                        {
                            MerchantManager.FlushClientMerchantRefreshOnClientBoundary(conn, SendCompressedA);
                        }
                    }
                    else
                    {
                        Debug.LogError($"[COMPONENT-ROUTE] ❌ Unknown component type for ID 0x{componentId:X4}!");
                    }
                }
                else if (subMessage == 0x1E)
                {
                    bool isMerchant = false;
                    foreach (var kvp in _zoneNPCs)
                    {
                        foreach (var npc in kvp.Value)
                        {
                            if (npc.IsMerchant && npc.MerchantId == componentId)
                            {
                                isMerchant = true;
                                break;
                            }
                        }
                        if (isMerchant) break;
                    }

                    if (isMerchant)
                    {
                        // Debug: show raw bytes before reading
                        byte[] peek = reader.PeekRemaining();
                        Debug.LogError($"[MERCHANT] RAW BYTES (remaining {peek.Length}): {BitConverter.ToString(peek)}");

                        byte buyByte1 = reader.ReadByte();   // First byte of the 2-byte field
                        byte buyByte2 = reader.ReadByte();   // Second byte — possibly inventory index?
                        uint itemId = reader.ReadUInt32();    // ACTUAL item ID
                        Debug.LogError($"[MERCHANT] 🛒 BUY REQUEST! componentId=0x{componentId:X4}, byte1=0x{buyByte1:X2}({buyByte1}), byte2=0x{buyByte2:X2}({buyByte2}), itemId={itemId}");
                        MerchantManager.HandleBuyItem(conn, componentId, (ushort)itemId, _zoneNPCs, _selectedCharacter, SendCompressedA, this, buyByte1, buyByte2, IsPlayerFree(conn.LoginName));
                    }
                }
                else if (subMessage == 0x1F)
                {
                    bool isMerchant = false;
                    foreach (var kvp in _zoneNPCs)
                    {
                        foreach (var npc in kvp.Value)
                        {
                            if (npc.IsMerchant && npc.MerchantId == componentId)
                            {
                                isMerchant = true;
                                break;
                            }
                        }
                        if (isMerchant) break;
                    }

                    if (isMerchant)
                    {
                        byte[] sellPeek = reader.PeekRemaining();
                        Debug.LogError($"[MERCHANT] SELL RAW BYTES (remaining {sellPeek.Length}): {BitConverter.ToString(sellPeek)}");
                        ushort entityRef = reader.ReadUInt16();   // Entity ref for client's findItem
                        uint itemId = reader.ReadUInt32();        // Item handle
                        Debug.LogError($"[MERCHANT] 💰 SELL REQUEST! componentId=0x{componentId:X4}, entityRef=0x{entityRef:X4}, itemId={itemId}, remaining after read={reader.Remaining}");
                        MerchantManager.HandleSellItem(conn, componentId, (ushort)itemId, entityRef, _zoneNPCs, _selectedCharacter, SendCompressedA, GetPlayerState(conn.ConnId.ToString()), this, 0);
                        // Drain any remaining bytes to prevent stream desync
                        if (reader.Remaining > 0)
                        {
                            int drained = 0;
                            while (reader.Remaining > 0) { reader.ReadByte(); drained++; }
                            Debug.LogError($"[MERCHANT] Drained {drained} leftover sell bytes");
                        }
                    }
                }
                else
                {
                    // Check if this is a SkillTrainer component
                    ZoneNPC trainerNpc = null;
                    foreach (var kvp in _zoneNPCs)
                    {
                        foreach (var npc in kvp.Value)
                        {
                            if (npc.IsTrainer && npc.TrainerId == componentId)
                            {
                                trainerNpc = npc;
                                break;
                            }
                        }
                        if (trainerNpc != null) break;
                    }

                    if (trainerNpc != null)
                    {
                        byte[] trainerRaw = reader.PeekRemaining();
                        Debug.LogError($"[TRAINER] 🎓 SkillTrainer message! NPC={trainerNpc.Name} componentId=0x{componentId:X4} subMessage=0x{subMessage:X2} remaining={trainerRaw.Length} hex={BitConverter.ToString(trainerRaw)}");
                        HandleSkillTrainRequest(conn, reader, componentId, subMessage, trainerNpc);
                    }
                    else
                    {
                        // ═══════════════════════════════════════════════════════
                        // Check if this is a skill equip/unequip request (0x39)
                        // on the player's Skills component.
                        //
                        // Binary-verified: Skills::equipSkill @ 0x5419C0
                        //   Client sends subMessage 0x39 with:
                        //     - entityRef (0xFF + cstring skillGcClass)
                        //     - byte slotIndex (1-8 for equip, 0 for unequip)
                        //     - syncFlags + optional HP
                        //
                        // Without handling this, the unconsumed bytes corrupt the
                        // packet stream — every subsequent component update in the
                        // same frame gets misinterpreted (explains 0x22 with 0 bytes).
                        // ═══════════════════════════════════════════════════════
                        string skillConnKey = conn.ConnId.ToString();
                        ushort playerSkillsCid = 0;
                        _playerSkillsComponentId.TryGetValue(skillConnKey, out playerSkillsCid);

                        if (playerSkillsCid != 0 && componentId == playerSkillsCid && subMessage == 0x39)
                        {
                            byte[] rawData = reader.PeekRemaining();
                            Debug.LogError($"[SKILL-EQUIP] 0x39 on Skills cid=0x{componentId:X4} remaining={rawData.Length} hex={BitConverter.ToString(rawData)}");

                            // Parse request: entityRef (skill) + byte (slot index)
                            string skillGcClass = "";
                            byte slotByte = 0;
                            try
                            {
                                if (reader.Remaining > 0)
                                {
                                    byte refType = reader.ReadByte();
                                    if (refType == 0xFF && reader.Remaining > 0)
                                        skillGcClass = reader.ReadCString();
                                    else if (reader.Remaining >= 2)
                                    {
                                        // Entity ID ref (uint16) — less common
                                        ushort refId = reader.ReadUInt16();
                                        Debug.LogError($"[SKILL-EQUIP] EntityID ref: {refId}");
                                    }
                                }
                                if (reader.Remaining > 0)
                                    slotByte = reader.ReadByte();

                                // Consume sync suffix
                                if (reader.Remaining > 0)
                                {
                                    byte syncFlags = reader.ReadByte();
                                    if ((syncFlags & 0x02) != 0 && reader.Remaining >= 4)
                                        reader.ReadUInt32();
                                }
                            }
                            catch (Exception parseEx)
                            {
                                Debug.LogError($"[SKILL-EQUIP] Parse error: {parseEx.Message}");
                                // Drain remaining to prevent desync
                                while (reader.Remaining > 0) reader.ReadByte();
                            }

                            Debug.LogError($"[SKILL-EQUIP] Skill='{skillGcClass}' slot={slotByte}");

                            // Client already assigned the skill to the slot locally before
                            // sending this request. Do NOT send 0x38 processUpdateSkillSlot
                            // back — that function calls deactivate+reset on the slot which
                            // UNDOES the assignment. Just acknowledge silently.
                            Debug.LogError($"[SKILL-EQUIP] ✅ Accepted '{skillGcClass}' → slot {slotByte} (no response needed, client assigned locally)");
                        }
                        else if (subMessage == 0x07 && componentId == conn.QuestManagerId)
                        {
                            uint cpHash = 0;
                            if (reader.Remaining >= 1)
                            {
                                byte tag = reader.ReadByte();
                                if (tag == 0x04 && reader.Remaining >= 4) cpHash = reader.ReadUInt32();
                                else if (tag == 0x02 && reader.Remaining >= 2) cpHash = reader.ReadUInt16();
                                else if (tag == 0x01 && reader.Remaining >= 1) cpHash = reader.ReadByte();
                            }
                            while (reader.Remaining > 0) reader.ReadByte();

                            string destZone = null;
                            string connId = conn.ConnId.ToString();
                            var playerState = QuestManager.Instance.GetPlayerState(connId);
                            if (playerState != null)
                            {
                                foreach (var cpId in playerState.UnlockedCheckpoints)
                                {
                                    if (DatabaseLoader.ComputeDJB2Hash(cpId) == cpHash)
                                    {
                                        var cp = DatabaseLoader.Checkpoints.FirstOrDefault(c =>
                                            c.id.Equals(cpId, StringComparison.OrdinalIgnoreCase));
                                        if (cp != null)
                                            destZone = cp.zone;
                                        else if (_checkpointZoneMap.TryGetValue(cpId, out string mz))
                                            destZone = mz;
                                        Debug.LogError($"[CP-TELEPORT] Hash 0x{cpHash:X8} → '{cpId}' → zone '{destZone}'");
                                        break;
                                    }
                                }
                            }

                            if (!string.IsNullOrEmpty(destZone))
                            {
                                var zone = _zones.Values.FirstOrDefault(z =>
                                    z.name.Equals(destZone, StringComparison.OrdinalIgnoreCase));
                                if (zone != null)
                                {
                                    conn.PendingSpawnX = zone.spawnX;
                                    conn.PendingSpawnY = zone.spawnY;
                                    conn.PendingSpawnZ = zone.spawnZ;
                                }
                                ChangeZone(conn, destZone, "");
                            }
                            else
                            {
                                Debug.LogError($"[CP-TELEPORT] Hash 0x{cpHash:X8} not matched — fallback to rotator");
                                HandleObeliskTeleport(conn);
                            }
                        }
                        else if (subMessage == 0x0C && componentId == conn.QuestManagerId)
                        {
                            while (reader.Remaining > 0) reader.ReadByte();
                            if (!string.IsNullOrEmpty(conn.ZonePortalSource))
                            {
                                Debug.LogError($"[ZONE-PORTAL] Teleporting to '{conn.ZonePortalSource}'");
                                var zone = _zones.Values.FirstOrDefault(z =>
                                    z.name.Equals(conn.ZonePortalSource, StringComparison.OrdinalIgnoreCase));
                                if (zone != null)
                                {
                                    conn.PendingSpawnX = zone.spawnX;
                                    conn.PendingSpawnY = zone.spawnY;
                                    conn.PendingSpawnZ = zone.spawnZ;
                                }
                                ChangeZone(conn, conn.ZonePortalSource, "");
                            }
                            else
                                Debug.LogError("[ZONE-PORTAL] No zone portal source set");
                        }
                        else
                        {
                            Debug.LogError($"[COMPONENT] ⚠️ Unknown subMessage: 0x{subMessage:X2} cid=0x{componentId:X4}");
                            // CRITICAL: Drain remaining bytes to prevent stream desync!
                            // Without this, leftover bytes get interpreted as the next
                            // componentId+subMessage, corrupting everything downstream.
                            int drained = 0;
                            while (reader.Remaining > 0) { reader.ReadByte(); drained++; }
                            if (drained > 0)
                                Debug.LogError($"[COMPONENT] Drained {drained} bytes to prevent desync");
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Debug.LogError($"[COMPONENT] ERROR: {ex.Message}");
            }
        }

        /// <summary>
        /// Handle state machine updates from client for monsters.
        /// Binary-verified: StateMachine::ReadMessage @ 0x5F0C70 uses BITFIELD format:
        ///   flags(1) → bit1:msgType(u16) bit2:scope(u16) bit3:target(u16) bit5:value(u32) bit4:watchers
        /// Then EntitySynchInfo::ReadFromStream @ 0x5DD840:
        ///   syncFlags(1) → if bit1: HP(u32)
        /// 
        /// Unit::onDead sends SM messages 0x9D5 (2517) and 0x925 (2341) — DEATH SIGNALS.
        /// OLD BUG: reader.ReadBytes(reader.Remaining) ate the entire stream, destroying
        /// all subsequent messages including death notifications.
        /// </summary>
        /// <summary>
        /// Handle state machine updates from client for monsters.
        /// Component types read DIFFERENT amounts before sync suffix:
        ///   BehaviorId (offset 1): 1 byte toggle only
        ///   SkillsId (offset 2): full bitfield ReadMessage (where death 0x925/0x9D5 appears)
        ///   ManipulatorsId (offset 3): 1 byte
        /// Then EntitySynchInfo::ReadFromStream @ 0x5DD840: syncFlags(1) + optional HP(u32)
        /// </summary>
        private void HandleMonsterStateMachineUpdate(RRConnection conn, LEReader reader, ushort componentId)
        {
            if (reader.Remaining < 1) return;
            if (VerbosePacketLogging) Debug.LogError($"[MONSTER-SM-RAW] cid={componentId} offset={(componentId - 50000) % 6} remaining={reader.Remaining} hex={BitConverter.ToString(reader.PeekRemaining())}");

            int componentOffset = (componentId - 50000) % 6;

            ushort messageType = 0xFFFF;
            ushort scope = 0xFFFF;
            ushort target = 0;
            uint value = 0;
            byte flags = 0;

            if (componentOffset == 2) // SkillsId — StateMachine::ReadMessage bitfield format
            {
                flags = reader.ReadByte();
                if ((flags & 0x02) != 0 && reader.Remaining >= 2)
                    messageType = reader.ReadUInt16();
                if ((flags & 0x04) != 0 && reader.Remaining >= 2)
                    scope = reader.ReadUInt16();
                if ((flags & 0x08) != 0 && reader.Remaining >= 2)
                    target = reader.ReadUInt16();
                if ((flags & 0x20) != 0 && reader.Remaining >= 4)
                    value = reader.ReadUInt32();
                if ((flags & 0x10) != 0 && reader.Remaining >= 2)
                {
                    ushort wCount = reader.ReadUInt16();
                    for (int w = 0; w < wCount && reader.Remaining >= 2; w++)
                        reader.ReadUInt16();
                }
            }
            else if (componentOffset == 1) // BehaviorId — 1 byte toggle only
            {
                flags = reader.ReadByte();
            }
            else // ManipulatorsId, ModifiersId, etc
            {
                flags = reader.ReadByte();
            }

            // === PHASE 2: EntitySynchInfo::ReadFromStream (binary @ 0x5DD840) ===
            // Sync suffix follows state machine message — Phase 1 already consumed message fields.
            // This is JUST the EntitySynchInfo: bit 1 (0x02) = HP wire(uint32) follows.
            uint syncHP = 0;
            bool hasSyncHP = false;
            if (reader.Remaining >= 1)
            {
                byte syncFlags = reader.ReadByte();
                if (syncFlags != 0 && (syncFlags & 0x02) != 0 && reader.Remaining >= 4)
                {
                    syncHP = reader.ReadUInt32();
                    hasSyncHP = true;
                }
            }

            // === PHASE 3: Resolve monster and log ===
            string messageName = messageType switch
            {
                0 => "Halt",
                1 => "GoToPrevious",
                2 => "Go",
                3 => "Arrive",
                4 => "CheckDest",
                5 => "Wait/LeaveCombat",
                6 => "Timer",
                7 => "ReturnHome",
                8 => "CombatTick",
                9 => "AGGRO",
                10 => "SecondaryTarget",
                11 => "Forget",
                12 => "Fidget/GOAGGRO",
                13 => "CombatAck/ServerAggro",
                0x925 => "DEAD (0x925)",
                0x9D5 => "DEAD (0x9D5)",
                _ => $"Unknown(0x{messageType:X4})"
            };

            string hpStr = hasSyncHP ? $" HP={syncHP}({syncHP / 256})" : "";
            if (VerbosePacketLogging) Debug.LogError($"[MONSTER-SM] cid={componentId} offset={componentOffset} flags=0x{flags:X2} msg={messageType}({messageName}) scope={scope} target={target} value={value}{hpStr}");

            var monster = CombatManager.Instance.GetMonsterByComponent(componentId)
                       ?? CombatManager.Instance.GetMonsterByBehaviorId(componentId)
                       ?? CombatManager.Instance.GetMonsterBySkillsId(componentId)
                       ?? CombatManager.Instance.GetMonsterByManipulatorsId(componentId);

            if (monster == null)
            {
                if (VerbosePacketLogging) Debug.LogError($"[MONSTER-SM] No monster found for cid={componentId}");
                return;
            }

            // === PHASE 4: Update HP from sync suffix ===
            if (hasSyncHP)
            {
                uint clientHPWire = syncHP;
                CombatManager.Instance.ObserveClientMonsterHP(monster, clientHPWire, "MONSTER-SM-HP-0x64");
            }

            // === PHASE 5: Handle death messages from Unit::onDead ===
            if (messageType == 0x9D5 || messageType == 0x925)
            {
                Debug.LogError($"[MONSTER-DEATH] {monster.Name} DEATH SIGNAL msg=0x{messageType:X4} from client!");
                if (!_finalizedMonsterKills.Contains(monster.EntityId))
                {
                    TryFinalizeMonsterKill(conn, monster, $"DeathMsg-0x{messageType:X4}");
                }
                return;
            }

            // === PHASE 6: Handle combat state transitions ===
            if (messageType == 9)
            {
                if (VerbosePacketLogging) Debug.LogError($"[MONSTER-SM] {monster.Name} AGGRO! value={value} target={target}");
                uint targetId = target != 0 ? target : (uint)(conn.Avatar?.Id ?? 0);
                if (targetId != 0)
                {
                    CombatManager.Instance.EngageMonsterFromClientAction(monster, targetId);
                }
            }
            else if (messageType == 13)
            {
                if (VerbosePacketLogging) Debug.LogError($"[MONSTER-SM] CombatAck value={value} target={target}");
                monster.State = MonsterState.Combat;
                if (target != 0) monster.TargetId = target;
                uint roomSeed = CombatManager.Instance.IsRoomRngReady ? CombatManager.Instance.RoomSeed : 0u;
                Debug.LogError($"[RNG-SEED] Skipped CombatAck reseed for {monster.Name}#{monster.EntityId} target={target} current=0x{roomSeed:X8} ready={CombatManager.Instance.IsRoomRngReady}");
                try { ApplyMonsterDebuffs(conn, monster); } catch (Exception ex) { Debug.LogError($"[DEBUFF] Error: {ex.Message}"); }
            }
            else if (messageType == 10)
            {
                monster.State = MonsterState.Combat;
                if (target != 0) monster.TargetId = target;
                try { ApplyMonsterDebuffs(conn, monster); } catch (Exception ex) { Debug.LogError($"[DEBUFF] Error: {ex.Message}"); }
            }
            else if (messageType == 8)
            {
                try { ApplyMonsterDebuffs(conn, monster); } catch (Exception ex) { Debug.LogError($"[DEBUFF] Error: {ex.Message}"); }
            }
            else if (messageType == 12)
            {
                if (monster.TargetId == 0 && conn.Avatar != null)
                    monster.TargetId = (uint)conn.Avatar.Id;
                monster.State = MonsterState.Combat;
            }

        }


        public void SendAggroType9TCP(RRConnection conn, ushort componentId, uint targetEntityId)
        {
            if (!ResolveEntitySynchInfoForComponent(conn, componentId, 0x64, SyncContext.MonsterAction, 0, "TCP-AGGRO9", false, out EntitySynchInfoDecision decision))
                return;

            var writer = new LEWriter();
            writer.WriteByte(0x07);           // BeginStream
            writer.WriteByte(0x35);           // ComponentUpdate
            writer.WriteUInt16(componentId);
            writer.WriteByte(0x64);           // StateMachine message
            writer.WriteByte(0x03);           // flags = 0x03 (type + scope)
            writer.WriteUInt16(0x09);         // type 9 = AGGRO (uint16, NOT DWORD!)
            writer.WriteUInt16(0xFFFF);       // scope = GLOBAL (uint16, NOT DWORD!)
            writer.WriteUInt32(0);            // value
            writer.WriteUInt16((ushort)targetEntityId);
            if (!TryWriteResolvedEntitySynchInfo(writer, componentId, 0x64, SyncContext.MonsterAction, "TCP-AGGRO9", decision))
                return;
            writer.WriteByte(0x06);           // EndStream

            SendCompressedA(conn, 0x01, 0x0F, writer.ToArray(), SyncContext.MonsterAction, "TCP-AGGRO9");
        }

        public void SendSkillAttackUDP(RRConnection conn, ushort skillsComponentId, uint targetEntityId)
        {
            var session = GetUDPSessionForConnection(conn);
            if (session == null || !session.IsEstablished) return;
            if (!ResolveEntitySynchInfoForComponent(conn, skillsComponentId, 0x64, SyncContext.MonsterAction, 0, "UDP-SKILL", false, out EntitySynchInfoDecision decision))
                return;

            var writer = new LEWriter();
            writer.WriteByte(0x07);           // BeginStream
            writer.WriteByte(0x35);           // ComponentUpdate
            writer.WriteUInt16(skillsComponentId);
            writer.WriteByte(0x64);           // StateMachine message
            writer.WriteByte(0x03);           // flags = type + scope
            writer.WriteUInt16(0x08);         // Type 8 = CombatTick (TRIGGERS ATTACK!)
            writer.WriteUInt16(0xFFFF);       // scope = GLOBAL
            writer.WriteUInt32(0);            // value
            writer.WriteUInt16((ushort)targetEntityId);
            if (!TryWriteResolvedEntitySynchInfo(writer, skillsComponentId, 0x64, SyncContext.MonsterAction, "UDP-SKILL", decision))
                return;
            writer.WriteByte(0x06);           // EndStream
            byte[] packet = writer.ToArray();
            int padLen = (8 - (packet.Length % 8)) % 8;
            if (padLen > 0)
            {
                byte[] padded = new byte[packet.Length + padLen];
                Array.Copy(packet, padded, packet.Length);
                packet = padded;
            }
            SendEncryptedUDP(session, packet);
            Debug.LogError($"[UDP-SKILL] ⚔️ Sent Type 8 CombatTick to skillsId={skillsComponentId} target={targetEntityId}");
        }

        public void SendDespawnEntity(RRConnection conn, ushort entityId)
        {
            var writer = new LEWriter();
            writer.WriteByte(0x07);           // BeginStream
            writer.WriteByte(0x05);           // Despawn
            writer.WriteUInt16(entityId);     // Entity to remove
            writer.WriteByte(0x06);           // EndStream
            SendToClient(conn, writer.ToArray());
            Debug.LogError($"[DESPAWN] Sent despawn for entity {entityId}");
        }



        private void SendClientControlReset(RRConnection conn, ushort componentId)
        {
            Debug.LogError($"[CONTROL] SendClientControlReset componentId=0x{componentId:X4}");

            var msg = new LEWriter();
            msg.WriteByte(0x07);
            if (!WriteClientControlUpdate(conn, msg, componentId, false) ||
                !WriteClientControlUpdate(conn, msg, componentId, true))
            {
                Debug.LogError($"[CONTROL] Dropped client control reset componentId=0x{componentId:X4}");
                ScheduleClientControlResetRetry(conn, componentId, "write-blocked");
                return;
            }
            msg.WriteByte(0x06);

            SendCompressedA(conn, 0x01, 0x0F, msg.ToArray(), SyncContext.ControlAck, "CLIENT-CONTROL");
            ClearPendingClientControlReset(conn, componentId);
            Debug.LogError($"[CONTROL] Sent client control reset");
        }

        private void ScheduleClientControlResetRetry(RRConnection conn, ushort componentId, string reason)
        {
            if (conn == null || componentId == 0 || !conn.IsConnected) return;
            conn.PendingClientControlReset = true;
            conn.PendingClientControlResetComponentId = componentId;
            conn.PendingClientControlResetAttempts = (byte)Math.Min(255, conn.PendingClientControlResetAttempts + 1);
            float delay = conn.PendingClientControlResetAttempts <= 3 ? 0.10f : conn.PendingClientControlResetAttempts <= 10 ? 0.25f : 1.00f;
            conn.PendingClientControlResetNextAttemptTime = Time.time + delay;
            Debug.LogError($"[CONTROL] Scheduled client control reset retry componentId=0x{componentId:X4} attempt={conn.PendingClientControlResetAttempts} reason={reason} delay={delay:F2}");
        }

        private void ClearPendingClientControlReset(RRConnection conn, ushort componentId)
        {
            if (conn == null || !conn.PendingClientControlReset) return;
            if (componentId != 0 && conn.PendingClientControlResetComponentId != componentId) return;
            conn.PendingClientControlReset = false;
            conn.PendingClientControlResetComponentId = 0;
            conn.PendingClientControlResetNextAttemptTime = 0f;
            conn.PendingClientControlResetAttempts = 0;
        }

        private void FlushPendingClientControlResets()
        {
            foreach (var conn in _connections.Values)
            {
                if (conn == null || !conn.PendingClientControlReset) continue;
                if (!conn.IsConnected)
                {
                    ClearPendingClientControlReset(conn, 0);
                    continue;
                }
                if (Time.time < conn.PendingClientControlResetNextAttemptTime) continue;
                ushort componentId = conn.PendingClientControlResetComponentId;
                if (componentId == 0)
                {
                    ClearPendingClientControlReset(conn, 0);
                    continue;
                }
                Debug.LogError($"[CONTROL] Retrying pending client control reset componentId=0x{componentId:X4} attempt={conn.PendingClientControlResetAttempts}");
                SendClientControlReset(conn, componentId);
            }
        }

        private bool WriteClientControlUpdate(RRConnection conn, LEWriter writer, ushort componentId, bool followClient)
        {
            return WriteClientControlUpdate(conn, writer, componentId, followClient, "CLIENT-CONTROL", null);
        }

        private bool WriteClientControlUpdate(RRConnection conn, LEWriter writer, ushort componentId, bool followClient, string packetName, uint? forcedHPWire)
        {
            writer.WriteByte(0x35);
            writer.WriteUInt16(componentId);
            writer.WriteByte(0x64);
            writer.WriteByte(followClient ? (byte)0x01 : (byte)0x00);
            if (forcedHPWire.HasValue)
            {
                GetNativeValidationCutoff(out uint validationCutoffTick, out float validationCutoffTime);
                uint avatarEntityId = conn?.Avatar != null ? (uint)conn.Avatar.Id : 0u;
                return TryWriteResolvedEntitySynchInfo(writer, componentId, 0x64, SyncContext.ControlAck, packetName, EntitySynchInfoDecision.HP(EntitySynchInfoOwner.Avatar, forcedHPWire.Value, packetName, avatarEntityId, componentId, 0x64, GetNativeCombatNow(), $"forced-player-hp; validationCutoffTick={validationCutoffTick} validationCutoffTime={validationCutoffTime:F3}", validationCutoffTick, validationCutoffTime));
            }
            return TryWritePlayerEntitySynch(conn, writer, SyncContext.ControlAck, packetName, true, false);
        }



