                    "skills.generic.PoisonBlastRadius",
                    "skills.generic.PoisonDamageBuff",
                    "skills.generic.SummonMonsterBait",
                    "skills.generic.PoisonTrail",
                    "skills.generic.NoxiousShot",
                    "skills.generic.PoisonResistBuff",
