                writer.WriteByte((byte)savedChar.level);    // Use actual character level

                writer.WriteUInt16(0);
                Debug.LogError($"[OP12] After unk1: position {writer.Position}");
                writer.WriteUInt16(0);
                Debug.LogError($"[OP12] After unk2: position {writer.Position}");

